insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','medium','Sixteen teams are split into four groups of four, and in each group every team plays every other team once. The top two teams of each group then form a league of eight, in which every team plays every other team once -- except that two teams from the same group do not meet again. How many matches are played in all?','सोलह टीमें चार-चार के चार समूहों में बाँटी जाती हैं, और हर समूह में हर टीम हर दूसरी टीम से एक बार खेलती है। फिर हर समूह की शीर्ष दो टीमें आठ टीमों की एक लीग बनाती हैं, जिसमें हर टीम हर दूसरी टीम से एक बार खेलती है -- सिवाय इसके कि एक ही समूह की दो टीमें फिर नहीं भिड़तीं। कुल कितने मैच खेले जाते हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 1}'::jsonb,'[{"id": "a", "body": "48", "body_hi": "48", "isCorrect": true}, {"id": "b", "body": "52", "body_hi": "52", "isCorrect": false}, {"id": "c", "body": "56", "body_hi": "56", "isCorrect": false}, {"id": "d", "body": "96", "body_hi": "96", "isCorrect": false}]'::jsonb,2.5,0.83,'Each group plays 4C2 = 6 matches, so the groups play 4 × 6 = 24. The league of eight would have 8C2 = 28 matches, but the 4 pairs who came from the same group have already met, leaving 24. In all 24 + 24 = 48. 52 forgets that teams from the same group do not meet again; 96 counts every match twice, once for each team; 56 has no basis.','हर समूह 4C2 = 6 मैच खेलता है, इसलिए समूह 4 × 6 = 24 मैच खेलते हैं। आठ टीमों की लीग में 8C2 = 28 मैच होते, पर एक ही समूह से आए 4 जोड़े पहले ही भिड़ चुके हैं, इसलिए 24 बचते हैं। कुल 24 + 24 = 48। 52 भूल जाता है कि एक ही समूह की टीमें फिर नहीं भिड़तीं; 96 हर मैच को दो बार गिनता है, हर टीम के लिए एक बार; 56 का कोई आधार नहीं।','csat-l4-s04-qa-ph-a-league-that-follows-the-groups','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','medium','In the series 9, 18, 27, 36, ..., of multiples of 9, which is the first term whose digits do not add up to 9?','9 के गुणजों की श्रेणी 9, 18, 27, 36, ... में वह पहला पद कौन-सा है जिसके अंकों का योग 9 नहीं है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 2}'::jsonb,'[{"id": "a", "body": "99", "body_hi": "99", "isCorrect": true}, {"id": "b", "body": "108", "body_hi": "108", "isCorrect": false}, {"id": "c", "body": "117", "body_hi": "117", "isCorrect": false}, {"id": "d", "body": "189", "body_hi": "189", "isCorrect": false}]'::jsonb,2.5,0.83,'The digit sum of a multiple of 9 is always a multiple of 9, and for the two-digit terms 18 to 90 it is 9. The first term whose digits add up to more is 99, with digit sum 18. 108 and 117 come later and their digits add up to 9 again; 189 (digit sum 18) also comes later.','9 के किसी गुणज का अंक-योग हमेशा 9 का गुणज होता है, और 18 से 90 तक के दो अंकों वाले पदों के लिए वह 9 है। पहला पद जिसके अंकों का योग इससे अधिक है, 99 है, अंक-योग 18। 108 और 117 बाद में आते हैं और उनके अंकों का योग फिर 9 है; 189 (अंक-योग 18) भी बाद में आता है।','csat-l4-s04-qa-ss-the-first-multiple-of-9-whose-digits-do-not-add-to-9','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','Which one of the following numbers can be written as the sum of two positive cubes in two different ways?','निम्नलिखित में से किस संख्या को दो धनात्मक घनों के योग के रूप में दो अलग-अलग तरीक़ों से लिखा जा सकता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 3}'::jsonb,'[{"id": "a", "body": "1,000", "body_hi": "1,000", "isCorrect": false}, {"id": "b", "body": "1,728", "body_hi": "1,728", "isCorrect": false}, {"id": "c", "body": "1,729", "body_hi": "1,729", "isCorrect": true}, {"id": "d", "body": "1,730", "body_hi": "1,730", "isCorrect": false}]'::jsonb,2.5,0.83,'1,729 = 1³ + 12³ = 1 + 1,728, and also 9³ + 10³ = 729 + 1,000. It is the smallest number with this property, made famous by the mathematician Srinivasa Ramanujan. 1,000 = 10³ and 1,728 = 12³ are single cubes and not sums of two positive cubes; 1,730 = 1³ + 1³ + 12³ needs three cubes.','1,729 = 1³ + 12³ = 1 + 1,728, और 9³ + 10³ = 729 + 1,000 भी। यह इस गुण वाली सबसे छोटी संख्या है, जिसे गणितज्ञ श्रीनिवास रामानुजन ने प्रसिद्ध किया। 1,000 = 10³ और 1,728 = 12³ अकेले घन हैं, दो धनात्मक घनों के योग नहीं; 1,730 = 1³ + 1³ + 12³ के लिए तीन घन चाहिए।','csat-l4-s04-qa-nt-a-sum-of-two-cubes-in-two-ways','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','hard','Two engineers inspect an old bridge. One says it can safely carry lorries of up to 40 tonnes; the other says it cannot safely carry more than 10 tonnes. To be fair to both, the town council decides to allow lorries of up to 25 tonnes. Which one of the following best describes the flaw in the council''s reasoning?','दो अभियंता एक पुराने पुल की जाँच करते हैं। एक कहता है कि वह 40 टन तक के ट्रक सुरक्षित रूप से ढो सकता है; दूसरा कहता है कि वह 10 टन से अधिक सुरक्षित रूप से नहीं ढो सकता। दोनों के साथ न्याय करने के लिए नगर परिषद 25 टन तक के ट्रकों की अनुमति देने का निर्णय लेती है। निम्नलिखित में से कौन-सा परिषद के तर्क की त्रुटि का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 4}'::jsonb,'[{"id": "a", "body": "It assumes that the truth must lie halfway between two opposing claims.", "body_hi": "यह मान लेती है कि सत्य दो विरोधी दावों के ठीक बीच में ही होगा।", "isCorrect": true}, {"id": "b", "body": "It rejects the advice of both engineers merely because the two of them disagree.", "body_hi": "यह दोनों अभियंताओं की सलाह केवल इसलिए ठुकरा देती है कि दोनों असहमत हैं।", "isCorrect": false}, {"id": "c", "body": "It trusts the more experienced of the two engineers without giving any reason.", "body_hi": "यह बिना कोई कारण बताए दोनों में से अधिक अनुभवी अभियंता पर भरोसा कर लेती है।", "isCorrect": false}, {"id": "d", "body": "It treats the bridge''s safe record in the past as proof that it will stay safe.", "body_hi": "यह पुल के अतीत के सुरक्षित रिकॉर्ड को इस बात का प्रमाण मान लेती है कि वह सुरक्षित रहेगा।", "isCorrect": false}]'::jsonb,2.5,0.83,'Being fair to two people is not the same as being right about a bridge. The safe load is a fact about the bridge, and it need not lie midway between the two estimates: if the cautious engineer is right, 25 tonnes is two and a half times the safe load. The council should find out which estimate is correct, or keep to the lower one while it does. It does not reject both engineers -- it uses both figures; it prefers neither of them; and it says nothing about the bridge''s past record.','दो लोगों के साथ न्याय करना और किसी पुल के बारे में सही होना एक बात नहीं है। सुरक्षित भार पुल के बारे में एक तथ्य है, और उसका दोनों अनुमानों के बीच में होना आवश्यक नहीं: यदि सतर्क अभियंता सही है, तो 25 टन सुरक्षित भार का ढाई गुना है। परिषद को पता लगाना चाहिए कि कौन-सा अनुमान सही है, या तब तक निचले अनुमान पर टिके रहना चाहिए। वह दोनों अभियंताओं को ठुकराती नहीं -- वह दोनों के आँकड़ों का उपयोग करती है; वह किसी को वरीयता नहीं देती; और पुल के अतीत के रिकॉर्ड के बारे में कुछ नहीं कहती।','csat-l4-s04-lr-sc-a-safe-load-found-by-splitting-the-difference','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','statement_based','medium','Consider the five marks 3, 5, 5, 7 and 10. Which of the following statements is/are correct?','पाँच अंकों 3, 5, 5, 7 और 10 पर विचार कीजिए। निम्नलिखित में से कौन-सा/से कथन सही है/हैं?','{"statements": ["The mean of the marks is greater than their median.", "The median of the marks is equal to their mode."], "statements_hi": ["अंकों का माध्य उनकी माध्यिका से बड़ा है।", "अंकों की माध्यिका उनके बहुलक के बराबर है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 5}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are correct. The mean is 30 ÷ 5 = 6, and the median, the middle mark in order, is 5, so the mean is greater (1). The mode, the most frequent mark, is also 5, equal to the median (2). The single high mark of 10 pulls the mean above the middle.','दोनों सही हैं। माध्य 30 ÷ 5 = 6 है, और माध्यिका, क्रम में बीच का अंक, 5 है, इसलिए माध्य बड़ा है (1)। बहुलक, सबसे अधिक बार आने वाला अंक, भी 5 है, माध्यिका के बराबर (2)। 10 का अकेला ऊँचा अंक माध्य को बीच से ऊपर खींच लेता है।','csat-l4-s04-qa-rm-mean-median-and-mode','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1850 the French economist Frédéric Bastiat told the story of a shopkeeper whose son breaks a pane of glass. The onlookers console him: at least the glazier will have work, and the glazier will spend what he earns, giving work to others in turn. So, they conclude, the broken window is good for trade. Bastiat called this the error of seeing only what is seen. The six francs paid to the glazier are visible. What is not visible is the pair of shoes or the book the shopkeeper would have bought with the same money, and the work that purchase would have given the shoemaker or the bookseller. The town has not gained a job; it has moved one, and lost a window. The lesson reaches beyond broken glass. Whenever an activity is praised for the work it creates -- rebuilding after a disaster, or a scheme that pays people to dig holes and fill them in again -- it is worth asking what the same resources would otherwise have done. This does not mean that spending is never useful, only that its benefits must be weighed against what is given up.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1850 में फ़्रांसीसी अर्थशास्त्री फ़्रेडरिक बास्तियाँ ने एक दुकानदार की कथा सुनाई जिसका बेटा शीशे का एक पल्ला तोड़ देता है। देखने वाले उसे सांत्वना देते हैं: कम से कम शीशा लगाने वाले को काम मिलेगा, और वह अपनी कमाई ख़र्च करेगा, जिससे बदले में दूसरों को काम मिलेगा। इसलिए, वे निष्कर्ष निकालते हैं, टूटी खिड़की व्यापार के लिए अच्छी है। बास्तियाँ ने इसे केवल वही देखने की भूल कहा जो दिखाई देता है। शीशा लगाने वाले को दिए गए छह फ़्रैंक दिखाई देते हैं। जो दिखाई नहीं देता वह है जूतों की वह जोड़ी या वह पुस्तक जो दुकानदार उसी पैसे से ख़रीदता, और वह काम जो उस ख़रीद से मोची या पुस्तक-विक्रेता को मिलता। नगर ने कोई रोज़गार नहीं पाया; उसने एक रोज़गार को एक जगह से दूसरी जगह खिसकाया है, और एक खिड़की खो दी है। यह सीख टूटे शीशे से आगे तक जाती है। जब भी किसी गतिविधि की प्रशंसा उससे पैदा होने वाले काम के लिए की जाती है -- किसी आपदा के बाद पुनर्निर्माण, या कोई योजना जो लोगों को गड्ढे खोदने और फिर भरने के लिए पैसे देती है -- तो यह पूछना उचित है कि वही संसाधन अन्यथा क्या करते। इसका अर्थ यह नहीं कि ख़र्च कभी उपयोगी नहीं होता, केवल यह कि उसके लाभों को उस चीज़ के सामने तौला जाना चाहिए जिसे छोड़ा जाता है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p01", "csat_order": 6}'::jsonb,'[{"id": "a", "body": "Breaking and repairing things is good for an economy, because it creates work for those who repair them.", "body_hi": "चीज़ें तोड़ना और उनकी मरम्मत करना अर्थव्यवस्था के लिए अच्छा है, क्योंकि इससे मरम्मत करने वालों को काम मिलता है।", "isCorrect": false}, {"id": "b", "body": "Public spending never does any good, since it only moves jobs from one place in the economy to another.", "body_hi": "सार्वजनिक ख़र्च कभी कोई भलाई नहीं करता, क्योंकि वह केवल रोज़गार को अर्थव्यवस्था में एक जगह से दूसरी जगह खिसकाता है।", "isCorrect": false}, {"id": "c", "body": "The work an activity creates must be weighed against what the same resources would otherwise have done.", "body_hi": "किसी गतिविधि से पैदा होने वाले काम को इसके सामने तौलना चाहिए कि वही संसाधन अन्यथा क्या करते।", "isCorrect": true}, {"id": "d", "body": "Shopkeepers should take more care of their windows, because repairing broken glass is very expensive.", "body_hi": "दुकानदारों को अपनी खिड़कियों का अधिक ध्यान रखना चाहिए, क्योंकि टूटे शीशे की मरम्मत बहुत महँगी होती है।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage uses the broken window to show that the visible work an activity creates must be set against what the same money would otherwise have done, and it ends by saying that spending can be useful once that weighing is done. It rejects the claim that breaking things is good for trade; it says spending is not ''never useful'', so it does not condemn all spending; and the care of windows is not its subject.','परिच्छेद टूटी खिड़की के उदाहरण से दिखाता है कि किसी गतिविधि से पैदा होने वाले दिखाई देने वाले काम को इसके सामने रखना चाहिए कि वही पैसा अन्यथा क्या करता, और अंत में कहता है कि यह तौल कर लेने पर ख़र्च उपयोगी हो सकता है। वह इस दावे को ख़ारिज करता है कि चीज़ें तोड़ना व्यापार के लिए अच्छा है; वह कहता है कि ख़र्च ''कभी उपयोगी नहीं'' ऐसा नहीं, इसलिए वह हर ख़र्च की निंदा नहीं करता; और खिड़कियों की देखभाल उसका विषय नहीं है।','csat-l4-s04-rc-p01-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1850 the French economist Frédéric Bastiat told the story of a shopkeeper whose son breaks a pane of glass. The onlookers console him: at least the glazier will have work, and the glazier will spend what he earns, giving work to others in turn. So, they conclude, the broken window is good for trade. Bastiat called this the error of seeing only what is seen. The six francs paid to the glazier are visible. What is not visible is the pair of shoes or the book the shopkeeper would have bought with the same money, and the work that purchase would have given the shoemaker or the bookseller. The town has not gained a job; it has moved one, and lost a window. The lesson reaches beyond broken glass. Whenever an activity is praised for the work it creates -- rebuilding after a disaster, or a scheme that pays people to dig holes and fill them in again -- it is worth asking what the same resources would otherwise have done. This does not mean that spending is never useful, only that its benefits must be weighed against what is given up.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1850 में फ़्रांसीसी अर्थशास्त्री फ़्रेडरिक बास्तियाँ ने एक दुकानदार की कथा सुनाई जिसका बेटा शीशे का एक पल्ला तोड़ देता है। देखने वाले उसे सांत्वना देते हैं: कम से कम शीशा लगाने वाले को काम मिलेगा, और वह अपनी कमाई ख़र्च करेगा, जिससे बदले में दूसरों को काम मिलेगा। इसलिए, वे निष्कर्ष निकालते हैं, टूटी खिड़की व्यापार के लिए अच्छी है। बास्तियाँ ने इसे केवल वही देखने की भूल कहा जो दिखाई देता है। शीशा लगाने वाले को दिए गए छह फ़्रैंक दिखाई देते हैं। जो दिखाई नहीं देता वह है जूतों की वह जोड़ी या वह पुस्तक जो दुकानदार उसी पैसे से ख़रीदता, और वह काम जो उस ख़रीद से मोची या पुस्तक-विक्रेता को मिलता। नगर ने कोई रोज़गार नहीं पाया; उसने एक रोज़गार को एक जगह से दूसरी जगह खिसकाया है, और एक खिड़की खो दी है। यह सीख टूटे शीशे से आगे तक जाती है। जब भी किसी गतिविधि की प्रशंसा उससे पैदा होने वाले काम के लिए की जाती है -- किसी आपदा के बाद पुनर्निर्माण, या कोई योजना जो लोगों को गड्ढे खोदने और फिर भरने के लिए पैसे देती है -- तो यह पूछना उचित है कि वही संसाधन अन्यथा क्या करते। इसका अर्थ यह नहीं कि ख़र्च कभी उपयोगी नहीं होता, केवल यह कि उसके लाभों को उस चीज़ के सामने तौला जाना चाहिए जिसे छोड़ा जाता है।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["A town that is rebuilt after a disaster ends up better off than it was before the disaster struck.", "If the shopkeeper''s money would otherwise have lain idle, the passage''s case against the onlookers would be weaker."], "statements_hi": ["आपदा के बाद फिर से बनाया गया नगर अंततः आपदा से पहले की तुलना में बेहतर स्थिति में होता है।", "यदि दुकानदार का पैसा अन्यथा बेकार पड़ा रहता, तो देखने वालों के विरुद्ध परिच्छेद का तर्क कमज़ोर होता।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p01", "csat_order": 7}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is valid. The case against the onlookers rests on the purchase the shopkeeper would otherwise have made: the glazier''s job only replaces the shoemaker''s or the bookseller''s. If the money would have lain idle, nothing would have been displaced, and the claim that the town ''has not gained a job'' would lose its force (though the town would still have lost a window). 1 is the very error the passage describes: rebuilding after a disaster is praised for the work it creates while the loss itself and the uses the resources would otherwise have had are ignored.','केवल 2 वैध है। देखने वालों के विरुद्ध तर्क उस ख़रीद पर टिका है जो दुकानदार अन्यथा करता: शीशा लगाने वाले का काम केवल मोची या पुस्तक-विक्रेता के काम की जगह लेता है। यदि पैसा अन्यथा बेकार पड़ा रहता, तो कुछ भी विस्थापित न होता, और यह दावा कि नगर ने ''कोई रोज़गार नहीं पाया'' अपना बल खो देता (हालाँकि नगर फिर भी एक खिड़की खो चुका होता)। 1 ठीक वही भूल है जिसका परिच्छेद वर्णन करता है: आपदा के बाद पुनर्निर्माण की प्रशंसा उससे पैदा होने वाले काम के लिए की जाती है, जबकि स्वयं हानि और संसाधनों के अन्य संभावित उपयोग अनदेखे रह जाते हैं।','csat-l4-s04-rc-p01-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1850 the French economist Frédéric Bastiat told the story of a shopkeeper whose son breaks a pane of glass. The onlookers console him: at least the glazier will have work, and the glazier will spend what he earns, giving work to others in turn. So, they conclude, the broken window is good for trade. Bastiat called this the error of seeing only what is seen. The six francs paid to the glazier are visible. What is not visible is the pair of shoes or the book the shopkeeper would have bought with the same money, and the work that purchase would have given the shoemaker or the bookseller. The town has not gained a job; it has moved one, and lost a window. The lesson reaches beyond broken glass. Whenever an activity is praised for the work it creates -- rebuilding after a disaster, or a scheme that pays people to dig holes and fill them in again -- it is worth asking what the same resources would otherwise have done. This does not mean that spending is never useful, only that its benefits must be weighed against what is given up.

Which one of the following is an example of the error that the passage describes?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1850 में फ़्रांसीसी अर्थशास्त्री फ़्रेडरिक बास्तियाँ ने एक दुकानदार की कथा सुनाई जिसका बेटा शीशे का एक पल्ला तोड़ देता है। देखने वाले उसे सांत्वना देते हैं: कम से कम शीशा लगाने वाले को काम मिलेगा, और वह अपनी कमाई ख़र्च करेगा, जिससे बदले में दूसरों को काम मिलेगा। इसलिए, वे निष्कर्ष निकालते हैं, टूटी खिड़की व्यापार के लिए अच्छी है। बास्तियाँ ने इसे केवल वही देखने की भूल कहा जो दिखाई देता है। शीशा लगाने वाले को दिए गए छह फ़्रैंक दिखाई देते हैं। जो दिखाई नहीं देता वह है जूतों की वह जोड़ी या वह पुस्तक जो दुकानदार उसी पैसे से ख़रीदता, और वह काम जो उस ख़रीद से मोची या पुस्तक-विक्रेता को मिलता। नगर ने कोई रोज़गार नहीं पाया; उसने एक रोज़गार को एक जगह से दूसरी जगह खिसकाया है, और एक खिड़की खो दी है। यह सीख टूटे शीशे से आगे तक जाती है। जब भी किसी गतिविधि की प्रशंसा उससे पैदा होने वाले काम के लिए की जाती है -- किसी आपदा के बाद पुनर्निर्माण, या कोई योजना जो लोगों को गड्ढे खोदने और फिर भरने के लिए पैसे देती है -- तो यह पूछना उचित है कि वही संसाधन अन्यथा क्या करते। इसका अर्थ यह नहीं कि ख़र्च कभी उपयोगी नहीं होता, केवल यह कि उसके लाभों को उस चीज़ के सामने तौला जाना चाहिए जिसे छोड़ा जाता है।

निम्नलिखित में से कौन-सा उस भूल का उदाहरण है जिसका परिच्छेद वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p01", "csat_order": 8}'::jsonb,'[{"id": "a", "body": "Praising a road-widening plan for the jobs it creates without asking what else the money could have built", "body_hi": "सड़क चौड़ी करने की योजना की उसके रोज़गारों के लिए प्रशंसा, बिना पूछे कि उस पैसे से और क्या बनता", "isCorrect": true}, {"id": "b", "body": "Choosing the cheapest of three glaziers after comparing the prices that each of them charges for the work", "body_hi": "तीन शीशा लगाने वालों में से हर एक के दाम मिलाकर उनमें सबसे सस्ते को चुनना", "isCorrect": false}, {"id": "c", "body": "Refusing to have a broken window repaired until the person who broke it has paid the full cost of the repair", "body_hi": "टूटी खिड़की की मरम्मत तब तक न करवाना जब तक उसे तोड़ने वाला व्यक्ति मरम्मत का पूरा ख़र्च स्वयं न चुका दे", "isCorrect": false}, {"id": "d", "body": "Counting both the money to be spent on a project and the benefits that the project is expected to bring", "body_hi": "किसी परियोजना पर ख़र्च होने वाला पैसा और उससे मिलने वाले अपेक्षित लाभ, दोनों को गिनना", "isCorrect": false}]'::jsonb,2.5,0.83,'The error is to count the work an activity creates while ignoring what the same money would otherwise have paid for. Praising a road plan for its jobs without asking what else the money could have built does exactly that. Comparing three glaziers'' prices is ordinary prudence; insisting that the person responsible pays is about who bears a cost, not about unseen alternatives; and counting both the cost of a project and its benefits is the weighing the passage recommends.','भूल यह है कि किसी गतिविधि से पैदा होने वाले काम को गिना जाए और यह अनदेखा किया जाए कि वही पैसा अन्यथा किस चीज़ पर लगता। सड़क की किसी योजना की प्रशंसा उसके रोज़गारों के लिए करना, बिना यह पूछे कि उस पैसे से और क्या बन सकता था, ठीक यही करता है। तीन शीशा लगाने वालों के दाम मिलाना सामान्य समझदारी है; ज़िम्मेदार व्यक्ति से भुगतान पर ज़ोर देना इस बारे में है कि लागत कौन उठाए, अनदेखे विकल्पों के बारे में नहीं; और किसी परियोजना की लागत और उसके लाभ दोनों गिनना वही तौल है जिसकी परिच्छेद सलाह देता है।','csat-l4-s04-rc-p01-an-example-of-the-error','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','hard','The average age of an 8-member committee is the same today as it was 4 years ago, because in the meantime one member was replaced by a new one. How much younger is the new member than the member replaced (comparing their ages at the time of the change)?','8 सदस्यों वाली एक समिति की औसत आयु आज भी उतनी ही है जितनी 4 वर्ष पहले थी, क्योंकि इस बीच एक सदस्य की जगह एक नया सदस्य आया। नया सदस्य हटाए गए सदस्य से कितना छोटा है (बदलाव के समय उनकी आयु की तुलना करते हुए)?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 9}'::jsonb,'[{"id": "a", "body": "4 years", "body_hi": "4 वर्ष", "isCorrect": false}, {"id": "b", "body": "8 years", "body_hi": "8 वर्ष", "isCorrect": false}, {"id": "c", "body": "28 years", "body_hi": "28 वर्ष", "isCorrect": false}, {"id": "d", "body": "32 years", "body_hi": "32 वर्ष", "isCorrect": true}]'::jsonb,2.5,0.83,'In 4 years each of the 8 members would have grown 4 years older, raising the total age by 8 × 4 = 32 years and the average by 4. For the average to stay the same, the new member must have been 32 years younger than the one replaced. 4 years is the rise in the average, not in the total; 8 years and 28 years have no basis.','4 वर्षों में 8 में से हर सदस्य 4 वर्ष बड़ा हो जाता, जिससे कुल आयु 8 × 4 = 32 वर्ष और औसत 4 बढ़ता। औसत वही रहने के लिए नए सदस्य को हटाए गए सदस्य से 32 वर्ष छोटा होना चाहिए। 4 वर्ष औसत की वृद्धि है, कुल की नहीं; 8 वर्ष और 28 वर्ष का कोई आधार नहीं।','csat-l4-s04-qa-rm-a-committee-as-young-as-it-was','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','How many of the whole numbers from 1 to 100 can be written as the difference of two perfect squares (counting 0 as a perfect square)?','1 से 100 तक की कितनी पूर्ण संख्याओं को दो पूर्ण वर्गों के अंतर के रूप में लिखा जा सकता है (0 को पूर्ण वर्ग मानते हुए)?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 10}'::jsonb,'[{"id": "a", "body": "50", "body_hi": "50", "isCorrect": false}, {"id": "b", "body": "67", "body_hi": "67", "isCorrect": false}, {"id": "c", "body": "75", "body_hi": "75", "isCorrect": true}, {"id": "d", "body": "100", "body_hi": "100", "isCorrect": false}]'::jsonb,2.5,0.83,'a² - b² = (a - b)(a + b), and the two factors a - b and a + b are both odd or both even. So the difference is either odd (every odd number n is ((n + 1)/2)² - ((n - 1)/2)²) or a multiple of 4 (4k = (k + 1)² - (k - 1)²). A number that is even but not a multiple of 4 -- 2, 6, 10, ..., 98 -- can never be such a difference. There are 25 of those, so 100 - 25 = 75 numbers can. 50 counts only the odd numbers; 100 assumes every number can; 67 has no basis.','a² - b² = (a - b)(a + b), और दोनों गुणनखंड a - b और a + b या तो दोनों विषम हैं या दोनों सम। इसलिए अंतर या तो विषम है (हर विषम n = ((n + 1)/2)² - ((n - 1)/2)²) या 4 का गुणज (4k = (k + 1)² - (k - 1)²)। जो संख्या सम है पर 4 का गुणज नहीं -- 2, 6, 10, ..., 98 -- वह कभी ऐसा अंतर नहीं हो सकती। ऐसी 25 हैं, इसलिए 100 - 25 = 75 संख्याएँ हो सकती हैं। 50 केवल विषम संख्याएँ गिनता है; 100 मान लेता है कि हर संख्या हो सकती है; 67 का कोई आधार नहीं।','csat-l4-s04-qa-nt-numbers-that-are-differences-of-two-squares','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Direction & Distance','mcq','medium','Facing east, Priya walks 8 m forward. Without turning round, she then walks 3 m backwards. Next she turns to her left and walks 12 m. How far is she now from where she started, and in which general direction?','पूर्व की ओर मुख करके प्रिया 8 मीटर आगे चलती है। फिर बिना मुड़े वह 3 मीटर पीछे की ओर चलती है। इसके बाद वह अपनी बाईं ओर मुड़कर 12 मीटर चलती है। अब वह अपने आरंभ स्थान से कितनी दूर है, और मोटे तौर पर किस दिशा में?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 11}'::jsonb,'[{"id": "a", "body": "13 m, to the north-east", "body_hi": "13 मीटर, उत्तर-पूर्व में", "isCorrect": true}, {"id": "b", "body": "13 m, to the south-east", "body_hi": "13 मीटर, दक्षिण-पूर्व में", "isCorrect": false}, {"id": "c", "body": "23 m, to the north-east", "body_hi": "23 मीटर, उत्तर-पूर्व में", "isCorrect": false}, {"id": "d", "body": "17 m, to the north-east", "body_hi": "17 मीटर, उत्तर-पूर्व में", "isCorrect": false}]'::jsonb,2.5,0.83,'Walking backwards without turning takes her 3 m west, so after two legs she is 8 - 3 = 5 m east of the start and still facing east. A left turn from east faces north, so she ends 5 m east and 12 m north of the start: √(5² + 12²) = 13 m, to the north-east. South-east comes from treating the backward walk as a turn to face west, which would make her left point south; 23 m adds up every leg walked; 17 m adds the 5 m and the 12 m.','बिना मुड़े पीछे चलना उसे 3 मीटर पश्चिम ले जाता है, इसलिए दो चरणों के बाद वह आरंभ से 8 - 3 = 5 मीटर पूर्व में है और अब भी पूर्व की ओर मुख किए है। पूर्व से बाईं ओर मुड़ने पर मुख उत्तर की ओर होता है, इसलिए वह आरंभ से 5 मीटर पूर्व और 12 मीटर उत्तर में पहुँचती है: √(5² + 12²) = 13 मीटर, उत्तर-पूर्व में। दक्षिण-पूर्व पीछे चलने को पश्चिम की ओर मुड़ना मान लेने से आता है, जिससे उसकी बाईं ओर दक्षिण हो जाती; 23 मीटर चले गए हर चरण को जोड़ता है; 17 मीटर 5 और 12 मीटर को जोड़ता है।','csat-l4-s04-lr-dd-a-walk-that-goes-backwards','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','medium','Two people walk beside a railway line at 3.6 km/h each: one in the same direction as a passing train, the other towards it. The train takes 12 seconds to pass the first and 10 seconds to pass the second. How long is the train?','दो लोग एक रेल लाइन के किनारे 3.6 किमी/घंटा से चल रहे हैं: एक गुज़रती रेलगाड़ी की ही दिशा में, दूसरा उसकी ओर। रेलगाड़ी पहले को पार करने में 12 सेकंड और दूसरे को पार करने में 10 सेकंड लेती है। रेलगाड़ी कितनी लंबी है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 12}'::jsonb,'[{"id": "a", "body": "110 m", "body_hi": "110 मीटर", "isCorrect": false}, {"id": "b", "body": "120 m", "body_hi": "120 मीटर", "isCorrect": true}, {"id": "c", "body": "132 m", "body_hi": "132 मीटर", "isCorrect": false}, {"id": "d", "body": "144 m", "body_hi": "144 मीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'3.6 km/h is 1 m/s. If the train''s speed is v m/s, it passes the first walker at v - 1 and the second at v + 1, so its length is 12(v - 1) = 10(v + 1), giving v = 11 m/s and a length of 10 × 12 = 120 m. 110 m multiplies the train''s speed by 10 seconds without adding the second walker''s speed; 132 m multiplies it by 12 seconds without taking away the first walker''s; 144 m has no basis.','3.6 किमी/घंटा = 1 मीटर/सेकंड। यदि रेलगाड़ी की चाल v मीटर/सेकंड है, तो वह पहले को v - 1 और दूसरे को v + 1 की सापेक्ष चाल से पार करती है, इसलिए उसकी लंबाई 12(v - 1) = 10(v + 1) है, जिससे v = 11 मीटर/सेकंड और लंबाई 10 × 12 = 120 मीटर। 110 मीटर रेलगाड़ी की चाल को दूसरे की चाल जोड़े बिना 10 सेकंड से गुणा करता है; 132 मीटर उसे पहले की चाल घटाए बिना 12 सेकंड से गुणा करता है; 144 मीटर का कोई आधार नहीं।','csat-l4-s04-qa-sdt-a-train-that-passes-two-walkers','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','hard','In an election between two candidates, A and B, their votes were in the ratio 5 : 3. Had 1,200 of A''s voters voted for B instead, B would have won by 400 votes. How many votes were cast in all?','दो उम्मीदवारों, A और B, के बीच एक चुनाव में उनके मत 5 : 3 के अनुपात में थे। यदि A के 1,200 मतदाताओं ने इसके बजाय B को मत दिया होता, तो B 400 मतों से जीत जाता। कुल कितने मत डाले गए?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 13}'::jsonb,'[{"id": "a", "body": "4,800", "body_hi": "4,800", "isCorrect": false}, {"id": "b", "body": "6,400", "body_hi": "6,400", "isCorrect": false}, {"id": "c", "body": "8,000", "body_hi": "8,000", "isCorrect": true}, {"id": "d", "body": "9,600", "body_hi": "9,600", "isCorrect": false}]'::jsonb,2.5,0.83,'Let the votes be 5k and 3k. After the switch A has 5k - 1,200 and B has 3k + 1,200, and B leads by 400: (3k + 1,200) - (5k - 1,200) = 400, so 2,400 - 2k = 400 and k = 1,000. The votes were 5,000 and 3,000: 8,000 in all. Check: after the switch A has 3,800 and B 4,200. 4,800, 6,400 and 9,600 take a part of the ratio as 600, 800 and 1,200.','मान लीजिए मत 5k और 3k थे। बदलाव के बाद A के 5k - 1,200 और B के 3k + 1,200 होते, और B 400 से आगे होता: (3k + 1,200) - (5k - 1,200) = 400, अतः 2,400 - 2k = 400 और k = 1,000। मत 5,000 और 3,000 थे: कुल 8,000। जाँच: बदलाव के बाद A के 3,800 और B के 4,200। 4,800, 6,400 और 9,600 अनुपात के एक भाग को 600, 800 और 1,200 मानते हैं।','csat-l4-s04-qa-rm-votes-that-would-switch-a-result','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','easy','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In a well-known experiment reported in 1974, the psychologists Amos Tversky and Daniel Kahneman spun a wheel of fortune marked from 0 to 100 in front of their subjects; unknown to the subjects, it had been rigged to stop at either 10 or 65. The subjects were asked whether the percentage of African countries in the United Nations was higher or lower than the number on the wheel, and then to estimate that percentage. Those who had seen 10 gave a median estimate of 25 per cent; those who had seen 65 gave 45. A number they took to be pure chance had pulled their judgement towards it. Such anchoring appears well beyond the laboratory. An opening price in a bargain, a figure in a headline or the sum a lawyer demands in court can shift the final number, even among people who believe they are ignoring it. Since warning people about the effect does little to remove it, a careful negotiator may do better to name the first figure, or to think deliberately of reasons why the anchor might be wrong.

According to the passage, what was striking about the estimates in the experiment?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1974 में प्रकाशित एक प्रसिद्ध प्रयोग में मनोवैज्ञानिक एमॉस त्वेर्स्की और डेनियल काह्नमन ने अपने प्रतिभागियों के सामने 0 से 100 तक अंकित भाग्य का एक पहिया घुमाया; प्रतिभागियों को पता नहीं था कि उसे केवल 10 या 65 पर रुकने के लिए बनाया गया था। प्रतिभागियों से पूछा गया कि संयुक्त राष्ट्र में अफ़्रीकी देशों का प्रतिशत पहिये की संख्या से अधिक है या कम, और फिर उस प्रतिशत का अनुमान लगाने को कहा गया। जिन्होंने 10 देखा था उनका माध्यिका अनुमान 25 प्रतिशत था; जिन्होंने 65 देखा था उनका 45। जिस संख्या को वे शुद्ध संयोग समझ रहे थे, उसने उनके निर्णय को अपनी ओर खींच लिया। ऐसी ''लंगर'' प्रवृत्ति प्रयोगशाला से बहुत बाहर भी दिखती है। मोल-भाव में पहली क़ीमत, किसी शीर्षक में दी गई संख्या या अदालत में किसी वकील द्वारा माँगी गई राशि अंतिम संख्या को खिसका सकती है, उन लोगों में भी जो मानते हैं कि वे उसे अनदेखा कर रहे हैं। चूँकि लोगों को इस प्रभाव के बारे में चेतावनी देने से वह बहुत कम हटता है, एक सावधान वार्ताकार के लिए बेहतर हो सकता है कि वह स्वयं पहली संख्या रखे, या सोच-समझकर उन कारणों पर विचार करे जिनसे लंगर ग़लत हो सकता है।

परिच्छेद के अनुसार, प्रयोग में लगाए गए अनुमानों में क्या उल्लेखनीय था?','{"craft": "precision", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p02", "csat_order": 14}'::jsonb,'[{"id": "a", "body": "They were almost exactly right, whichever number the wheel had stopped at.", "body_hi": "पहिया चाहे जिस संख्या पर रुका हो, वे लगभग बिल्कुल सही थे।", "isCorrect": false}, {"id": "b", "body": "Most subjects refused to guess once they realised the wheel had been rigged.", "body_hi": "पहिये के बनावटी होने का पता चलते ही अधिकांश प्रतिभागियों ने अनुमान लगाने से मना कर दिया।", "isCorrect": false}, {"id": "c", "body": "The subjects who saw 65 gave lower estimates than those who saw only 10.", "body_hi": "65 देखने वाले प्रतिभागियों ने केवल 10 देखने वालों से कम अनुमान दिए।", "isCorrect": false}, {"id": "d", "body": "They moved towards a number the subjects took to be pure chance.", "body_hi": "वे उस संख्या की ओर खिसक गए जिसे प्रतिभागी शुद्ध संयोग से आई मान रहे थे।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage says that a number the subjects ''took to be pure chance had pulled their judgement towards it'': those shown 10 guessed lower than those shown 65. It does not say the estimates were accurate or that subjects refused to guess; and the group that saw the higher number gave the higher estimate, not the lower one.','परिच्छेद कहता है कि जिस संख्या को प्रतिभागी ''शुद्ध संयोग समझ रहे थे, उसने उनके निर्णय को अपनी ओर खींच लिया'': 10 देखने वालों ने 65 देखने वालों से कम अनुमान लगाया। वह यह नहीं कहता कि अनुमान सटीक थे या प्रतिभागियों ने अनुमान लगाने से मना किया; और ऊँची संख्या देखने वाले समूह ने ऊँचा अनुमान दिया, नीचा नहीं।','csat-l4-s04-rc-p02-what-was-striking-about-the-estimates','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In a well-known experiment reported in 1974, the psychologists Amos Tversky and Daniel Kahneman spun a wheel of fortune marked from 0 to 100 in front of their subjects; unknown to the subjects, it had been rigged to stop at either 10 or 65. The subjects were asked whether the percentage of African countries in the United Nations was higher or lower than the number on the wheel, and then to estimate that percentage. Those who had seen 10 gave a median estimate of 25 per cent; those who had seen 65 gave 45. A number they took to be pure chance had pulled their judgement towards it. Such anchoring appears well beyond the laboratory. An opening price in a bargain, a figure in a headline or the sum a lawyer demands in court can shift the final number, even among people who believe they are ignoring it. Since warning people about the effect does little to remove it, a careful negotiator may do better to name the first figure, or to think deliberately of reasons why the anchor might be wrong.

Which one of the following would the passage lead us to expect?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1974 में प्रकाशित एक प्रसिद्ध प्रयोग में मनोवैज्ञानिक एमॉस त्वेर्स्की और डेनियल काह्नमन ने अपने प्रतिभागियों के सामने 0 से 100 तक अंकित भाग्य का एक पहिया घुमाया; प्रतिभागियों को पता नहीं था कि उसे केवल 10 या 65 पर रुकने के लिए बनाया गया था। प्रतिभागियों से पूछा गया कि संयुक्त राष्ट्र में अफ़्रीकी देशों का प्रतिशत पहिये की संख्या से अधिक है या कम, और फिर उस प्रतिशत का अनुमान लगाने को कहा गया। जिन्होंने 10 देखा था उनका माध्यिका अनुमान 25 प्रतिशत था; जिन्होंने 65 देखा था उनका 45। जिस संख्या को वे शुद्ध संयोग समझ रहे थे, उसने उनके निर्णय को अपनी ओर खींच लिया। ऐसी ''लंगर'' प्रवृत्ति प्रयोगशाला से बहुत बाहर भी दिखती है। मोल-भाव में पहली क़ीमत, किसी शीर्षक में दी गई संख्या या अदालत में किसी वकील द्वारा माँगी गई राशि अंतिम संख्या को खिसका सकती है, उन लोगों में भी जो मानते हैं कि वे उसे अनदेखा कर रहे हैं। चूँकि लोगों को इस प्रभाव के बारे में चेतावनी देने से वह बहुत कम हटता है, एक सावधान वार्ताकार के लिए बेहतर हो सकता है कि वह स्वयं पहली संख्या रखे, या सोच-समझकर उन कारणों पर विचार करे जिनसे लंगर ग़लत हो सकता है।

परिच्छेद के आधार पर निम्नलिखित में से किसकी अपेक्षा की जानी चाहिए?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p02", "csat_order": 15}'::jsonb,'[{"id": "a", "body": "A buyer who has read about anchoring is no longer influenced at all by a seller''s opening price.", "body_hi": "लंगर प्रवृत्ति के बारे में पढ़ चुका ख़रीदार विक्रेता की पहली क़ीमत से बिल्कुल भी प्रभावित नहीं होता।", "isCorrect": false}, {"id": "b", "body": "A figure printed in a headline has no effect on readers who distrust the newspaper that printed it.", "body_hi": "किसी शीर्षक में छपी संख्या का उन पाठकों पर कोई प्रभाव नहीं पड़ता जो उसे छापने वाले समाचारपत्र पर भरोसा नहीं करते।", "isCorrect": false}, {"id": "c", "body": "A buyer who hears a high asking price first pays more than one who hears a low price first.", "body_hi": "जो ख़रीदार पहले ऊँची माँगी गई क़ीमत सुनता है, वह उसी वस्तु के लिए पहले नीची क़ीमत सुनने वाले से अधिक चुकाता है।", "isCorrect": true}, {"id": "d", "body": "Estimates made just after seeing a random number are as accurate as those made without seeing one.", "body_hi": "किसी यादृच्छिक संख्या को देखने के ठीक बाद लगाए गए अनुमान उतने ही सटीक होते हैं जितने उसे देखे बिना लगाए गए।", "isCorrect": false}]'::jsonb,2.5,0.83,'Anchoring says that a first figure pulls the final one towards it, so a buyer who first hears a high asking price is likely to settle higher than one who first hears a low price for the same item. The passage says warnings do little to remove the effect, so knowing about it is no shield; it says even people who believe they are ignoring a figure can be moved, so doubting the source is no shield either; and the experiment shows a random number distorting estimates, not leaving them unchanged.','लंगर प्रवृत्ति कहती है कि पहली संख्या अंतिम संख्या को अपनी ओर खींचती है, इसलिए जो ख़रीदार पहले ऊँची माँगी गई क़ीमत सुनता है, उसके उसी वस्तु के लिए नीची क़ीमत पहले सुनने वाले से अधिक पर सौदा करने की संभावना है। परिच्छेद कहता है कि चेतावनी प्रभाव को बहुत कम हटाती है, इसलिए उसके बारे में जानना कोई कवच नहीं; वह कहता है कि जो लोग मानते हैं कि वे किसी संख्या को अनदेखा कर रहे हैं वे भी प्रभावित हो सकते हैं, इसलिए स्रोत पर संदेह भी कवच नहीं; और प्रयोग दिखाता है कि यादृच्छिक संख्या अनुमानों को बिगाड़ती है, उन्हें अपरिवर्तित नहीं छोड़ती।','csat-l4-s04-rc-p02-what-the-passage-leads-us-to-expect','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In a well-known experiment reported in 1974, the psychologists Amos Tversky and Daniel Kahneman spun a wheel of fortune marked from 0 to 100 in front of their subjects; unknown to the subjects, it had been rigged to stop at either 10 or 65. The subjects were asked whether the percentage of African countries in the United Nations was higher or lower than the number on the wheel, and then to estimate that percentage. Those who had seen 10 gave a median estimate of 25 per cent; those who had seen 65 gave 45. A number they took to be pure chance had pulled their judgement towards it. Such anchoring appears well beyond the laboratory. An opening price in a bargain, a figure in a headline or the sum a lawyer demands in court can shift the final number, even among people who believe they are ignoring it. Since warning people about the effect does little to remove it, a careful negotiator may do better to name the first figure, or to think deliberately of reasons why the anchor might be wrong.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1974 में प्रकाशित एक प्रसिद्ध प्रयोग में मनोवैज्ञानिक एमॉस त्वेर्स्की और डेनियल काह्नमन ने अपने प्रतिभागियों के सामने 0 से 100 तक अंकित भाग्य का एक पहिया घुमाया; प्रतिभागियों को पता नहीं था कि उसे केवल 10 या 65 पर रुकने के लिए बनाया गया था। प्रतिभागियों से पूछा गया कि संयुक्त राष्ट्र में अफ़्रीकी देशों का प्रतिशत पहिये की संख्या से अधिक है या कम, और फिर उस प्रतिशत का अनुमान लगाने को कहा गया। जिन्होंने 10 देखा था उनका माध्यिका अनुमान 25 प्रतिशत था; जिन्होंने 65 देखा था उनका 45। जिस संख्या को वे शुद्ध संयोग समझ रहे थे, उसने उनके निर्णय को अपनी ओर खींच लिया। ऐसी ''लंगर'' प्रवृत्ति प्रयोगशाला से बहुत बाहर भी दिखती है। मोल-भाव में पहली क़ीमत, किसी शीर्षक में दी गई संख्या या अदालत में किसी वकील द्वारा माँगी गई राशि अंतिम संख्या को खिसका सकती है, उन लोगों में भी जो मानते हैं कि वे उसे अनदेखा कर रहे हैं। चूँकि लोगों को इस प्रभाव के बारे में चेतावनी देने से वह बहुत कम हटता है, एक सावधान वार्ताकार के लिए बेहतर हो सकता है कि वह स्वयं पहली संख्या रखे, या सोच-समझकर उन कारणों पर विचार करे जिनसे लंगर ग़लत हो सकता है।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Believing that a number has been produced by pure chance does not stop a person from being influenced by it.", "In the experiment, the subjects who saw 65 overestimated the true percentage, and those who saw 10 underestimated it."], "statements_hi": ["किसी संख्या को शुद्ध संयोग से आई मानना किसी व्यक्ति को उससे प्रभावित होने से नहीं रोकता।", "प्रयोग में 65 देखने वाले प्रतिभागियों ने वास्तविक प्रतिशत को बढ़ाकर आँका, और 10 देखने वालों ने घटाकर।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p02", "csat_order": 16}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 1 is valid. The subjects took the wheel''s number to be chance, and it still moved their estimates; so believing a number to be random did not protect them. 2 cannot be concluded: the passage gives the two groups'' median estimates but never the true percentage, so it does not say whether either group was too high or too low. It shows only that the two groups differed.','केवल 1 वैध है। प्रतिभागी पहिये की संख्या को संयोग मान रहे थे, और फिर भी उसने उनके अनुमानों को खिसका दिया; इसलिए किसी संख्या को यादृच्छिक मानने ने उन्हें नहीं बचाया। 2 का निष्कर्ष नहीं निकाला जा सकता: परिच्छेद दोनों समूहों के माध्यिका अनुमान देता है पर वास्तविक प्रतिशत कभी नहीं, इसलिए वह यह नहीं कहता कि कोई समूह बहुत ऊपर था या बहुत नीचे। वह केवल यह दिखाता है कि दोनों समूह अलग थे।','csat-l4-s04-rc-p02-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','easy','12 pens cost as much as 8 notebooks. What is the ratio of the price of a pen to the price of a notebook?','12 पेनों का मूल्य 8 नोटबुकों के बराबर है। एक पेन के मूल्य और एक नोटबुक के मूल्य का अनुपात क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 17}'::jsonb,'[{"id": "a", "body": "2 : 3", "body_hi": "2 : 3", "isCorrect": true}, {"id": "b", "body": "3 : 2", "body_hi": "3 : 2", "isCorrect": false}, {"id": "c", "body": "3 : 4", "body_hi": "3 : 4", "isCorrect": false}, {"id": "d", "body": "4 : 5", "body_hi": "4 : 5", "isCorrect": false}]'::jsonb,2.5,0.83,'If 12 pens cost as much as 8 notebooks, a pen costs 8/12 = 2/3 of a notebook: the ratio is 2 : 3. More pens are needed to match fewer notebooks, so each pen is cheaper. 3 : 2 reads the counts straight across, which turns the ratio upside down; 3 : 4 and 4 : 5 have no basis.','यदि 12 पेनों का मूल्य 8 नोटबुकों के बराबर है, तो एक पेन का मूल्य एक नोटबुक का 8/12 = 2/3 है: अनुपात 2 : 3 है। कम नोटबुकों के बराबर होने के लिए अधिक पेन चाहिए, इसलिए हर पेन सस्ता है। 3 : 2 संख्याओं को सीधे पढ़ता है, जो अनुपात को उलट देता है; 3 : 4 और 4 : 5 का कोई आधार नहीं।','csat-l4-s04-qa-rm-pens-against-notebooks','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','hard','Anil, Bela, Chetan and Disha each attend one class, on a different day from Monday to Thursday, and each class is in a different subject: Music, Painting, Chess or Yoga. The Chess class is on the day after Bela''s class. Chetan does not take Music, and his class is not on Tuesday. Exactly one class falls between Bela''s and Disha''s. The Music class comes earlier in the week than the Painting class. Chetan''s class is on the day before the Yoga class. Which one of the following is correct?','अनिल, बेला, चेतन और दिशा में से हर एक सोमवार से गुरुवार तक के अलग-अलग दिन एक कक्षा में जाता/जाती है, और हर कक्षा अलग विषय की है: संगीत, चित्रकला, शतरंज या योग। शतरंज की कक्षा बेला की कक्षा के अगले दिन है। चेतन संगीत नहीं लेता, और उसकी कक्षा मंगलवार को नहीं है। बेला और दिशा की कक्षाओं के बीच ठीक एक कक्षा पड़ती है। संगीत की कक्षा सप्ताह में चित्रकला की कक्षा से पहले आती है। चेतन की कक्षा योग की कक्षा से एक दिन पहले है। निम्नलिखित में से कौन-सा सही है?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 18}'::jsonb,'[{"id": "a", "body": "Anil takes Chess on Wednesday.", "body_hi": "अनिल बुधवार को शतरंज लेता है।", "isCorrect": false}, {"id": "b", "body": "Bela takes Painting on Tuesday.", "body_hi": "बेला मंगलवार को चित्रकला लेती है।", "isCorrect": true}, {"id": "c", "body": "Disha takes Painting on Thursday.", "body_hi": "दिशा गुरुवार को चित्रकला लेती है।", "isCorrect": false}, {"id": "d", "body": "Chetan takes Yoga on Wednesday.", "body_hi": "चेतन बुधवार को योग लेता है।", "isCorrect": false}]'::jsonb,2.5,0.83,'Chetan''s class is the day before Yoga and not on Tuesday, so Chetan is on Monday or Wednesday. Bela and Disha are two days apart: Monday and Wednesday, or Tuesday and Thursday. If Chetan were on Monday, Yoga would be Tuesday and Bela and Disha would need Tuesday and Thursday -- but Chess must be the day after Bela''s class, which fails for Thursday and puts Chess on Wednesday if Bela is on Tuesday, leaving Bela with Yoga, Anil with Chess and Chetan with Painting on Monday, before any Music: ruled out. So Chetan is on Wednesday and Yoga on Thursday. Wednesday is Chetan''s, so Bela and Disha take Tuesday and Thursday, and Chess follows Bela, so Bela is on Tuesday, Disha on Thursday with Yoga, Chetan on Wednesday with Chess, and Anil on Monday. Music comes before Painting, so Anil takes Music and Bela Painting. Anil does not take Chess, Disha takes Yoga rather than Painting, and Chetan takes Chess rather than Yoga.','चेतन की कक्षा योग से एक दिन पहले है और मंगलवार को नहीं, इसलिए चेतन सोमवार या बुधवार को है। बेला और दिशा दो दिन के अंतर पर हैं: सोमवार और बुधवार, या मंगलवार और गुरुवार। यदि चेतन सोमवार को होता, तो योग मंगलवार को होता और बेला व दिशा को मंगलवार और गुरुवार चाहिए होते -- पर शतरंज बेला की कक्षा के अगले दिन होना चाहिए, जो गुरुवार के लिए असंभव है और बेला के मंगलवार को होने पर शतरंज को बुधवार पर रखता है, जिससे बेला को योग, अनिल को शतरंज और चेतन को सोमवार को चित्रकला मिलती, किसी भी संगीत से पहले: यह ख़ारिज। अतः चेतन बुधवार को है और योग गुरुवार को। बुधवार चेतन का है, इसलिए बेला और दिशा मंगलवार और गुरुवार लेती हैं, और शतरंज बेला के बाद आता है, इसलिए बेला मंगलवार को, दिशा गुरुवार को योग के साथ, चेतन बुधवार को शतरंज के साथ, और अनिल सोमवार को है। संगीत चित्रकला से पहले आता है, इसलिए अनिल संगीत लेता है और बेला चित्रकला। अनिल शतरंज नहीं लेता, दिशा चित्रकला के बजाय योग लेती है, और चेतन योग के बजाय शतरंज लेता है।','csat-l4-s04-lr-sa-four-classes-on-four-weekdays','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','What is the LCM of 12, 18 and 24 divided by their HCF?','12, 18 और 24 के LCM को उनके HCF से भाग देने पर क्या मिलता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 19}'::jsonb,'[{"id": "a", "body": "6", "body_hi": "6", "isCorrect": false}, {"id": "b", "body": "12", "body_hi": "12", "isCorrect": true}, {"id": "c", "body": "36", "body_hi": "36", "isCorrect": false}, {"id": "d", "body": "72", "body_hi": "72", "isCorrect": false}]'::jsonb,2.5,0.83,'12 = 2² × 3, 18 = 2 × 3², 24 = 2³ × 3. The LCM takes the highest powers, 2³ × 3² = 72; the HCF takes the lowest, 2 × 3 = 6. So 72 ÷ 6 = 12. 72 is the LCM and 6 the HCF; 36 divides the LCM by 2.','12 = 2² × 3, 18 = 2 × 3², 24 = 2³ × 3। LCM सबसे बड़ी घातें लेता है, 2³ × 3² = 72; HCF सबसे छोटी, 2 × 3 = 6। अतः 72 ÷ 6 = 12। 72, LCM है और 6, HCF; 36, LCM को 2 से भाग देता है।','csat-l4-s04-qa-nt-the-lcm-over-the-hcf-of-three-numbers','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Time & Work','mcq','hard','A job needs 30 days of work. The worker works for 3 days and then rests for 1 day, over and over, starting with a working day. On which day, counting from the first, is the job finished?','एक काम के लिए 30 दिनों का काम चाहिए। कामगार 3 दिन काम करता है और फिर 1 दिन विश्राम करता है, बार-बार, काम के दिन से शुरू करते हुए। पहले दिन से गिनने पर काम किस दिन पूरा होता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 20}'::jsonb,'[{"id": "a", "body": "37th", "body_hi": "37वें", "isCorrect": false}, {"id": "b", "body": "39th", "body_hi": "39वें", "isCorrect": true}, {"id": "c", "body": "40th", "body_hi": "40वें", "isCorrect": false}, {"id": "d", "body": "42nd", "body_hi": "42वें", "isCorrect": false}]'::jsonb,2.5,0.83,'Every block of 4 days gives 3 days of work. Ten blocks would give 30 days of work in 40 days -- but the 40th day is a rest day, and the 30th working day is the 39th day. So the job is finished on the 39th day. The 40th counts the final rest day; the 42nd and the 37th miscount the blocks.','हर 4 दिनों के खंड में 3 दिन काम होता है। दस खंड 40 दिनों में 30 दिन का काम देते -- पर 40वाँ दिन विश्राम का है, और काम का 30वाँ दिन 39वाँ दिन है। अतः काम 39वें दिन पूरा होता है। 40वाँ अंतिम विश्राम-दिवस भी गिन लेता है; 42वाँ और 37वाँ खंडों को ग़लत गिनते हैं।','csat-l4-s04-qa-tw-three-days-on-and-one-off','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Al-Biruni was born in 973 in Khwarizm, in Central Asia. Taken to Ghazni by Sultan Mahmud in 1017, he later spent years among Brahmana scholars in the Punjab, learning Sanskrit, and wrote in Arabic a long account of India, the Kitab-ul-Hind. He was unusually aware of how hard it is to understand a society from outside, and he named three barriers. The first was language: Sanskrit differed so much from Arabic and Persian that ideas could not easily be carried from one to the other. The second was the difference in religious beliefs and practices. The third was the self-absorption of the local people, which he felt made them unwilling to share what they knew with outsiders. To overcome these, he relied heavily on Sanskrit texts, and he looked for parallels in societies his readers knew, noting, for instance, that ancient Persia too had recognised four social categories. His account is valuable not because it is free of bias -- built on texts that laid down how society ought to be ordered, it often presents that ideal rather than everyday practice -- but because he named his difficulties openly.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अल-बिरूनी का जन्म 973 में मध्य एशिया के ख़्वारिज़्म में हुआ था। 1017 में सुल्तान महमूद द्वारा ग़ज़नी ले जाए जाने के बाद उसने वर्षों तक पंजाब में ब्राह्मण विद्वानों के बीच रहकर संस्कृत सीखी, और अरबी में भारत का एक लंबा विवरण, किताब-उल-हिंद, लिखा। वह असाधारण रूप से जानता था कि किसी समाज को बाहर से समझना कितना कठिन है, और उसने तीन बाधाएँ बताईं। पहली भाषा थी: संस्कृत अरबी और फ़ारसी से इतनी भिन्न थी कि विचारों को एक से दूसरी में आसानी से नहीं ले जाया जा सकता था। दूसरी धार्मिक विश्वासों और प्रथाओं का अंतर थी। तीसरी स्थानीय लोगों का आत्म-केंद्रित होना थी, जिसके कारण, उसे लगा, वे जो जानते थे उसे बाहरी लोगों के साथ बाँटना नहीं चाहते थे। इन पर पार पाने के लिए वह संस्कृत ग्रंथों पर बहुत निर्भर रहा, और उसने अपने पाठकों के परिचित समाजों में समानताएँ खोजीं, उदाहरण के लिए यह बताते हुए कि प्राचीन फ़ारस में भी चार सामाजिक वर्ग माने गए थे। उसका विवरण इसलिए मूल्यवान नहीं कि वह पूर्वाग्रह से मुक्त है -- उन ग्रंथों पर आधारित होने के कारण जो बताते थे कि समाज को कैसे व्यवस्थित होना चाहिए, वह प्रायः रोज़मर्रा के व्यवहार के बजाय उस आदर्श को प्रस्तुत करता है -- बल्कि इसलिए कि उसने अपनी कठिनाइयों को खुलकर बताया।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p03", "csat_order": 21}'::jsonb,'[{"id": "a", "body": "Al-Biruni''s account is valuable partly because he was frank about what made India hard to understand.", "body_hi": "अल-बिरूनी का विवरण कुछ हद तक इसलिए मूल्यवान है कि उसने खुलकर बताया कि भारत को समझना किन कारणों से कठिन था।", "isCorrect": true}, {"id": "b", "body": "Al-Biruni''s account gives an unbiased picture of how ordinary people in India actually lived and worked.", "body_hi": "अल-बिरूनी का विवरण इस बात की पूर्वाग्रह-रहित तस्वीर देता है कि भारत के सामान्य लोग वास्तव में कैसे रहते और काम करते थे।", "isCorrect": false}, {"id": "c", "body": "Al-Biruni could not understand India at all, because he never learnt any of the languages spoken there.", "body_hi": "अल-बिरूनी भारत को बिल्कुल नहीं समझ सका, क्योंकि उसने वहाँ बोली जाने वाली कोई भी भाषा कभी नहीं सीखी।", "isCorrect": false}, {"id": "d", "body": "Al-Biruni wrote his account of India mainly in order to praise the military campaigns of Sultan Mahmud.", "body_hi": "अल-बिरूनी ने भारत का अपना विवरण मुख्यतः सुल्तान महमूद के सैन्य अभियानों की प्रशंसा के लिए लिखा।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage presents Al-Biruni as a careful outsider who named the barriers to understanding India, and it values his account for that frankness while warning that his reliance on prescriptive texts shaped what he described. It says outright that the account is not free of bias; he learnt Sanskrit, so he did not fail for want of the language; and nothing suggests that he wrote to praise Mahmud''s campaigns.','परिच्छेद अल-बिरूनी को एक सावधान बाहरी व्यक्ति के रूप में प्रस्तुत करता है जिसने भारत को समझने की बाधाएँ बताईं, और उसके विवरण को इसी स्पष्टवादिता के लिए मूल्यवान मानता है, यह चेतावनी देते हुए कि नियम बताने वाले ग्रंथों पर उसकी निर्भरता ने उसके वर्णन को आकार दिया। वह साफ़ कहता है कि विवरण पूर्वाग्रह से मुक्त नहीं है; उसने संस्कृत सीखी, इसलिए वह भाषा के अभाव में विफल नहीं हुआ; और कुछ भी यह नहीं बताता कि उसने महमूद के अभियानों की प्रशंसा के लिए लिखा।','csat-l4-s04-rc-p03-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Al-Biruni was born in 973 in Khwarizm, in Central Asia. Taken to Ghazni by Sultan Mahmud in 1017, he later spent years among Brahmana scholars in the Punjab, learning Sanskrit, and wrote in Arabic a long account of India, the Kitab-ul-Hind. He was unusually aware of how hard it is to understand a society from outside, and he named three barriers. The first was language: Sanskrit differed so much from Arabic and Persian that ideas could not easily be carried from one to the other. The second was the difference in religious beliefs and practices. The third was the self-absorption of the local people, which he felt made them unwilling to share what they knew with outsiders. To overcome these, he relied heavily on Sanskrit texts, and he looked for parallels in societies his readers knew, noting, for instance, that ancient Persia too had recognised four social categories. His account is valuable not because it is free of bias -- built on texts that laid down how society ought to be ordered, it often presents that ideal rather than everyday practice -- but because he named his difficulties openly.

Which one of the following was NOT among the barriers that, according to the passage, Al-Biruni named?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अल-बिरूनी का जन्म 973 में मध्य एशिया के ख़्वारिज़्म में हुआ था। 1017 में सुल्तान महमूद द्वारा ग़ज़नी ले जाए जाने के बाद उसने वर्षों तक पंजाब में ब्राह्मण विद्वानों के बीच रहकर संस्कृत सीखी, और अरबी में भारत का एक लंबा विवरण, किताब-उल-हिंद, लिखा। वह असाधारण रूप से जानता था कि किसी समाज को बाहर से समझना कितना कठिन है, और उसने तीन बाधाएँ बताईं। पहली भाषा थी: संस्कृत अरबी और फ़ारसी से इतनी भिन्न थी कि विचारों को एक से दूसरी में आसानी से नहीं ले जाया जा सकता था। दूसरी धार्मिक विश्वासों और प्रथाओं का अंतर थी। तीसरी स्थानीय लोगों का आत्म-केंद्रित होना थी, जिसके कारण, उसे लगा, वे जो जानते थे उसे बाहरी लोगों के साथ बाँटना नहीं चाहते थे। इन पर पार पाने के लिए वह संस्कृत ग्रंथों पर बहुत निर्भर रहा, और उसने अपने पाठकों के परिचित समाजों में समानताएँ खोजीं, उदाहरण के लिए यह बताते हुए कि प्राचीन फ़ारस में भी चार सामाजिक वर्ग माने गए थे। उसका विवरण इसलिए मूल्यवान नहीं कि वह पूर्वाग्रह से मुक्त है -- उन ग्रंथों पर आधारित होने के कारण जो बताते थे कि समाज को कैसे व्यवस्थित होना चाहिए, वह प्रायः रोज़मर्रा के व्यवहार के बजाय उस आदर्श को प्रस्तुत करता है -- बल्कि इसलिए कि उसने अपनी कठिनाइयों को खुलकर बताया।

परिच्छेद के अनुसार, निम्नलिखित में से कौन-सी उन बाधाओं में से नहीं थी जो अल-बिरूनी ने बताईं?','{"craft": "precision", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p03", "csat_order": 22}'::jsonb,'[{"id": "a", "body": "How far Sanskrit differed from Arabic and Persian", "body_hi": "संस्कृत का अरबी और फ़ारसी से इतना अधिक भिन्न होना", "isCorrect": false}, {"id": "b", "body": "Differences in religious beliefs and practices", "body_hi": "धार्मिक विश्वासों और प्रथाओं में अंतर", "isCorrect": false}, {"id": "c", "body": "The reluctance of local people to share what they knew", "body_hi": "स्थानीय लोगों का अपना ज्ञान बाँटने में संकोच", "isCorrect": false}, {"id": "d", "body": "A shortage of written works about Indian society", "body_hi": "भारतीय समाज के बारे में लिखित ग्रंथों की कमी", "isCorrect": true}]'::jsonb,2.5,0.83,'The three barriers were language, differences of religious belief and practice, and the local people''s unwillingness to share knowledge with outsiders. A lack of written sources was not one of them: he relied heavily on Sanskrit texts. The other three options restate the barriers he named.','तीन बाधाएँ थीं भाषा, धार्मिक विश्वास और प्रथा के अंतर, और स्थानीय लोगों की बाहरी लोगों से ज्ञान बाँटने की अनिच्छा। लिखित स्रोतों का अभाव उनमें से नहीं था: वह संस्कृत ग्रंथों पर बहुत निर्भर रहा। अन्य तीन विकल्प उसकी बताई बाधाओं को ही दोहराते हैं।','csat-l4-s04-rc-p03-a-barrier-he-did-not-name','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Al-Biruni was born in 973 in Khwarizm, in Central Asia. Taken to Ghazni by Sultan Mahmud in 1017, he later spent years among Brahmana scholars in the Punjab, learning Sanskrit, and wrote in Arabic a long account of India, the Kitab-ul-Hind. He was unusually aware of how hard it is to understand a society from outside, and he named three barriers. The first was language: Sanskrit differed so much from Arabic and Persian that ideas could not easily be carried from one to the other. The second was the difference in religious beliefs and practices. The third was the self-absorption of the local people, which he felt made them unwilling to share what they knew with outsiders. To overcome these, he relied heavily on Sanskrit texts, and he looked for parallels in societies his readers knew, noting, for instance, that ancient Persia too had recognised four social categories. His account is valuable not because it is free of bias -- built on texts that laid down how society ought to be ordered, it often presents that ideal rather than everyday practice -- but because he named his difficulties openly.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अल-बिरूनी का जन्म 973 में मध्य एशिया के ख़्वारिज़्म में हुआ था। 1017 में सुल्तान महमूद द्वारा ग़ज़नी ले जाए जाने के बाद उसने वर्षों तक पंजाब में ब्राह्मण विद्वानों के बीच रहकर संस्कृत सीखी, और अरबी में भारत का एक लंबा विवरण, किताब-उल-हिंद, लिखा। वह असाधारण रूप से जानता था कि किसी समाज को बाहर से समझना कितना कठिन है, और उसने तीन बाधाएँ बताईं। पहली भाषा थी: संस्कृत अरबी और फ़ारसी से इतनी भिन्न थी कि विचारों को एक से दूसरी में आसानी से नहीं ले जाया जा सकता था। दूसरी धार्मिक विश्वासों और प्रथाओं का अंतर थी। तीसरी स्थानीय लोगों का आत्म-केंद्रित होना थी, जिसके कारण, उसे लगा, वे जो जानते थे उसे बाहरी लोगों के साथ बाँटना नहीं चाहते थे। इन पर पार पाने के लिए वह संस्कृत ग्रंथों पर बहुत निर्भर रहा, और उसने अपने पाठकों के परिचित समाजों में समानताएँ खोजीं, उदाहरण के लिए यह बताते हुए कि प्राचीन फ़ारस में भी चार सामाजिक वर्ग माने गए थे। उसका विवरण इसलिए मूल्यवान नहीं कि वह पूर्वाग्रह से मुक्त है -- उन ग्रंथों पर आधारित होने के कारण जो बताते थे कि समाज को कैसे व्यवस्थित होना चाहिए, वह प्रायः रोज़मर्रा के व्यवहार के बजाय उस आदर्श को प्रस्तुत करता है -- बल्कि इसलिए कि उसने अपनी कठिनाइयों को खुलकर बताया।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["A historian using Al-Biruni''s account should check what it says about everyday life against other kinds of evidence.", "Al-Biruni drew comparisons with societies familiar to his readers to help them understand what was unfamiliar."], "statements_hi": ["अल-बिरूनी के विवरण का उपयोग करने वाले इतिहासकार को रोज़मर्रा के जीवन के बारे में उसकी बातों को अन्य प्रकार के साक्ष्यों से मिलाना चाहिए।", "अल-बिरूनी ने अपने पाठकों के परिचित समाजों से तुलना की, ताकि उन्हें अपरिचित बातें समझने में सहायता मिले।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p03", "csat_order": 23}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are valid. The passage says Al-Biruni''s account, built on texts about how society ought to be ordered, often presents that ideal rather than everyday practice -- so a historian would do well to check what it says about daily life against other evidence (1). And it says he looked for parallels in societies his readers knew, such as ancient Persia''s four categories: a way of making the unfamiliar easier for them to grasp (2).','दोनों वैध हैं। परिच्छेद कहता है कि अल-बिरूनी का विवरण, इस बारे में ग्रंथों पर आधारित होने के कारण कि समाज को कैसे व्यवस्थित होना चाहिए, प्रायः रोज़मर्रा के व्यवहार के बजाय उस आदर्श को प्रस्तुत करता है -- इसलिए इतिहासकार के लिए अच्छा होगा कि वह दैनिक जीवन के बारे में उसकी बातों को अन्य साक्ष्यों से मिलाए (1)। और वह कहता है कि उसने अपने पाठकों के परिचित समाजों में समानताएँ खोजीं, जैसे प्राचीन फ़ारस के चार वर्ग: अपरिचित को उनके लिए समझना आसान बनाने का एक तरीक़ा (2)।','csat-l4-s04-rc-p03-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','medium','A time such as 12:21 on a 24-hour clock that shows hours and minutes reads the same backwards as forwards. How many such times are there in one day, counting from midnight, 00:00, to 23:59?','घंटे और मिनट दिखाने वाली 24-घंटे की घड़ी पर 12:21 जैसा समय आगे और पीछे से एक जैसा पढ़ा जाता है। आधी रात, 00:00, से 23:59 तक गिनने पर एक दिन में ऐसे कितने समय होते हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 24}'::jsonb,'[{"id": "a", "body": "6", "body_hi": "6", "isCorrect": false}, {"id": "b", "body": "10", "body_hi": "10", "isCorrect": false}, {"id": "c", "body": "15", "body_hi": "15", "isCorrect": false}, {"id": "d", "body": "16", "body_hi": "16", "isCorrect": true}]'::jsonb,2.5,0.83,'For HH:MM to read the same backwards, the minutes must be the hour''s digits reversed, and that reversed number must be a valid minute (below 60). Hours 00 to 05 give 00:00, 01:10, 02:20, 03:30, 04:40, 05:50 (6); hours 06 to 09 would need minutes 60 to 90; 10 to 15 give 10:01 to 15:51 (6); 16 to 19 fail; 20 to 23 give 20:02 to 23:32 (4). In all 16. 15 leaves out 00:00; 6 and 10 stop part of the way.','HH:MM के पीछे से एक जैसा पढ़े जाने के लिए मिनट घंटे के अंकों का उलटा होने चाहिए, और वह उलटी संख्या एक वैध मिनट (60 से कम) होनी चाहिए। घंटे 00 से 05 देते हैं 00:00, 01:10, 02:20, 03:30, 04:40, 05:50 (6); घंटे 06 से 09 के लिए मिनट 60 से 90 चाहिए; 10 से 15 देते हैं 10:01 से 15:51 (6); 16 से 19 विफल; 20 से 23 देते हैं 20:02 से 23:32 (4)। कुल 16। 15, 00:00 को छोड़ देता है; 6 और 10 बीच में रुक जाते हैं।','csat-l4-s04-qa-ph-palindromic-times','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','hard','''If a student practises every day, she will pass the examination. Meera does not practise every day. So Meera will not pass the examination.'' Which one of the following arguments has the same flaw?','''यदि कोई विद्यार्थी हर दिन अभ्यास करती है, तो वह परीक्षा में उत्तीर्ण होगी। मीरा हर दिन अभ्यास नहीं करती। इसलिए मीरा परीक्षा में उत्तीर्ण नहीं होगी।'' निम्नलिखित में से किस तर्क में वही त्रुटि है?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 25}'::jsonb,'[{"id": "a", "body": "If a fruit is a mango, it tastes sweet. This fruit tastes sweet, so this fruit must be a mango.", "body_hi": "यदि कोई फल आम है, तो वह मीठा होता है। यह फल मीठा है, इसलिए यह फल अवश्य आम है।", "isCorrect": false}, {"id": "b", "body": "If it rains at night, the ground is wet in the morning. The ground is dry this morning, so it did not rain.", "body_hi": "यदि रात में वर्षा होती है, तो सुबह ज़मीन गीली रहती है। आज सुबह ज़मीन सूखी है, इसलिए वर्षा नहीं हुई।", "isCorrect": false}, {"id": "c", "body": "If a train is more than an hour late, the passengers complain. Today''s train is two hours late, so they will complain.", "body_hi": "यदि कोई रेलगाड़ी एक घंटे से अधिक देर से है, तो यात्री शिकायत करते हैं। आज की रेलगाड़ी दो घंटे देर से है, इसलिए वे शिकायत करेंगे।", "isCorrect": false}, {"id": "d", "body": "If a shop is in the main market, it is crowded. This shop is not in the main market, so it is not crowded.", "body_hi": "यदि कोई दुकान मुख्य बाज़ार में है, तो उसमें भीड़ रहती है। यह दुकान मुख्य बाज़ार में नहीं है, इसलिए इसमें भीड़ नहीं रहती।", "isCorrect": true}]'::jsonb,2.5,0.83,'The original argument denies the condition (''does not practise every day'') and concludes that the result will not follow -- but daily practice was offered as one way to pass, not the only way. The shop argument makes exactly this move: a shop outside the main market may still be crowded. The mango argument has a different flaw, reasoning back from the result to the condition (other fruits are sweet too). The wet-ground and late-train arguments are both valid: one rules the condition out because the result did not happen, the other applies the rule to a case that meets it.','मूल तर्क शर्त को नकारता है (''हर दिन अभ्यास नहीं करती'') और निष्कर्ष निकालता है कि परिणाम नहीं होगा -- पर दैनिक अभ्यास उत्तीर्ण होने का एक रास्ता बताया गया था, एकमात्र नहीं। दुकान वाला तर्क ठीक यही करता है: मुख्य बाज़ार के बाहर की दुकान में भी भीड़ हो सकती है। आम वाले तर्क में अलग त्रुटि है, जो परिणाम से उलटकर शर्त तक तर्क करता है (और फल भी मीठे होते हैं)। गीली ज़मीन और देर से चल रही रेलगाड़ी वाले दोनों तर्क वैध हैं: एक परिणाम न होने से शर्त को ख़ारिज करता है, दूसरा नियम को ऐसी स्थिति पर लागू करता है जो उसे पूरा करती है।','csat-l4-s04-lr-sc-an-argument-that-denies-its-own-condition','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','hard','Four men and four women are to sit at a round table with eight chairs so that men and women sit in alternate chairs. In how many ways can this be done, if seatings that differ only by everyone moving round the same number of places are counted as the same?','चार पुरुष और चार महिलाएँ आठ कुर्सियों वाली एक गोल मेज़ पर ऐसे बैठने हैं कि पुरुष और महिलाएँ बारी-बारी की कुर्सियों पर हों। यदि वे व्यवस्थाएँ जिनमें केवल सब लोग समान स्थान घूम जाते हैं, एक ही मानी जाएँ, तो यह कितने तरीक़ों से किया जा सकता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 26}'::jsonb,'[{"id": "a", "body": "72", "body_hi": "72", "isCorrect": false}, {"id": "b", "body": "96", "body_hi": "96", "isCorrect": false}, {"id": "c", "body": "120", "body_hi": "120", "isCorrect": false}, {"id": "d", "body": "144", "body_hi": "144", "isCorrect": true}]'::jsonb,2.5,0.83,'Seat the men first. Round a table, the four men can be arranged in (4 - 1)! = 6 ways. That fixes four alternate chairs between them, and the four women can fill those in 4! = 24 ways, since the chairs are now distinguishable. In all 6 × 24 = 144. 72 halves the count, as if mirror images were the same; 120 and 96 have no basis.','पहले पुरुषों को बैठाइए। गोल मेज़ पर चार पुरुष (4 - 1)! = 6 तरीक़ों से बैठ सकते हैं। इससे उनके बीच चार बारी-बारी की कुर्सियाँ तय हो जाती हैं, और चार महिलाएँ उन्हें 4! = 24 तरीक़ों से भर सकती हैं, क्योंकि अब कुर्सियाँ अलग-अलग पहचानी जा सकती हैं। कुल 6 × 24 = 144। 72 गिनती को आधा कर देता है, मानो दर्पण-प्रतिबिंब एक ही हों; 120 और 96 का कोई आधार नहीं।','csat-l4-s04-qa-pc-couples-seated-alternately','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','What is the sum of all the digits used in writing the numbers from 1 to 99?','1 से 99 तक की संख्याएँ लिखने में प्रयुक्त सभी अंकों का योग क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 27}'::jsonb,'[{"id": "a", "body": "900", "body_hi": "900", "isCorrect": true}, {"id": "b", "body": "990", "body_hi": "990", "isCorrect": false}, {"id": "c", "body": "1,000", "body_hi": "1,000", "isCorrect": false}, {"id": "d", "body": "4,950", "body_hi": "4,950", "isCorrect": false}]'::jsonb,2.5,0.83,'In the units place each digit 0 to 9 appears 10 times, giving 10 × 45 = 450. In the tens place each digit 1 to 9 appears 10 times (10-19, 20-29, ...), another 450. In all 900. 4,950 adds the numbers themselves, not their digits; 990 and 1,000 have no basis.','इकाई के स्थान पर 0 से 9 तक हर अंक 10 बार आता है, जिससे 10 × 45 = 450 मिलता है। दहाई के स्थान पर 1 से 9 तक हर अंक 10 बार आता है (10-19, 20-29, ...), और 450। कुल 900। 4,950 संख्याओं को जोड़ता है, उनके अंकों को नहीं; 990 और 1,000 का कोई आधार नहीं।','csat-l4-s04-qa-nt-the-digits-of-1-to-99-added','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','medium','Which one of the following sets of lengths can be the three sides of a triangle?','निम्नलिखित में से लंबाइयों का कौन-सा समूह किसी त्रिभुज की तीन भुजाएँ हो सकता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 28}'::jsonb,'[{"id": "a", "body": "10 cm, 12 cm and 25 cm", "body_hi": "10 सेमी, 12 सेमी और 25 सेमी", "isCorrect": false}, {"id": "b", "body": "3 cm, 4 cm and 8 cm", "body_hi": "3 सेमी, 4 सेमी और 8 सेमी", "isCorrect": false}, {"id": "c", "body": "1 cm, 2 cm and 3 cm", "body_hi": "1 सेमी, 2 सेमी और 3 सेमी", "isCorrect": false}, {"id": "d", "body": "5 cm, 6 cm and 10 cm", "body_hi": "5 सेमी, 6 सेमी और 10 सेमी", "isCorrect": true}]'::jsonb,2.5,0.83,'Three lengths make a triangle only if the two shorter ones together are longer than the longest. 5 + 6 = 11 > 10, so 5, 6 and 10 work. 10 + 12 = 22 < 25 and 3 + 4 = 7 < 8 fall short; 1 + 2 = 3 only equals 3, which flattens the ''triangle'' into a straight line.','तीन लंबाइयाँ त्रिभुज तभी बनाती हैं जब दो छोटी मिलकर सबसे लंबी से अधिक हों। 5 + 6 = 11 > 10, इसलिए 5, 6 और 10 काम करती हैं। 10 + 12 = 22 < 25 और 3 + 4 = 7 < 8 कम पड़ते हैं; 1 + 2 = 3 केवल 3 के बराबर है, जो ''त्रिभुज'' को एक सीधी रेखा में चपटा कर देता है।','csat-l4-s04-qa-gm-sides-that-can-make-a-triangle','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Charles Darwin''s last book, published in 1881, the year before his death, was about earthworms. Over some forty years he had watched them in his garden and fields, measured the soil they brought up, and even tested whether they responded to sound by having music played to them; they responded to vibration, not to sound. He found that worms swallow soil, pass it through their bodies and leave it on the surface as fine castings, so that over the years stones and the remains of old buildings sink slowly beneath a layer of new earth. Each worm moves very little, but there are so many of them, working year after year, that the whole of a field''s topsoil passes through their bodies again and again over the centuries. The book sold well, and it showed a way of thinking that ran through all of Darwin''s work: that small causes, repeated over long periods, can produce large effects. It is a habit of mind easily lost whenever we judge a force by how dramatic it looks rather than by how long it acts.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
चार्ल्स डार्विन की अंतिम पुस्तक, जो 1881 में, उनकी मृत्यु से एक वर्ष पहले, प्रकाशित हुई, केंचुओं के बारे में थी। लगभग चालीस वर्षों तक उन्होंने अपने बग़ीचे और खेतों में उन्हें देखा था, उनके द्वारा ऊपर लाई गई मिट्टी नापी थी, और यह भी परखा था कि क्या वे ध्वनि पर प्रतिक्रिया करते हैं, उनके लिए संगीत बजवाकर; वे कंपन पर प्रतिक्रिया करते थे, ध्वनि पर नहीं। उन्होंने पाया कि केंचुए मिट्टी निगलते हैं, उसे अपने शरीर से गुज़ारते हैं और सतह पर महीन विष्ठा के रूप में छोड़ देते हैं, जिससे वर्षों में पत्थर और पुरानी इमारतों के अवशेष धीरे-धीरे नई मिट्टी की परत के नीचे धँसते जाते हैं। हर केंचुआ बहुत कम चलता है, पर वे इतने अधिक हैं, और वर्ष-दर-वर्ष काम करते हैं, कि सदियों में किसी खेत की पूरी ऊपरी मिट्टी बार-बार उनके शरीर से होकर गुज़रती है। पुस्तक ख़ूब बिकी, और उसने सोचने का वह ढंग दिखाया जो डार्विन के पूरे काम में चलता है: कि छोटे कारण, लंबे समय तक दोहराए जाने पर, बड़े प्रभाव पैदा कर सकते हैं। सोचने की यह आदत तब आसानी से छूट जाती है जब भी हम किसी शक्ति को इससे आँकते हैं कि वह कितनी नाटकीय दिखती है, इससे नहीं कि वह कितने समय तक काम करती है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p04", "csat_order": 29}'::jsonb,'[{"id": "a", "body": "Earthworms are the most important of all the animals for the health of the soil in a farmer''s field.", "body_hi": "किसी किसान के खेत की मिट्टी के स्वास्थ्य के लिए केंचुए धरती के सभी जीवों में सबसे अधिक महत्त्वपूर्ण हैं।", "isCorrect": false}, {"id": "b", "body": "Small effects repeated over a long time can add up to large changes, as Darwin''s worms show.", "body_hi": "लंबे समय तक दोहराए गए छोटे प्रभाव मिलकर बड़े परिवर्तन ला सकते हैं, जैसा डार्विन के केंचुए दिखाते हैं।", "isCorrect": true}, {"id": "c", "body": "Darwin''s book on earthworms was more popular with readers than any other book that he ever wrote.", "body_hi": "केंचुओं पर डार्विन की पुस्तक पाठकों में उनकी लिखी किसी भी अन्य पुस्तक से अधिक लोकप्रिय थी।", "isCorrect": false}, {"id": "d", "body": "Forces that look dramatic always do more to shape the surface of the Earth than gradual ones can do.", "body_hi": "नाटकीय दिखने वाली शक्तियाँ पृथ्वी की सतह को आकार देने में हमेशा धीमी शक्तियों से अधिक काम करती हैं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage uses Darwin''s study of worms to make a general point: tiny effects repeated over a long time can reshape the land, and we underrate such forces when we look only for the dramatic. It does not rank worms above all other animals; it says the book ''sold well'', not that it outsold his other books; and it warns against judging forces by how dramatic they look, the opposite of saying dramatic forces always matter more.','परिच्छेद डार्विन के केंचुओं के अध्ययन से एक सामान्य बात कहता है: लंबे समय तक दोहराए गए बहुत छोटे प्रभाव भूमि को नया रूप दे सकते हैं, और जब हम केवल नाटकीय चीज़ें खोजते हैं तो ऐसी शक्तियों को कम आँकते हैं। वह केंचुओं को अन्य सभी जीवों से ऊपर नहीं रखता; वह कहता है कि पुस्तक ''ख़ूब बिकी'', यह नहीं कि वह उनकी अन्य पुस्तकों से अधिक बिकी; और वह शक्तियों को उनके नाटकीय दिखने से आँकने के विरुद्ध चेतावनी देता है, जो यह कहने का उलटा है कि नाटकीय शक्तियाँ हमेशा अधिक मायने रखती हैं।','csat-l4-s04-rc-p04-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Charles Darwin''s last book, published in 1881, the year before his death, was about earthworms. Over some forty years he had watched them in his garden and fields, measured the soil they brought up, and even tested whether they responded to sound by having music played to them; they responded to vibration, not to sound. He found that worms swallow soil, pass it through their bodies and leave it on the surface as fine castings, so that over the years stones and the remains of old buildings sink slowly beneath a layer of new earth. Each worm moves very little, but there are so many of them, working year after year, that the whole of a field''s topsoil passes through their bodies again and again over the centuries. The book sold well, and it showed a way of thinking that ran through all of Darwin''s work: that small causes, repeated over long periods, can produce large effects. It is a habit of mind easily lost whenever we judge a force by how dramatic it looks rather than by how long it acts.

Which one of the following shows the error that the passage warns against in its last sentence?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
चार्ल्स डार्विन की अंतिम पुस्तक, जो 1881 में, उनकी मृत्यु से एक वर्ष पहले, प्रकाशित हुई, केंचुओं के बारे में थी। लगभग चालीस वर्षों तक उन्होंने अपने बग़ीचे और खेतों में उन्हें देखा था, उनके द्वारा ऊपर लाई गई मिट्टी नापी थी, और यह भी परखा था कि क्या वे ध्वनि पर प्रतिक्रिया करते हैं, उनके लिए संगीत बजवाकर; वे कंपन पर प्रतिक्रिया करते थे, ध्वनि पर नहीं। उन्होंने पाया कि केंचुए मिट्टी निगलते हैं, उसे अपने शरीर से गुज़ारते हैं और सतह पर महीन विष्ठा के रूप में छोड़ देते हैं, जिससे वर्षों में पत्थर और पुरानी इमारतों के अवशेष धीरे-धीरे नई मिट्टी की परत के नीचे धँसते जाते हैं। हर केंचुआ बहुत कम चलता है, पर वे इतने अधिक हैं, और वर्ष-दर-वर्ष काम करते हैं, कि सदियों में किसी खेत की पूरी ऊपरी मिट्टी बार-बार उनके शरीर से होकर गुज़रती है। पुस्तक ख़ूब बिकी, और उसने सोचने का वह ढंग दिखाया जो डार्विन के पूरे काम में चलता है: कि छोटे कारण, लंबे समय तक दोहराए जाने पर, बड़े प्रभाव पैदा कर सकते हैं। सोचने की यह आदत तब आसानी से छूट जाती है जब भी हम किसी शक्ति को इससे आँकते हैं कि वह कितनी नाटकीय दिखती है, इससे नहीं कि वह कितने समय तक काम करती है।

निम्नलिखित में से कौन-सा उस भूल को दिखाता है जिसके विरुद्ध परिच्छेद अपने अंतिम वाक्य में चेतावनी देता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p04", "csat_order": 30}'::jsonb,'[{"id": "a", "body": "Studying a single violent earthquake in great detail to learn exactly how the ground moved during it", "body_hi": "किसी एक प्रचंड भूकंप का बहुत विस्तार से अध्ययन करना ताकि ठीक-ठीक पता चले कि उसमें ज़मीन कैसे हिली", "isCorrect": false}, {"id": "b", "body": "Measuring the soil that worms bring to the surface over several years to estimate their total effect", "body_hi": "केंचुओं द्वारा कई वर्षों में सतह पर लाई गई मिट्टी नापकर उनके कुल प्रभाव का अनुमान लगाना", "isCorrect": false}, {"id": "c", "body": "Testing whether worms respond to music, to other sounds or to the vibration of the ground beneath them", "body_hi": "यह परखना कि केंचुए संगीत, अन्य ध्वनियों या अपने नीचे की ज़मीन के कंपन पर प्रतिक्रिया करते हैं या नहीं", "isCorrect": false}, {"id": "d", "body": "Ignoring the slow loss of a hillside''s soil because no single rainstorm washes much of it away", "body_hi": "किसी ढलान की मिट्टी के धीमे बहाव को इसलिए अनदेखा करना कि कोई एक वर्षा उसका अधिक भाग नहीं बहाती", "isCorrect": true}]'::jsonb,2.5,0.83,'The warning is against judging a force by how dramatic it looks rather than by how long it acts. Dismissing the steady loss of a hillside''s topsoil because no single storm removes much of it is exactly that error: each storm is small, but the loss accumulates. Studying one earthquake closely is not a judgement about which forces matter; measuring castings over years is Darwin''s own method; and testing worms'' responses is part of his careful observation, not an error.','चेतावनी किसी शक्ति को इससे आँकने के विरुद्ध है कि वह कितनी नाटकीय दिखती है, इससे नहीं कि वह कितने समय तक काम करती है। किसी पहाड़ी ढलान की ऊपरी मिट्टी के लगातार बहने को इसलिए नकारना कि कोई एक तूफ़ान उसका अधिक भाग नहीं बहाता, ठीक यही भूल है: हर तूफ़ान छोटा है, पर हानि जुड़ती जाती है। एक भूकंप का बारीकी से अध्ययन यह निर्णय नहीं कि कौन-सी शक्तियाँ मायने रखती हैं; वर्षों तक विष्ठा नापना डार्विन की अपनी पद्धति है; और केंचुओं की प्रतिक्रियाएँ परखना उनके सावधान अवलोकन का भाग है, भूल नहीं।','csat-l4-s04-rc-p04-the-error-in-the-last-sentence','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Charles Darwin''s last book, published in 1881, the year before his death, was about earthworms. Over some forty years he had watched them in his garden and fields, measured the soil they brought up, and even tested whether they responded to sound by having music played to them; they responded to vibration, not to sound. He found that worms swallow soil, pass it through their bodies and leave it on the surface as fine castings, so that over the years stones and the remains of old buildings sink slowly beneath a layer of new earth. Each worm moves very little, but there are so many of them, working year after year, that the whole of a field''s topsoil passes through their bodies again and again over the centuries. The book sold well, and it showed a way of thinking that ran through all of Darwin''s work: that small causes, repeated over long periods, can produce large effects. It is a habit of mind easily lost whenever we judge a force by how dramatic it looks rather than by how long it acts.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
चार्ल्स डार्विन की अंतिम पुस्तक, जो 1881 में, उनकी मृत्यु से एक वर्ष पहले, प्रकाशित हुई, केंचुओं के बारे में थी। लगभग चालीस वर्षों तक उन्होंने अपने बग़ीचे और खेतों में उन्हें देखा था, उनके द्वारा ऊपर लाई गई मिट्टी नापी थी, और यह भी परखा था कि क्या वे ध्वनि पर प्रतिक्रिया करते हैं, उनके लिए संगीत बजवाकर; वे कंपन पर प्रतिक्रिया करते थे, ध्वनि पर नहीं। उन्होंने पाया कि केंचुए मिट्टी निगलते हैं, उसे अपने शरीर से गुज़ारते हैं और सतह पर महीन विष्ठा के रूप में छोड़ देते हैं, जिससे वर्षों में पत्थर और पुरानी इमारतों के अवशेष धीरे-धीरे नई मिट्टी की परत के नीचे धँसते जाते हैं। हर केंचुआ बहुत कम चलता है, पर वे इतने अधिक हैं, और वर्ष-दर-वर्ष काम करते हैं, कि सदियों में किसी खेत की पूरी ऊपरी मिट्टी बार-बार उनके शरीर से होकर गुज़रती है। पुस्तक ख़ूब बिकी, और उसने सोचने का वह ढंग दिखाया जो डार्विन के पूरे काम में चलता है: कि छोटे कारण, लंबे समय तक दोहराए जाने पर, बड़े प्रभाव पैदा कर सकते हैं। सोचने की यह आदत तब आसानी से छूट जाती है जब भी हम किसी शक्ति को इससे आँकते हैं कि वह कितनी नाटकीय दिखती है, इससे नहीं कि वह कितने समय तक काम करती है।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["According to the passage, worms carry soil down from the surface and bury it deep in the ground.", "Objects lying on the ground slowly become buried because worms deposit fresh soil on the surface around and above them."], "statements_hi": ["परिच्छेद के अनुसार केंचुए सतह से मिट्टी नीचे ले जाते हैं और उसे ज़मीन में गहरे दबा देते हैं।", "ज़मीन पर पड़ी वस्तुएँ धीरे-धीरे इसलिए दब जाती हैं कि केंचुए उनके आसपास और ऊपर सतह पर ताज़ी मिट्टी जमा करते हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "precision", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p04", "csat_order": 31}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is valid. The passage says worms leave swallowed soil on the surface as castings, so that stones and old remains sink beneath a layer of new earth: objects are buried from above. 1 reverses this: the worms bring soil up to the surface; they do not carry surface soil down to bury it.','केवल 2 वैध है। परिच्छेद कहता है कि केंचुए निगली हुई मिट्टी को सतह पर विष्ठा के रूप में छोड़ते हैं, जिससे पत्थर और पुराने अवशेष नई मिट्टी की परत के नीचे धँस जाते हैं: वस्तुएँ ऊपर से दबती हैं। 1 इसे उलट देता है: केंचुए मिट्टी को ऊपर सतह पर लाते हैं; वे सतह की मिट्टी को नीचे ले जाकर नहीं दबाते।','csat-l4-s04-rc-p04-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Syllogism','mcq','easy','Which one of the following best describes how the classes ''women'', ''mothers'' and ''doctors'' are related?','निम्नलिखित में से कौन-सा सबसे अच्छा वर्णन करता है कि ''महिलाएँ'', ''माताएँ'' और ''डॉक्टर'' वर्ग आपस में कैसे संबंधित हैं?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 32}'::jsonb,'[{"id": "a", "body": "Women lie wholly within mothers, and doctors overlap both of them.", "body_hi": "महिलाएँ पूरी तरह माताओं के भीतर हैं, और डॉक्टर दोनों से आंशिक रूप से मिलते हैं।", "isCorrect": false}, {"id": "b", "body": "Mothers lie wholly within women, and doctors overlap both of them.", "body_hi": "माताएँ पूरी तरह महिलाओं के भीतर हैं, और डॉक्टर दोनों से आंशिक रूप से मिलते हैं।", "isCorrect": true}, {"id": "c", "body": "Mothers lie wholly within women, and doctors lie wholly within mothers.", "body_hi": "माताएँ पूरी तरह महिलाओं के भीतर हैं, और डॉक्टर पूरी तरह माताओं के भीतर हैं।", "isCorrect": false}, {"id": "d", "body": "The three classes overlap, but none of them lies wholly within another.", "body_hi": "तीनों वर्ग आपस में मिलते हैं, पर उनमें से कोई दूसरे के पूरी तरह भीतर नहीं है।", "isCorrect": false}]'::jsonb,2.5,0.83,'Every mother is a woman, but not every woman is a mother, so mothers lie wholly within women. Some doctors are women, some of them mothers, and some doctors are men, who are neither -- so doctors overlap both classes without lying inside either. Women do not lie within mothers; doctors are not all mothers; and mothers do lie wholly within women.','हर माता महिला है, पर हर महिला माता नहीं, इसलिए माताएँ पूरी तरह महिलाओं के भीतर हैं। कुछ डॉक्टर महिलाएँ हैं, उनमें से कुछ माताएँ, और कुछ डॉक्टर पुरुष हैं, जो दोनों में से कुछ नहीं -- इसलिए डॉक्टर दोनों वर्गों से आंशिक रूप से मिलते हैं, किसी के भीतर हुए बिना। महिलाएँ माताओं के भीतर नहीं हैं; सभी डॉक्टर माताएँ नहीं हैं; और माताएँ सचमुच पूरी तरह महिलाओं के भीतर हैं।','csat-l4-s04-lr-sy-women-mothers-and-doctors','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','All the two-digit numbers that can be formed from the digits 1, 2 and 3, without using a digit twice in the same number, are added together. What is the total?','अंकों 1, 2 और 3 से, एक ही संख्या में किसी अंक को दो बार प्रयोग किए बिना, बन सकने वाली दो अंकों की सभी संख्याओं को जोड़ा जाता है। योग क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 33}'::jsonb,'[{"id": "a", "body": "66", "body_hi": "66", "isCorrect": false}, {"id": "b", "body": "123", "body_hi": "123", "isCorrect": false}, {"id": "c", "body": "132", "body_hi": "132", "isCorrect": true}, {"id": "d", "body": "264", "body_hi": "264", "isCorrect": false}]'::jsonb,2.5,0.83,'The numbers are 12, 13, 21, 23, 31 and 32. Each digit appears twice in the tens place and twice in the units place, so the total is (1 + 2 + 3) × 2 × (10 + 1) = 6 × 22 = 132. 66 counts each digit only once in each place; 264 doubles the total; 123 has no basis.','संख्याएँ 12, 13, 21, 23, 31 और 32 हैं। हर अंक दहाई के स्थान पर दो बार और इकाई के स्थान पर दो बार आता है, इसलिए योग (1 + 2 + 3) × 2 × (10 + 1) = 6 × 22 = 132 है। 66 हर अंक को हर स्थान पर केवल एक बार गिनता है; 264 योग को दोगुना कर देता है; 123 का कोई आधार नहीं।','csat-l4-s04-qa-nt-two-digit-numbers-from-1-2-and-3','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','medium','1 January 2028 is a Saturday. On which day of the week does 1 March 2028 fall?','1 जनवरी 2028 शनिवार है। 1 मार्च 2028 सप्ताह के किस दिन पड़ता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 34}'::jsonb,'[{"id": "a", "body": "Tuesday", "body_hi": "मंगलवार", "isCorrect": false}, {"id": "b", "body": "Wednesday", "body_hi": "बुधवार", "isCorrect": true}, {"id": "c", "body": "Thursday", "body_hi": "गुरुवार", "isCorrect": false}, {"id": "d", "body": "Saturday", "body_hi": "शनिवार", "isCorrect": false}]'::jsonb,2.5,0.83,'2028 is a leap year, so January has 31 days and February 29: 1 March is 31 + 29 = 60 days after 1 January. 60 = 8 weeks and 4 days, so it falls four days after Saturday -- on a Wednesday. Tuesday comes from giving February only 28 days; Thursday and Saturday have no basis.','2028 अधिवर्ष है, इसलिए जनवरी में 31 और फ़रवरी में 29 दिन हैं: 1 मार्च, 1 जनवरी से 31 + 29 = 60 दिन बाद है। 60 = 8 सप्ताह और 4 दिन, इसलिए वह शनिवार के चार दिन बाद -- बुधवार को पड़ता है। मंगलवार फ़रवरी को केवल 28 दिन देने से आता है; गुरुवार और शनिवार का कोई आधार नहीं।','csat-l4-s04-qa-ph-1-march-from-1-january','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','hard','A producer sells through an agent who keeps 10 per cent of the selling price as commission. By what percentage above the cost must the selling price be set so that the producer still makes a profit of 20 per cent on the cost?','एक उत्पादक एक एजेंट के माध्यम से बेचता है जो बिक्री मूल्य का 10 प्रतिशत कमीशन के रूप में रखता है। बिक्री मूल्य लागत से कितने प्रतिशत ऊपर रखा जाए ताकि उत्पादक को लागत पर फिर भी 20 प्रतिशत लाभ हो?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 35}'::jsonb,'[{"id": "a", "body": "20 per cent", "body_hi": "20 प्रतिशत", "isCorrect": false}, {"id": "b", "body": "30 per cent", "body_hi": "30 प्रतिशत", "isCorrect": false}, {"id": "c", "body": "32 per cent", "body_hi": "32 प्रतिशत", "isCorrect": false}, {"id": "d", "body": "33⅓ per cent", "body_hi": "33⅓ प्रतिशत", "isCorrect": true}]'::jsonb,2.5,0.83,'The producer keeps 90 per cent of the selling price and wants this to be 120 per cent of the cost: 0.9 × SP = 1.2 × cost, so SP = 4/3 of the cost -- 33⅓ per cent above it. 30 per cent simply adds the 10 per cent commission to the 20 per cent profit; 32 per cent adds 10 per cent on top of the target (1.2 × 1.1 = 1.32) -- both forget that the commission is a tenth of the selling price, which is larger than either; 20 per cent ignores the commission.','उत्पादक बिक्री मूल्य का 90 प्रतिशत रखता है और चाहता है कि यह लागत का 120 प्रतिशत हो: 0.9 × बिक्री मूल्य = 1.2 × लागत, अतः बिक्री मूल्य लागत का 4/3 -- उससे 33⅓ प्रतिशत ऊपर। 30 प्रतिशत बस 10 प्रतिशत कमीशन को 20 प्रतिशत लाभ में जोड़ता है; 32 प्रतिशत लक्ष्य के ऊपर 10 प्रतिशत जोड़ता है (1.2 × 1.1 = 1.32) -- दोनों भूल जाते हैं कि कमीशन बिक्री मूल्य का दसवाँ भाग है, जो दोनों से बड़ा है; 20 प्रतिशत कमीशन को अनदेखा करता है।','csat-l4-s04-qa-pp-a-price-that-covers-an-agent-s-commission','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Blood Relation','mcq','hard','Pointing to a man, Neha said, ''His mother''s only grandchild is my daughter.'' Which one of the following must be true?','एक व्यक्ति की ओर संकेत करते हुए नेहा ने कहा, ''इसकी माँ की एकमात्र पोती/नातिन मेरी बेटी है।'' निम्नलिखित में से कौन-सा अवश्य सत्य है?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 36}'::jsonb,'[{"id": "a", "body": "Neha is the man''s wife.", "body_hi": "नेहा उस व्यक्ति की पत्नी है।", "isCorrect": false}, {"id": "b", "body": "Neha is the man''s sister.", "body_hi": "नेहा उस व्यक्ति की बहन है।", "isCorrect": false}, {"id": "c", "body": "Neha''s daughter is the man''s daughter.", "body_hi": "नेहा की बेटी उस व्यक्ति की बेटी है।", "isCorrect": false}, {"id": "d", "body": "The man has no son.", "body_hi": "उस व्यक्ति का कोई बेटा नहीं है।", "isCorrect": true}]'::jsonb,2.5,0.83,'Neha''s daughter is a grandchild of the man''s mother, so one of her parents is a child of that mother. That parent may be the man himself (Neha is then his wife), Neha (she is then his sister), or a brother of the man (Neha is then his sister-in-law). So none of ''wife'', ''sister'' or ''his daughter'' must hold. But in every case the man can have no child other than Neha''s daughter, since any child of his would be another grandchild of his mother. So he has no son.','नेहा की बेटी उस व्यक्ति की माँ की पोती/नातिन है, इसलिए उसके माता-पिता में से एक उस माँ की संतान है। वह व्यक्ति स्वयं हो सकता है (तब नेहा उसकी पत्नी है), नेहा हो सकती है (तब वह उसकी बहन है), या उस व्यक्ति का कोई भाई (तब नेहा उसकी भाभी है)। अतः ''पत्नी'', ''बहन'' या ''उसकी बेटी'' में से कोई अवश्य सत्य नहीं। पर हर स्थिति में उस व्यक्ति की नेहा की बेटी के अलावा कोई संतान नहीं हो सकती, क्योंकि उसकी कोई भी संतान उसकी माँ का एक और पोता या पोती होती। अतः उसका कोई बेटा नहीं है।','csat-l4-s04-lr-br-a-mother-s-only-grandchild','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Every autumn, tens of thousands of Amur falcons -- small birds of prey that breed in eastern Asia -- stop in Nagaland on their way to southern Africa, on one of the longest migrations of any bird of prey. In 2012, reports that villagers around the Doyang reservoir were trapping the birds in great numbers, for food and for sale, drew wide attention. What followed is often cited as a conservation success. Rather than relying only on bans and patrols, the forest department and conservation groups worked with village councils; some former hunters became guards and guides; schoolchildren formed eco-clubs; and villages such as Pangti came to see the falcons as a source of pride and of visitors. Within a few years the killing had largely stopped. The lesson is not that laws are useless -- hunting the falcons had been illegal throughout -- but that a law a community accepts does far more than one merely imposed on it. Protection lasts when the people who live beside a species gain more from its survival than from its loss.

Which one of the following statements best reflects the most logical and rational message conveyed by the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हर शरद ऋतु में दसियों हज़ार अमूर बाज़ -- शिकारी पक्षियों की एक छोटी जाति जो पूर्वी एशिया में प्रजनन करती है -- दक्षिणी अफ़्रीका की ओर जाते हुए नागालैंड में रुकते हैं, किसी भी शिकारी पक्षी के सबसे लंबे प्रवासों में से एक पर। 2012 में इन ख़बरों ने व्यापक ध्यान खींचा कि दोयांग जलाशय के आसपास के ग्रामीण इन पक्षियों को भोजन और बिक्री के लिए भारी संख्या में फँसा रहे थे। उसके बाद जो हुआ उसे प्रायः संरक्षण की एक सफलता के रूप में उद्धृत किया जाता है। केवल प्रतिबंधों और गश्त पर निर्भर रहने के बजाय वन विभाग और संरक्षण समूहों ने ग्राम परिषदों के साथ काम किया; कुछ पूर्व शिकारी रक्षक और मार्गदर्शक बन गए; स्कूली बच्चों ने इको-क्लब बनाए; और पांग्ती जैसे गाँव बाज़ों को गर्व और पर्यटकों का स्रोत मानने लगे। कुछ ही वर्षों में हत्याएँ लगभग रुक गईं। सीख यह नहीं कि क़ानून बेकार हैं -- बाज़ों का शिकार पूरे समय अवैध था -- बल्कि यह कि जिस क़ानून को समुदाय स्वीकार करता है वह केवल थोपे गए क़ानून से कहीं अधिक करता है। संरक्षण तब टिकता है जब किसी प्रजाति के पास रहने वाले लोगों को उसके नष्ट होने से अधिक उसके बचे रहने से लाभ हो।

निम्नलिखित में से कौन-सा कथन परिच्छेद द्वारा दिए गए सबसे तार्किक और विवेकपूर्ण संदेश को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p05", "csat_order": 37}'::jsonb,'[{"id": "a", "body": "Laws against hunting are useless and ought to be replaced everywhere by campaigns of awareness.", "body_hi": "शिकार के विरुद्ध क़ानून बेकार हैं और उन्हें हर जगह जागरूकता अभियानों से बदल दिया जाना चाहिए।", "isCorrect": false}, {"id": "b", "body": "The Amur falcon makes the longest migration of any bird in the world, from eastern Asia to Africa.", "body_hi": "अमूर बाज़ पूर्वी एशिया से अफ़्रीका तक दुनिया के किसी भी पक्षी का सबसे लंबा प्रवास करता है।", "isCorrect": false}, {"id": "c", "body": "Conservation works best when the people who live beside a species gain from protecting it.", "body_hi": "संरक्षण सबसे अच्छा तब काम करता है जब किसी प्रजाति के पास रहने वालों को उसकी रक्षा से लाभ हो।", "isCorrect": true}, {"id": "d", "body": "Birds that pass through a region cannot be protected there unless all fishing in it is stopped.", "body_hi": "किसी क्षेत्र से गुज़रने वाले पक्षियों की वहाँ रक्षा तब तक नहीं हो सकती जब तक वहाँ हर तरह की मछली पकड़ना बंद न हो।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage credits the turnaround to working with the community -- councils, former hunters, schools, villages that gained from the birds -- and concludes that protection lasts when local people gain from a species'' survival. It says the lesson is ''not that laws are useless''; it calls the falcons'' journey one of the longest of any bird of prey, not the longest of any bird; and it says nothing about fishing.','परिच्छेद इस बदलाव का श्रेय समुदाय के साथ काम करने को देता है -- परिषदें, पूर्व शिकारी, स्कूल, वे गाँव जिन्हें पक्षियों से लाभ हुआ -- और निष्कर्ष निकालता है कि संरक्षण तब टिकता है जब स्थानीय लोगों को किसी प्रजाति के बचे रहने से लाभ हो। वह कहता है कि सीख ''यह नहीं कि क़ानून बेकार हैं''; वह बाज़ों की यात्रा को किसी भी शिकारी पक्षी की सबसे लंबी यात्राओं में से एक कहता है, किसी भी पक्षी की सबसे लंबी नहीं; और वह मछली पकड़ने के बारे में कुछ नहीं कहता।','csat-l4-s04-rc-p05-message','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Every autumn, tens of thousands of Amur falcons -- small birds of prey that breed in eastern Asia -- stop in Nagaland on their way to southern Africa, on one of the longest migrations of any bird of prey. In 2012, reports that villagers around the Doyang reservoir were trapping the birds in great numbers, for food and for sale, drew wide attention. What followed is often cited as a conservation success. Rather than relying only on bans and patrols, the forest department and conservation groups worked with village councils; some former hunters became guards and guides; schoolchildren formed eco-clubs; and villages such as Pangti came to see the falcons as a source of pride and of visitors. Within a few years the killing had largely stopped. The lesson is not that laws are useless -- hunting the falcons had been illegal throughout -- but that a law a community accepts does far more than one merely imposed on it. Protection lasts when the people who live beside a species gain more from its survival than from its loss.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हर शरद ऋतु में दसियों हज़ार अमूर बाज़ -- शिकारी पक्षियों की एक छोटी जाति जो पूर्वी एशिया में प्रजनन करती है -- दक्षिणी अफ़्रीका की ओर जाते हुए नागालैंड में रुकते हैं, किसी भी शिकारी पक्षी के सबसे लंबे प्रवासों में से एक पर। 2012 में इन ख़बरों ने व्यापक ध्यान खींचा कि दोयांग जलाशय के आसपास के ग्रामीण इन पक्षियों को भोजन और बिक्री के लिए भारी संख्या में फँसा रहे थे। उसके बाद जो हुआ उसे प्रायः संरक्षण की एक सफलता के रूप में उद्धृत किया जाता है। केवल प्रतिबंधों और गश्त पर निर्भर रहने के बजाय वन विभाग और संरक्षण समूहों ने ग्राम परिषदों के साथ काम किया; कुछ पूर्व शिकारी रक्षक और मार्गदर्शक बन गए; स्कूली बच्चों ने इको-क्लब बनाए; और पांग्ती जैसे गाँव बाज़ों को गर्व और पर्यटकों का स्रोत मानने लगे। कुछ ही वर्षों में हत्याएँ लगभग रुक गईं। सीख यह नहीं कि क़ानून बेकार हैं -- बाज़ों का शिकार पूरे समय अवैध था -- बल्कि यह कि जिस क़ानून को समुदाय स्वीकार करता है वह केवल थोपे गए क़ानून से कहीं अधिक करता है। संरक्षण तब टिकता है जब किसी प्रजाति के पास रहने वाले लोगों को उसके नष्ट होने से अधिक उसके बचे रहने से लाभ हो।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["The killing reported in 2012 shows that a law can be in force without being obeyed.", "Once a community values a species, patrols and penalties are no longer needed to protect it anywhere."], "statements_hi": ["2012 में बताई गई हत्याएँ दिखाती हैं कि कोई क़ानून लागू रहते हुए भी माना न जाए, ऐसा हो सकता है।", "जब कोई समुदाय किसी प्रजाति को महत्त्व देने लगे, तो उसकी रक्षा के लिए कहीं भी गश्त और दंड की आवश्यकता नहीं रहती।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p05", "csat_order": 38}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 1 is valid. Hunting the falcons was illegal throughout, yet in 2012 villagers were trapping them in great numbers: a law can exist without being obeyed. 2 goes too far. The passage says the forest department relied ''not only'' on bans and patrols, which means they were still used alongside the work with villages; nothing suggests that enforcement can be dropped wherever a community values a species.','केवल 1 वैध है। बाज़ों का शिकार पूरे समय अवैध था, फिर भी 2012 में ग्रामीण उन्हें भारी संख्या में फँसा रहे थे: क़ानून हो सकता है और उसका पालन न हो। 2 बहुत आगे जाता है। परिच्छेद कहता है कि वन विभाग ''केवल'' प्रतिबंधों और गश्त पर निर्भर नहीं रहा, जिसका अर्थ है कि गाँवों के साथ काम के साथ-साथ उनका भी उपयोग होता रहा; कुछ भी यह नहीं बताता कि जहाँ भी कोई समुदाय किसी प्रजाति को महत्त्व दे वहाँ प्रवर्तन छोड़ा जा सकता है।','csat-l4-s04-rc-p05-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Every autumn, tens of thousands of Amur falcons -- small birds of prey that breed in eastern Asia -- stop in Nagaland on their way to southern Africa, on one of the longest migrations of any bird of prey. In 2012, reports that villagers around the Doyang reservoir were trapping the birds in great numbers, for food and for sale, drew wide attention. What followed is often cited as a conservation success. Rather than relying only on bans and patrols, the forest department and conservation groups worked with village councils; some former hunters became guards and guides; schoolchildren formed eco-clubs; and villages such as Pangti came to see the falcons as a source of pride and of visitors. Within a few years the killing had largely stopped. The lesson is not that laws are useless -- hunting the falcons had been illegal throughout -- but that a law a community accepts does far more than one merely imposed on it. Protection lasts when the people who live beside a species gain more from its survival than from its loss.

Which one of the following, if true, would most strengthen the passage''s explanation of why the killing stopped?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हर शरद ऋतु में दसियों हज़ार अमूर बाज़ -- शिकारी पक्षियों की एक छोटी जाति जो पूर्वी एशिया में प्रजनन करती है -- दक्षिणी अफ़्रीका की ओर जाते हुए नागालैंड में रुकते हैं, किसी भी शिकारी पक्षी के सबसे लंबे प्रवासों में से एक पर। 2012 में इन ख़बरों ने व्यापक ध्यान खींचा कि दोयांग जलाशय के आसपास के ग्रामीण इन पक्षियों को भोजन और बिक्री के लिए भारी संख्या में फँसा रहे थे। उसके बाद जो हुआ उसे प्रायः संरक्षण की एक सफलता के रूप में उद्धृत किया जाता है। केवल प्रतिबंधों और गश्त पर निर्भर रहने के बजाय वन विभाग और संरक्षण समूहों ने ग्राम परिषदों के साथ काम किया; कुछ पूर्व शिकारी रक्षक और मार्गदर्शक बन गए; स्कूली बच्चों ने इको-क्लब बनाए; और पांग्ती जैसे गाँव बाज़ों को गर्व और पर्यटकों का स्रोत मानने लगे। कुछ ही वर्षों में हत्याएँ लगभग रुक गईं। सीख यह नहीं कि क़ानून बेकार हैं -- बाज़ों का शिकार पूरे समय अवैध था -- बल्कि यह कि जिस क़ानून को समुदाय स्वीकार करता है वह केवल थोपे गए क़ानून से कहीं अधिक करता है। संरक्षण तब टिकता है जब किसी प्रजाति के पास रहने वाले लोगों को उसके नष्ट होने से अधिक उसके बचे रहने से लाभ हो।

निम्नलिखित में से कौन-सा, यदि सत्य हो, हत्याएँ रुकने की परिच्छेद की व्याख्या को सबसे अधिक मज़बूत करेगा?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p05", "csat_order": 39}'::jsonb,'[{"id": "a", "body": "Villages that earned from falcon-watching visitors stopped hunting sooner than those that did not.", "body_hi": "बाज़ देखने आने वाले पर्यटकों से कमाने वाले गाँवों ने बाक़ी गाँवों से पहले शिकार बंद किया।", "isCorrect": true}, {"id": "b", "body": "The number of forest patrols around the reservoir was increased sharply in the year after the reports.", "body_hi": "ख़बरों के बाद के वर्ष में जलाशय के आसपास वन विभाग की गश्त की संख्या तेज़ी से बढ़ा दी गई।", "isCorrect": false}, {"id": "c", "body": "Most Amur falcons now fly a shorter route to Africa that avoids Nagaland and the Doyang reservoir.", "body_hi": "अधिकांश अमूर बाज़ अब अफ़्रीका तक एक छोटे मार्ग से उड़ते हैं जो नागालैंड और दोयांग जलाशय से बचता है।", "isCorrect": false}, {"id": "d", "body": "The price paid for trapped falcons in the local markets rose steadily in the years after 2012.", "body_hi": "2012 के बाद के वर्षों में स्थानीय बाज़ारों में फँसाए गए बाज़ों का दाम लगातार बढ़ता गया।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage explains the change by what villages came to gain from the living birds. If villages that earned from falcon-watching visitors stopped hunting sooner than others, the timing would match that explanation. A sharp rise in patrols would point instead to enforcement; a new route avoiding Nagaland would mean there were simply fewer birds to kill; and a rise in the price of trapped falcons would, if anything, make hunting more tempting.','परिच्छेद बदलाव को इस बात से समझाता है कि गाँवों को जीवित पक्षियों से क्या लाभ होने लगा। यदि बाज़ देखने आने वाले पर्यटकों से कमाने वाले गाँवों ने अन्य गाँवों से पहले शिकार बंद किया, तो समय उस व्याख्या से मेल खाएगा। गश्त में तेज़ वृद्धि इसके बजाय प्रवर्तन की ओर संकेत करेगी; नागालैंड से बचने वाला नया मार्ग यह अर्थ देगा कि मारने के लिए पक्षी ही कम थे; और फँसाए गए बाज़ों के दाम में वृद्धि, यदि कुछ करती, तो शिकार को और लुभावना बनाती।','csat-l4-s04-rc-p05-what-strengthens-the-explanation','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','medium','Two runners take 16 seconds and 20 seconds to run 100 m. In a 100 m race between them, by how many metres does the faster one win?','दो धावक 100 मीटर दौड़ने में 16 सेकंड और 20 सेकंड लेते हैं। उनके बीच 100 मीटर की दौड़ में तेज़ धावक कितने मीटर से जीतता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 40}'::jsonb,'[{"id": "a", "body": "10 m", "body_hi": "10 मीटर", "isCorrect": false}, {"id": "b", "body": "20 m", "body_hi": "20 मीटर", "isCorrect": true}, {"id": "c", "body": "25 m", "body_hi": "25 मीटर", "isCorrect": false}, {"id": "d", "body": "80 m", "body_hi": "80 मीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'When the faster runner finishes, after 16 seconds, the slower one has run 16/20 of the race, that is 80 m. So the faster wins by 20 m. 25 m divides the 4-second gap by the faster time (4/16 of 100) instead of the slower; 80 m is the slower runner''s position, not the margin; 10 m has no basis.','जब तेज़ धावक 16 सेकंड बाद समाप्त करता है, धीमा धावक दौड़ का 16/20, यानी 80 मीटर दौड़ चुका है। अतः तेज़ धावक 20 मीटर से जीतता है। 25 मीटर 4 सेकंड के अंतर को धीमे के बजाय तेज़ समय से भाग देता है (100 का 4/16); 80 मीटर धीमे धावक की स्थिति है, अंतर नहीं; 10 मीटर का कोई आधार नहीं।','csat-l4-s04-qa-sdt-a-race-won-by-the-time-ratio','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','Which one of the following years was a leap year?','निम्नलिखित में से कौन-सा वर्ष अधिवर्ष (लीप वर्ष) था?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 41}'::jsonb,'[{"id": "a", "body": "1700", "body_hi": "1700", "isCorrect": false}, {"id": "b", "body": "1800", "body_hi": "1800", "isCorrect": false}, {"id": "c", "body": "1900", "body_hi": "1900", "isCorrect": false}, {"id": "d", "body": "2000", "body_hi": "2000", "isCorrect": true}]'::jsonb,2.5,0.83,'A year divisible by 4 is a leap year, except that a century year must be divisible by 400. All four are century years; only 2000 is divisible by 400, so only 2000 was a leap year. 1700, 1800 and 1900 are divisible by 4 and by 100 but not by 400 -- the trap is to stop at the test for 4.','4 से विभाज्य वर्ष अधिवर्ष होता है, इस अपवाद के साथ कि शताब्दी वर्ष को 400 से विभाज्य होना चाहिए। चारों शताब्दी वर्ष हैं; केवल 2000, 400 से विभाज्य है, इसलिए केवल 2000 अधिवर्ष था। 1700, 1800 और 1900, 4 और 100 से विभाज्य हैं पर 400 से नहीं -- जाल 4 की जाँच पर रुक जाना है।','csat-l4-s04-qa-nt-the-century-rule-for-leap-years','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','easy','Ten points are marked on a sheet so that no three of them lie on one straight line. How many different straight lines can be drawn, each through two of the points?','एक काग़ज़ पर दस बिंदु ऐसे अंकित हैं कि उनमें से कोई तीन एक सीधी रेखा पर नहीं हैं। कितनी अलग-अलग सीधी रेखाएँ खींची जा सकती हैं, हर एक दो बिंदुओं से होकर?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 42}'::jsonb,'[{"id": "a", "body": "10", "body_hi": "10", "isCorrect": false}, {"id": "b", "body": "20", "body_hi": "20", "isCorrect": false}, {"id": "c", "body": "36", "body_hi": "36", "isCorrect": false}, {"id": "d", "body": "45", "body_hi": "45", "isCorrect": true}]'::jsonb,2.5,0.83,'Each line is fixed by a pair of points, and no two pairs give the same line, since no three points are in a line. The number of pairs is 10C2 = 45. 36 counts the lines through 9 points; 10 and 20 have no basis.','हर रेखा बिंदुओं के एक जोड़े से तय होती है, और कोई दो जोड़े एक ही रेखा नहीं देते, क्योंकि कोई तीन बिंदु एक रेखा पर नहीं। जोड़ों की संख्या 10C2 = 45 है। 36, 9 बिंदुओं से होकर जाने वाली रेखाएँ गिनता है; 10 और 20 का कोई आधार नहीं।','csat-l4-s04-qa-pc-lines-through-ten-points','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','hard','Mohan: ''No good teacher ever loses patience with a student.'' Sunita: ''But Mrs Rao, whom everyone calls the best teacher in our school, lost her patience with a student yesterday.'' Mohan: ''Then she was never a good teacher after all.'' Which one of the following best describes the flaw in Mohan''s reasoning?','मोहन: ''कोई भी अच्छा शिक्षक कभी किसी विद्यार्थी पर धैर्य नहीं खोता।'' सुनीता: ''पर श्रीमती राव, जिन्हें सब हमारे विद्यालय की सबसे अच्छी शिक्षिका कहते हैं, कल एक विद्यार्थी पर धैर्य खो बैठीं।'' मोहन: ''तब वे कभी अच्छी शिक्षिका थीं ही नहीं।'' निम्नलिखित में से कौन-सा मोहन के तर्क की त्रुटि का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 43}'::jsonb,'[{"id": "a", "body": "He attacks Sunita''s motives for raising the example instead of answering her point.", "body_hi": "वह सुनीता की बात का उत्तर देने के बजाय उदाहरण देने के उसके इरादों पर हमला करता है।", "isCorrect": false}, {"id": "b", "body": "He protects his claim by refusing to let any example count against it.", "body_hi": "वह किसी भी उदाहरण को अपने दावे के विरुद्ध न गिनने देकर दावे को बचाता है।", "isCorrect": true}, {"id": "c", "body": "He draws a general rule about all teachers from what happened in one classroom.", "body_hi": "वह एक कक्षा में हुई घटना से सभी शिक्षकों के बारे में एक सामान्य नियम बना लेता है।", "isCorrect": false}, {"id": "d", "body": "He assumes that any teacher who stays patient must also be a good teacher.", "body_hi": "वह मान लेता है कि जो भी शिक्षक धैर्य रखता है वह अच्छा शिक्षक भी होगा।", "isCorrect": false}]'::jsonb,2.5,0.83,'A good teacher who loses patience is exactly the kind of case that could test Mohan''s claim. When Sunita offers one, Mohan decides that the teacher cannot have been good -- so no example could ever count against him, and his claim has quietly become true by definition rather than by evidence. He says nothing about Sunita''s motives; it is Sunita, not Mohan, who brings a single case, which is a fair way to test a rule that says ''no''; and he never claims that patience is enough to make a teacher good.','धैर्य खोने वाला अच्छा शिक्षक ठीक वैसा उदाहरण है जो मोहन के दावे को परख सकता है। जब सुनीता ऐसा उदाहरण देती है, मोहन तय कर लेता है कि वह शिक्षिका अच्छी रही ही नहीं होगी -- इसलिए कोई भी उदाहरण कभी उसके विरुद्ध नहीं गिना जा सकता, और उसका दावा चुपचाप प्रमाण से नहीं बल्कि परिभाषा से सत्य बन गया है। वह सुनीता के इरादों के बारे में कुछ नहीं कहता; एक उदाहरण मोहन नहीं, सुनीता देती है, जो ''कोई नहीं'' कहने वाले नियम को परखने का उचित तरीक़ा है; और वह कभी यह दावा नहीं करता कि धैर्य अकेले किसी शिक्षक को अच्छा बना देता है।','csat-l4-s04-lr-sc-a-claim-saved-by-redefining-its-terms','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Time & Work','mcq','medium','A worker finishes half of a job in 6 days, and then works twice as fast as before. How many days does the whole job take?','एक कामगार किसी काम का आधा भाग 6 दिनों में पूरा करता है, और फिर पहले से दोगुनी तेज़ी से काम करता है। पूरा काम कितने दिनों में होता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 44}'::jsonb,'[{"id": "a", "body": "8 days", "body_hi": "8 दिन", "isCorrect": false}, {"id": "b", "body": "9 days", "body_hi": "9 दिन", "isCorrect": true}, {"id": "c", "body": "10 days", "body_hi": "10 दिन", "isCorrect": false}, {"id": "d", "body": "12 days", "body_hi": "12 दिन", "isCorrect": false}]'::jsonb,2.5,0.83,'The second half is the same amount of work as the first; at twice the speed it takes half the time, 3 days. The whole job takes 6 + 3 = 9 days. 12 days ignores the speed-up; 8 and 10 days have no basis.','दूसरा आधा भाग पहले जितना ही काम है; दोगुनी तेज़ी से उसमें आधा समय, 3 दिन लगता है। पूरा काम 6 + 3 = 9 दिनों में होता है। 12 दिन तेज़ी को अनदेखा करता है; 8 और 10 दिन का कोई आधार नहीं।','csat-l4-s04-qa-tw-a-job-finished-at-double-speed','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
How should the basic rules of a society be chosen? In A Theory of Justice, published in 1971, the philosopher John Rawls proposed a thought experiment. Imagine choosing the rules from behind a ''veil of ignorance'': you do not know whether you will be born rich or poor, healthy or disabled, into the majority or a minority, or what talents you will have. Unable to tilt the rules in your own favour, you would have to choose rules you could accept whatever your place turned out to be. Rawls argued that people in this position would insist on equal basic liberties for all, and would allow inequalities of income and wealth only if they worked to the benefit of the least advantaged -- for instance, by rewarding effort and skill that make everyone better off. Critics reply that people might instead gamble on being among the lucky, and that the veil strips away the very loyalties and commitments that make us who we are. Yet even many critics grant the idea''s use as a test of fairness: a rule we would reject if we did not know who we were is hard to defend once we do.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
किसी समाज के मूल नियम कैसे चुने जाने चाहिए? 1971 में प्रकाशित ''ए थ्योरी ऑफ़ जस्टिस'' में दार्शनिक जॉन रॉल्स ने एक विचार-प्रयोग प्रस्तावित किया। कल्पना कीजिए कि आप नियम ''अज्ञान के पर्दे'' के पीछे से चुन रहे हैं: आप नहीं जानते कि आप धनी पैदा होंगे या निर्धन, स्वस्थ या दिव्यांग, बहुसंख्यक में या किसी अल्पसंख्यक में, या आपमें कौन-सी प्रतिभाएँ होंगी। नियमों को अपने पक्ष में झुकाने में असमर्थ होकर आपको ऐसे नियम चुनने होंगे जिन्हें आप स्वीकार कर सकें, चाहे आपका स्थान जो भी निकले। रॉल्स का तर्क था कि इस स्थिति में लोग सबके लिए समान मूल स्वतंत्रताओं पर ज़ोर देंगे, और आय और संपत्ति की असमानताओं की अनुमति केवल तभी देंगे जब वे सबसे वंचित लोगों के लाभ के लिए काम करें -- उदाहरण के लिए, उस प्रयास और कौशल को पुरस्कृत करके जो सबकी स्थिति बेहतर बनाते हैं। आलोचक उत्तर देते हैं कि लोग इसके बजाय भाग्यशाली लोगों में होने का दाँव लगा सकते हैं, और यह पर्दा उन्हीं निष्ठाओं और प्रतिबद्धताओं को हटा देता है जो हमें वह बनाती हैं जो हम हैं। फिर भी कई आलोचक भी इस विचार को निष्पक्षता की कसौटी के रूप में उपयोगी मानते हैं: जिस नियम को हम यह न जानते हुए ठुकरा देते कि हम कौन हैं, उसका बचाव यह जान लेने के बाद कठिन है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p06", "csat_order": 45}'::jsonb,'[{"id": "a", "body": "All inequalities of income and wealth are unjust and should be removed by the rules of a fair society.", "body_hi": "आय और संपत्ति की सभी असमानताएँ अन्यायपूर्ण हैं और किसी निष्पक्ष समाज के नियमों द्वारा हटाई जानी चाहिए।", "isCorrect": false}, {"id": "b", "body": "People choosing behind a veil of ignorance would gamble on being lucky, as Rawls''s critics have shown.", "body_hi": "अज्ञान के पर्दे के पीछे चुनने वाले लोग भाग्यशाली होने का दाँव लगाएँगे, जैसा रॉल्स के आलोचकों ने सिद्ध किया है।", "isCorrect": false}, {"id": "c", "body": "A just society is one whose rules give the largest rewards to those who have the greatest talents.", "body_hi": "न्यायपूर्ण समाज वह है जिसके नियम सबसे बड़ी प्रतिभा वालों को सबसे बड़े पुरस्कार देते हैं।", "isCorrect": false}, {"id": "d", "body": "Asking which rules we would accept without knowing our place in society is a useful test of fairness.", "body_hi": "यह पूछना कि समाज में अपना स्थान जाने बिना हम कौन-से नियम स्वीकार करेंगे, निष्पक्षता की एक उपयोगी कसौटी है।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage sets out Rawls''s thought experiment and his conclusions, notes two criticisms, and ends on what survives them: imagining that one does not know one''s own place is a useful test of whether a rule is fair. Rawls allows inequalities that benefit the least advantaged, so he does not call all inequality unjust; the critics'' gamble is offered as an objection, not as something shown; and rewarding the most talented for its own sake is not what the passage describes.','परिच्छेद रॉल्स का विचार-प्रयोग और उनके निष्कर्ष बताता है, दो आलोचनाओं का उल्लेख करता है, और उस पर समाप्त होता है जो उनके बाद भी बचता है: यह कल्पना करना कि हम अपना स्थान नहीं जानते, यह परखने की उपयोगी कसौटी है कि कोई नियम निष्पक्ष है या नहीं। रॉल्स उन असमानताओं की अनुमति देते हैं जो सबसे वंचितों को लाभ पहुँचाएँ, इसलिए वे हर असमानता को अन्यायपूर्ण नहीं कहते; आलोचकों का दाँव एक आपत्ति के रूप में रखा गया है, सिद्ध की गई बात के रूप में नहीं; और सबसे प्रतिभाशाली को केवल इसलिए पुरस्कृत करना वह नहीं जो परिच्छेद बताता है।','csat-l4-s04-rc-p06-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
How should the basic rules of a society be chosen? In A Theory of Justice, published in 1971, the philosopher John Rawls proposed a thought experiment. Imagine choosing the rules from behind a ''veil of ignorance'': you do not know whether you will be born rich or poor, healthy or disabled, into the majority or a minority, or what talents you will have. Unable to tilt the rules in your own favour, you would have to choose rules you could accept whatever your place turned out to be. Rawls argued that people in this position would insist on equal basic liberties for all, and would allow inequalities of income and wealth only if they worked to the benefit of the least advantaged -- for instance, by rewarding effort and skill that make everyone better off. Critics reply that people might instead gamble on being among the lucky, and that the veil strips away the very loyalties and commitments that make us who we are. Yet even many critics grant the idea''s use as a test of fairness: a rule we would reject if we did not know who we were is hard to defend once we do.

Which one of the following arrangements would Rawls''s principles, as the passage describes them, allow?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
किसी समाज के मूल नियम कैसे चुने जाने चाहिए? 1971 में प्रकाशित ''ए थ्योरी ऑफ़ जस्टिस'' में दार्शनिक जॉन रॉल्स ने एक विचार-प्रयोग प्रस्तावित किया। कल्पना कीजिए कि आप नियम ''अज्ञान के पर्दे'' के पीछे से चुन रहे हैं: आप नहीं जानते कि आप धनी पैदा होंगे या निर्धन, स्वस्थ या दिव्यांग, बहुसंख्यक में या किसी अल्पसंख्यक में, या आपमें कौन-सी प्रतिभाएँ होंगी। नियमों को अपने पक्ष में झुकाने में असमर्थ होकर आपको ऐसे नियम चुनने होंगे जिन्हें आप स्वीकार कर सकें, चाहे आपका स्थान जो भी निकले। रॉल्स का तर्क था कि इस स्थिति में लोग सबके लिए समान मूल स्वतंत्रताओं पर ज़ोर देंगे, और आय और संपत्ति की असमानताओं की अनुमति केवल तभी देंगे जब वे सबसे वंचित लोगों के लाभ के लिए काम करें -- उदाहरण के लिए, उस प्रयास और कौशल को पुरस्कृत करके जो सबकी स्थिति बेहतर बनाते हैं। आलोचक उत्तर देते हैं कि लोग इसके बजाय भाग्यशाली लोगों में होने का दाँव लगा सकते हैं, और यह पर्दा उन्हीं निष्ठाओं और प्रतिबद्धताओं को हटा देता है जो हमें वह बनाती हैं जो हम हैं। फिर भी कई आलोचक भी इस विचार को निष्पक्षता की कसौटी के रूप में उपयोगी मानते हैं: जिस नियम को हम यह न जानते हुए ठुकरा देते कि हम कौन हैं, उसका बचाव यह जान लेने के बाद कठिन है।

परिच्छेद में वर्णित रॉल्स के सिद्धांत निम्नलिखित में से किस व्यवस्था की अनुमति देंगे?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p06", "csat_order": 46}'::jsonb,'[{"id": "a", "body": "Paying one group more than others simply because that group makes up the majority of the population", "body_hi": "किसी समूह को दूसरों से अधिक वेतन केवल इसलिए देना कि वह समूह जनसंख्या का बहुमत है", "isCorrect": false}, {"id": "b", "body": "Higher pay for doctors, if it draws more people into medicine and so improves care for the poorest", "body_hi": "डॉक्टरों को ऊँचा वेतन, यदि वह अधिक लोगों को चिकित्सा में लाए और निर्धनतम की देखभाल सुधारे", "isCorrect": true}, {"id": "c", "body": "Letting only owners of property vote, if doing so would make the country richer on average", "body_hi": "केवल संपत्ति के स्वामियों को मतदान का अधिकार देना, यदि ऐसा करने से पूरा देश औसतन अधिक धनी हो जाए", "isCorrect": false}, {"id": "d", "body": "Paying a minority lower wages, if doing so raised the average income of everyone else in the country", "body_hi": "किसी अल्पसंख्यक को कम मज़दूरी देना, यदि ऐसा करने से देश के बाक़ी सब लोगों की औसत आय बढ़ जाए", "isCorrect": false}]'::jsonb,2.5,0.83,'Rawls allows an inequality of income only if it works to the benefit of the least advantaged, and never at the cost of equal basic liberties. Higher pay for doctors that draws more people into medicine and so improves the care the poorest receive meets that test. Higher pay for a group because it is the majority benefits the majority, not the least advantaged; a property qualification for voting takes away an equal basic liberty, whatever it does to average wealth; and lower wages for a minority to raise the majority''s average harms those who are already worse off.','रॉल्स आय की असमानता की अनुमति केवल तभी देते हैं जब वह सबसे वंचितों के लाभ के लिए काम करे, और समान मूल स्वतंत्रताओं की क़ीमत पर कभी नहीं। डॉक्टरों का ऊँचा वेतन जो अधिक लोगों को चिकित्सा की ओर खींचे और इस तरह सबसे निर्धनों को मिलने वाली देखभाल सुधारे, इस कसौटी पर खरा उतरता है। किसी समूह को बहुसंख्यक होने के कारण ऊँचा वेतन बहुसंख्यकों को लाभ देता है, सबसे वंचितों को नहीं; मतदान के लिए संपत्ति की शर्त एक समान मूल स्वतंत्रता छीन लेती है, औसत संपत्ति पर उसका प्रभाव जो भी हो; और बहुसंख्यकों का औसत बढ़ाने के लिए किसी अल्पसंख्यक की कम मज़दूरी उन्हें हानि पहुँचाती है जो पहले से ही बदतर स्थिति में हैं।','csat-l4-s04-rc-p06-an-inequality-rawls-would-allow','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
How should the basic rules of a society be chosen? In A Theory of Justice, published in 1971, the philosopher John Rawls proposed a thought experiment. Imagine choosing the rules from behind a ''veil of ignorance'': you do not know whether you will be born rich or poor, healthy or disabled, into the majority or a minority, or what talents you will have. Unable to tilt the rules in your own favour, you would have to choose rules you could accept whatever your place turned out to be. Rawls argued that people in this position would insist on equal basic liberties for all, and would allow inequalities of income and wealth only if they worked to the benefit of the least advantaged -- for instance, by rewarding effort and skill that make everyone better off. Critics reply that people might instead gamble on being among the lucky, and that the veil strips away the very loyalties and commitments that make us who we are. Yet even many critics grant the idea''s use as a test of fairness: a rule we would reject if we did not know who we were is hard to defend once we do.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
किसी समाज के मूल नियम कैसे चुने जाने चाहिए? 1971 में प्रकाशित ''ए थ्योरी ऑफ़ जस्टिस'' में दार्शनिक जॉन रॉल्स ने एक विचार-प्रयोग प्रस्तावित किया। कल्पना कीजिए कि आप नियम ''अज्ञान के पर्दे'' के पीछे से चुन रहे हैं: आप नहीं जानते कि आप धनी पैदा होंगे या निर्धन, स्वस्थ या दिव्यांग, बहुसंख्यक में या किसी अल्पसंख्यक में, या आपमें कौन-सी प्रतिभाएँ होंगी। नियमों को अपने पक्ष में झुकाने में असमर्थ होकर आपको ऐसे नियम चुनने होंगे जिन्हें आप स्वीकार कर सकें, चाहे आपका स्थान जो भी निकले। रॉल्स का तर्क था कि इस स्थिति में लोग सबके लिए समान मूल स्वतंत्रताओं पर ज़ोर देंगे, और आय और संपत्ति की असमानताओं की अनुमति केवल तभी देंगे जब वे सबसे वंचित लोगों के लाभ के लिए काम करें -- उदाहरण के लिए, उस प्रयास और कौशल को पुरस्कृत करके जो सबकी स्थिति बेहतर बनाते हैं। आलोचक उत्तर देते हैं कि लोग इसके बजाय भाग्यशाली लोगों में होने का दाँव लगा सकते हैं, और यह पर्दा उन्हीं निष्ठाओं और प्रतिबद्धताओं को हटा देता है जो हमें वह बनाती हैं जो हम हैं। फिर भी कई आलोचक भी इस विचार को निष्पक्षता की कसौटी के रूप में उपयोगी मानते हैं: जिस नियम को हम यह न जानते हुए ठुकरा देते कि हम कौन हैं, उसका बचाव यह जान लेने के बाद कठिन है।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Rawls held that people behind the veil would accept any inequality that raised the average income of the society.", "The critics mentioned in the passage object that the veil would make people too cautious to take any gamble."], "statements_hi": ["रॉल्स का मत था कि पर्दे के पीछे के लोग समाज की औसत आय बढ़ाने वाली किसी भी असमानता को स्वीकार कर लेंगे।", "परिच्छेद में उल्लिखित आलोचक आपत्ति करते हैं कि पर्दा लोगों को कोई भी दाँव लगाने के लिए बहुत सतर्क बना देगा।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "precision", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p06", "csat_order": 47}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2.5,0.83,'Neither is valid. 1 misstates Rawls: he would allow inequalities only if they benefit the least advantaged, not any inequality that raises the average. 2 reverses the critics'' point: they say people might gamble on being among the lucky -- that the veil would not make them as cautious as Rawls supposed -- not that it makes them too cautious to gamble.','कोई भी वैध नहीं। 1 रॉल्स को ग़लत ढंग से बताता है: वे असमानताओं की अनुमति केवल तभी देंगे जब वे सबसे वंचितों को लाभ पहुँचाएँ, औसत बढ़ाने वाली किसी भी असमानता की नहीं। 2 आलोचकों की बात को उलट देता है: वे कहते हैं कि लोग भाग्यशाली लोगों में होने का दाँव लगा सकते हैं -- कि पर्दा उन्हें उतना सतर्क नहीं बनाएगा जितना रॉल्स ने माना -- यह नहीं कि वह उन्हें दाँव लगाने के लिए बहुत सतर्क बना देता है।','csat-l4-s04-rc-p06-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','How many pairs of integers (x, y), positive, negative or zero, satisfy |x| + |y| = 3?','पूर्णांकों के कितने जोड़े (x, y), धनात्मक, ऋणात्मक या शून्य, |x| + |y| = 3 को संतुष्ट करते हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 48}'::jsonb,'[{"id": "a", "body": "4", "body_hi": "4", "isCorrect": false}, {"id": "b", "body": "8", "body_hi": "8", "isCorrect": false}, {"id": "c", "body": "12", "body_hi": "12", "isCorrect": true}, {"id": "d", "body": "16", "body_hi": "16", "isCorrect": false}]'::jsonb,2.5,0.83,'With |x| = 0 or 3 one coordinate is 0 and the other ±3: (0, ±3) and (±3, 0), 4 pairs. With |x| = 1 or 2 neither is 0, and each sign can be chosen: (±1, ±2) and (±2, ±1), 8 pairs. In all 12. 4 counts only the pairs with a zero; 8 only those without; 16 counts the zero cases twice.','|x| = 0 या 3 होने पर एक निर्देशांक 0 और दूसरा ±3 है: (0, ±3) और (±3, 0), 4 जोड़े। |x| = 1 या 2 होने पर कोई 0 नहीं, और हर चिह्न चुना जा सकता है: (±1, ±2) और (±2, ±1), 8 जोड़े। कुल 12। 4 केवल शून्य वाले जोड़े गिनता है; 8 केवल बिना शून्य वाले; 16 शून्य वाली स्थितियों को दो बार गिनता है।','csat-l4-s04-qa-nt-whole-number-points-on-a-diamond','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Data Sufficiency','mcq','easy','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: What is the value of x?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: x का मान क्या है?','{"statements": ["3x + 2 = 17.", "x² = 25, and x is positive."], "statements_hi": ["3x + 2 = 17।", "x² = 25, और x धनात्मक है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 49}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": true}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I gives 3x = 15, so x = 5 -- sufficient. Statement II allows x = 5 or x = -5, but x is positive, so x = 5 -- also sufficient. Either statement alone answers the question.','कथन I से 3x = 15, इसलिए x = 5 -- पर्याप्त। कथन II, x = 5 या x = -5 की अनुमति देता है, पर x धनात्मक है, इसलिए x = 5 -- यह भी पर्याप्त। कोई भी एक कथन अकेले प्रश्न का उत्तर देता है।','csat-l4-s04-qa-ds-a-value-found-from-a-line-or-a-square','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: Is the positive integer n a prime number?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: क्या धनात्मक पूर्णांक n एक अभाज्य संख्या है?','{"statements": ["n is odd.", "n is less than 20."], "statements_hi": ["n विषम है।", "n, 20 से कम है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 50}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": true}]'::jsonb,2.5,0.83,'Even together the statements allow odd numbers below 20 that are prime (3, 5, 7, 11, 13, 17, 19) and some that are not (1, 9, 15). So the question cannot be answered. The trap is to treat ''odd'' as if it meant ''prime''.','दोनों कथन साथ मिलकर भी 20 से कम ऐसी विषम संख्याओं की अनुमति देते हैं जो अभाज्य हैं (3, 5, 7, 11, 13, 17, 19) और कुछ जो नहीं हैं (1, 9, 15)। अतः प्रश्न का उत्तर नहीं दिया जा सकता। जाल ''विषम'' को ''अभाज्य'' के अर्थ में ले लेना है।','csat-l4-s04-qa-ds-an-odd-number-below-20','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: A die lies on a table. What number is on its bottom face?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: एक पासा मेज़ पर रखा है। उसके नीचे वाले फलक पर कौन-सी संख्या है?','{"statements": ["The top face shows 3.", "The numbers on opposite faces of the die add up to 7."], "statements_hi": ["ऊपर वाला फलक 3 दिखाता है।", "पासे के आमने-सामने के फलकों की संख्याओं का योग 7 है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 51}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone gives the top but not which number is opposite it, since dice can be numbered in different ways. Statement II alone gives the rule for opposite faces but not the top. Together, the bottom is opposite 3, so it shows 7 - 3 = 4. Both statements are needed.','कथन I अकेले ऊपर का फलक बताता है पर यह नहीं कि उसके सामने कौन-सी संख्या है, क्योंकि पासों पर संख्याएँ अलग-अलग ढंग से लिखी जा सकती हैं। कथन II अकेले आमने-सामने के फलकों का नियम बताता है पर ऊपर का फलक नहीं। दोनों मिलकर: नीचे वाला फलक 3 के सामने है, इसलिए वह 7 - 3 = 4 दिखाता है। दोनों कथन आवश्यक हैं।','csat-l4-s04-lr-ds-the-bottom-face-of-a-die','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','hard','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: On an island every person either always tells the truth or always lies. Is A a truth-teller?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: एक द्वीप पर हर व्यक्ति या तो हमेशा सच बोलता है या हमेशा झूठ। क्या A सच बोलने वाला है?','{"statements": ["A says, ''B is a liar.''", "B says, ''A and I are not of the same kind.''"], "statements_hi": ["A कहता है, ''B झूठा है।''", "B कहता है, ''A और मैं एक ही प्रकार के नहीं हैं।''"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 52}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement II alone settles it. If B tells the truth, A and B differ, so A is a liar. If B lies, the statement is false, so A and B are alike -- and A is a liar again. Either way A is a liar. Statement I alone does not: A truthful with B a liar, and A a liar with B truthful, both fit. So the question can be answered from one statement alone but not from the other.','कथन II अकेले इसे तय कर देता है। यदि B सच बोलता है, तो A और B अलग हैं, इसलिए A झूठा है। यदि B झूठ बोलता है, तो कथन असत्य है, इसलिए A और B एक जैसे हैं -- और A फिर झूठा है। दोनों ही तरह A झूठा है। कथन I अकेले नहीं: A सच्चा और B झूठा, तथा A झूठा और B सच्चा, दोनों ठीक बैठते हैं। अतः प्रश्न का उत्तर एक कथन से अकेले दिया जा सकता है पर दूसरे से नहीं।','csat-l4-s04-lr-ds-an-islander-who-gives-another-away','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: How many children are standing in a row?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: एक पंक्ति में कितने बच्चे खड़े हैं?','{"statements": ["Ravi is 7th from the left end of the row and 9th from the right end.", "Sita is 8th from the left end of the row and 8th from the right end."], "statements_hi": ["रवि पंक्ति के बाएँ छोर से 7वाँ और दाएँ छोर से 9वाँ है।", "सीता पंक्ति के बाएँ छोर से 8वीं और दाएँ छोर से 8वीं है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 53}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": true}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'A child who is m-th from one end and n-th from the other has m - 1 children on one side and n - 1 on the other, so the row has m + n - 1. Statement I gives 7 + 9 - 1 = 15; Statement II gives 8 + 8 - 1 = 15. Either statement alone answers the question.','जो बच्चा एक छोर से m-वाँ और दूसरे से n-वाँ है, उसके एक ओर m - 1 और दूसरी ओर n - 1 बच्चे हैं, इसलिए पंक्ति में m + n - 1 बच्चे हैं। कथन I से 7 + 9 - 1 = 15; कथन II से 8 + 8 - 1 = 15। कोई भी एक कथन अकेले प्रश्न का उत्तर देता है।','csat-l4-s04-lr-ds-a-row-counted-two-ways','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','easy','At a certain time of day a girl 1.5 m tall casts a shadow 2 m long, and a tree nearby casts a shadow 24 m long. How tall is the tree?','दिन के किसी समय 1.5 मीटर लंबी एक लड़की की छाया 2 मीटर लंबी है, और पास के एक पेड़ की छाया 24 मीटर लंबी है। पेड़ कितना ऊँचा है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 54}'::jsonb,'[{"id": "a", "body": "12 m", "body_hi": "12 मीटर", "isCorrect": false}, {"id": "b", "body": "16 m", "body_hi": "16 मीटर", "isCorrect": false}, {"id": "c", "body": "18 m", "body_hi": "18 मीटर", "isCorrect": true}, {"id": "d", "body": "32 m", "body_hi": "32 मीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'At the same moment the sun''s rays make the same angle everywhere nearby, so height and shadow are in the same ratio for both: 1.5 : 2 = h : 24, giving h = 24 × 1.5 ÷ 2 = 18 m. 32 m inverts the ratio (24 × 2 ÷ 1.5); 12 m halves the shadow; 16 m has no basis.','एक ही क्षण पर पास के हर स्थान पर सूर्य की किरणें एक ही कोण बनाती हैं, इसलिए दोनों के लिए ऊँचाई और छाया एक ही अनुपात में हैं: 1.5 : 2 = h : 24, जिससे h = 24 × 1.5 ÷ 2 = 18 मीटर। 32 मीटर अनुपात को उलट देता है (24 × 2 ÷ 1.5); 12 मीटर छाया को आधा करता है; 16 मीटर का कोई आधार नहीं।','csat-l4-s04-qa-gm-a-tree-measured-by-its-shadow','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Truth-Liar','mcq','hard','Ravi alternates between the truth and lies: whenever one of his statements is true, the next is false, and whenever one is false, the next is true. He makes three statements in a row: ''I am older than 30.'' ''I am 28 years old.'' ''My age is an even number.'' What can be concluded about his age?','रवि बारी-बारी से सच और झूठ बोलता है: जब भी उसका कोई कथन सत्य होता है, अगला असत्य होता है, और जब कोई असत्य होता है, अगला सत्य होता है। वह लगातार तीन कथन कहता है: ''मैं 30 से बड़ा हूँ।'' ''मेरी आयु 28 वर्ष है।'' ''मेरी आयु एक सम संख्या है।'' उसकी आयु के बारे में क्या निष्कर्ष निकाला जा सकता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 55}'::jsonb,'[{"id": "a", "body": "He is exactly 28 years old.", "body_hi": "उसकी आयु ठीक 28 वर्ष है।", "isCorrect": false}, {"id": "b", "body": "His age is an odd number of 30 or less.", "body_hi": "उसकी आयु 30 या उससे कम की एक विषम संख्या है।", "isCorrect": false}, {"id": "c", "body": "Nothing can be concluded about his age.", "body_hi": "उसकी आयु के बारे में कोई निष्कर्ष नहीं निकाला जा सकता।", "isCorrect": false}, {"id": "d", "body": "His age is an even number above 30.", "body_hi": "उसकी आयु 30 से ऊपर की एक सम संख्या है।", "isCorrect": true}]'::jsonb,2.5,0.83,'The first and third statements are both true or both false, and the second is the opposite. If the second were true, he would be 28 -- but then the third, ''my age is even'', would have to be false, and 28 is even. That is impossible. So the second is false and the first and third are true: he is older than 30 and his age is even (32, 34 and so on). He is not 28; an odd age of 30 or less would make the first and third false together with the second; and a conclusion can be drawn.','पहला और तीसरा कथन दोनों सत्य हैं या दोनों असत्य, और दूसरा उनका उलटा। यदि दूसरा सत्य होता, तो वह 28 का होता -- पर तब तीसरा, ''मेरी आयु सम है'', असत्य होना चाहिए, और 28 सम है। यह असंभव है। अतः दूसरा असत्य है और पहला व तीसरा सत्य: वह 30 से बड़ा है और उसकी आयु सम है (32, 34 आदि)। वह 28 का नहीं; 30 या कम की विषम आयु पहले और तीसरे को दूसरे के साथ ही असत्य कर देती; और निष्कर्ष निकाला जा सकता है।','csat-l4-s04-lr-tl-a-speaker-who-alternates-truth-and-lies','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','hard','Two swimmers start at the same moment from opposite ends of a 100 m pool, one at 3 m/s and the other at 2 m/s, and swim lengths without stopping, turning instantly at each end. After how long do they meet for the second time?','दो तैराक एक साथ 100 मीटर के तालाब के विपरीत छोरों से तैरना शुरू करते हैं, एक 3 मीटर/सेकंड से और दूसरा 2 मीटर/सेकंड से, और बिना रुके लंबाइयाँ तैरते हैं, हर छोर पर तुरंत मुड़ते हुए। कितने समय बाद वे दूसरी बार मिलते हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 56}'::jsonb,'[{"id": "a", "body": "20 s", "body_hi": "20 s", "isCorrect": false}, {"id": "b", "body": "40 s", "body_hi": "40 s", "isCorrect": false}, {"id": "c", "body": "60 s", "body_hi": "60 s", "isCorrect": true}, {"id": "d", "body": "80 s", "body_hi": "80 s", "isCorrect": false}]'::jsonb,2.5,0.83,'Together they cover 5 m every second. They first meet when their combined distance is one length, 100 m, after 20 s. Between one meeting and the next each reaches the far end and comes back, so together they cover two more lengths: the second meeting comes when their combined distance is three lengths, 300 m, after 60 s. 40 s assumes the second meeting needs only two lengths in all; 20 s is the first meeting; 80 s has no basis.','दोनों मिलकर हर सेकंड 5 मीटर तय करते हैं। वे पहली बार तब मिलते हैं जब उनकी कुल दूरी एक लंबाई, 100 मीटर, हो, 20 सेकंड बाद। एक भेंट और अगली के बीच हर एक दूर के छोर तक पहुँचकर लौटता है, इसलिए मिलकर वे दो और लंबाइयाँ तय करते हैं: दूसरी भेंट तब होती है जब कुल दूरी तीन लंबाइयाँ, 300 मीटर, हो, 60 सेकंड बाद। 40 सेकंड मान लेता है कि दूसरी भेंट के लिए कुल दो लंबाइयाँ ही चाहिए; 20 सेकंड पहली भेंट है; 80 सेकंड का कोई आधार नहीं।','csat-l4-s04-qa-sdt-swimmers-meeting-a-second-time','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','Which one of the following perfect squares is divisible by 7?','निम्नलिखित में से कौन-सा पूर्ण वर्ग 7 से विभाज्य है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 57}'::jsonb,'[{"id": "a", "body": "196", "body_hi": "196", "isCorrect": true}, {"id": "b", "body": "225", "body_hi": "225", "isCorrect": false}, {"id": "c", "body": "256", "body_hi": "256", "isCorrect": false}, {"id": "d", "body": "289", "body_hi": "289", "isCorrect": false}]'::jsonb,2.5,0.83,'A square is divisible by 7 only if its root is, since 7 is prime. The roots are 14, 15, 16 and 17, and only 14 is a multiple of 7: 196 = 14² = 7 × 28. 225, 256 and 289 have roots 15, 16 and 17, none divisible by 7.','चूँकि 7 अभाज्य है, कोई वर्ग 7 से तभी विभाज्य है जब उसका मूल हो। मूल 14, 15, 16 और 17 हैं, और केवल 14, 7 का गुणज है: 196 = 14² = 7 × 28। 225, 256 और 289 के मूल 15, 16 और 17 हैं, जिनमें से कोई 7 से विभाज्य नहीं।','csat-l4-s04-qa-nt-a-square-that-is-a-multiple-of-7','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Most of India''s rain falls in the summer monsoon, but the north-west also receives a little rain in winter, and it matters out of all proportion to its amount. It is brought by western disturbances -- low-pressure systems that form over the Mediterranean region and are carried eastward across Iran and Afghanistan by the westerly winds of the upper air. When they reach India they bring light rain to the plains of Punjab, Haryana and western Uttar Pradesh, and snow to the western Himalaya. The rain falls while the wheat sown in November is growing, and can save farmers an irrigation or two; the snow feeds the rivers that flow through the following spring and summer. Yet the same systems can do harm. A disturbance that arrives late, in March or April, when the wheat is ripening, may bring hail and strong winds that flatten the crop. Whether a western disturbance proves a blessing or a loss depends less on its strength than on its timing.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
भारत की अधिकांश वर्षा ग्रीष्मकालीन मानसून में होती है, पर उत्तर-पश्चिम में सर्दियों में भी थोड़ी वर्षा होती है, और उसका महत्त्व उसकी मात्रा से कहीं अधिक है। यह पश्चिमी विक्षोभों से आती है -- निम्न दाब की प्रणालियाँ जो भूमध्यसागरीय क्षेत्र के ऊपर बनती हैं और ऊपरी वायुमंडल की पछुआ हवाओं द्वारा ईरान और अफ़ग़ानिस्तान के पार पूर्व की ओर ले जाई जाती हैं। भारत पहुँचने पर वे पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश के मैदानों में हल्की वर्षा, और पश्चिमी हिमालय में हिमपात लाते हैं। वर्षा तब होती है जब नवंबर में बोया गया गेहूँ बढ़ रहा होता है, और किसानों की एक-दो सिंचाई बचा सकती है; हिम उन नदियों को पोषित करता है जो अगले वसंत और ग्रीष्म में बहती हैं। फिर भी यही प्रणालियाँ हानि भी कर सकती हैं। देर से, मार्च या अप्रैल में, जब गेहूँ पक रहा होता है, आने वाला विक्षोभ ओले और तेज़ हवाएँ ला सकता है जो फ़सल को बिछा देती हैं। कोई पश्चिमी विक्षोभ वरदान सिद्ध होगा या हानि, यह उसकी तीव्रता से कम और उसके समय से अधिक तय होता है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p07", "csat_order": 58}'::jsonb,'[{"id": "a", "body": "Winter rain from western disturbances helps the rabi crop, but its effect depends on when it comes.", "body_hi": "पश्चिमी विक्षोभों की शीतकालीन वर्षा रबी फ़सल की सहायता करती है, पर उसका प्रभाव आने के समय पर निर्भर है।", "isCorrect": true}, {"id": "b", "body": "The winter rain of the north-west matters more to Indian farming than the rain of the summer monsoon.", "body_hi": "उत्तर-पश्चिम की शीतकालीन वर्षा भारतीय खेती के लिए ग्रीष्मकालीन मानसून की वर्षा से अधिक मायने रखती है।", "isCorrect": false}, {"id": "c", "body": "Western disturbances always harm the wheat crop, since they bring hail and strong winds to the plains.", "body_hi": "पश्चिमी विक्षोभ हमेशा गेहूँ की फ़सल को हानि पहुँचाते हैं, क्योंकि वे मैदानों में ओले और तेज़ हवाएँ लाते हैं।", "isCorrect": false}, {"id": "d", "body": "Western disturbances form over the Indian Ocean and move north-west across the Indian subcontinent.", "body_hi": "पश्चिमी विक्षोभ हिंद महासागर के ऊपर बनते हैं और भारतीय उपमहाद्वीप के पार उत्तर-पश्चिम की ओर बढ़ते हैं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage explains that the small winter rain of western disturbances helps the wheat and feeds the rivers, then turns to the harm late disturbances can do, ending on timing as the deciding factor. It says the winter rain matters ''out of all proportion to its amount'', not that it matters more than the monsoon; it says late disturbances ''may'' harm the crop, not that all of them do; and it places their origin over the Mediterranean, not the Indian Ocean.','परिच्छेद बताता है कि पश्चिमी विक्षोभों की थोड़ी-सी शीतकालीन वर्षा गेहूँ की सहायता करती है और नदियों को पोषित करती है, फिर देर से आने वाले विक्षोभों से होने वाली हानि की ओर मुड़ता है, और समय को निर्णायक कारक बताकर समाप्त होता है। वह कहता है कि शीतकालीन वर्षा का महत्त्व ''उसकी मात्रा से कहीं अधिक'' है, यह नहीं कि वह मानसून से अधिक मायने रखती है; वह कहता है कि देर से आने वाले विक्षोभ फ़सल को हानि पहुँचा ''सकते'' हैं, यह नहीं कि सभी पहुँचाते हैं; और वह उनका उद्गम भूमध्यसागर के ऊपर बताता है, हिंद महासागर नहीं।','csat-l4-s04-rc-p07-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Most of India''s rain falls in the summer monsoon, but the north-west also receives a little rain in winter, and it matters out of all proportion to its amount. It is brought by western disturbances -- low-pressure systems that form over the Mediterranean region and are carried eastward across Iran and Afghanistan by the westerly winds of the upper air. When they reach India they bring light rain to the plains of Punjab, Haryana and western Uttar Pradesh, and snow to the western Himalaya. The rain falls while the wheat sown in November is growing, and can save farmers an irrigation or two; the snow feeds the rivers that flow through the following spring and summer. Yet the same systems can do harm. A disturbance that arrives late, in March or April, when the wheat is ripening, may bring hail and strong winds that flatten the crop. Whether a western disturbance proves a blessing or a loss depends less on its strength than on its timing.

According to the passage, how does the winter snow that western disturbances bring to the western Himalaya help?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
भारत की अधिकांश वर्षा ग्रीष्मकालीन मानसून में होती है, पर उत्तर-पश्चिम में सर्दियों में भी थोड़ी वर्षा होती है, और उसका महत्त्व उसकी मात्रा से कहीं अधिक है। यह पश्चिमी विक्षोभों से आती है -- निम्न दाब की प्रणालियाँ जो भूमध्यसागरीय क्षेत्र के ऊपर बनती हैं और ऊपरी वायुमंडल की पछुआ हवाओं द्वारा ईरान और अफ़ग़ानिस्तान के पार पूर्व की ओर ले जाई जाती हैं। भारत पहुँचने पर वे पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश के मैदानों में हल्की वर्षा, और पश्चिमी हिमालय में हिमपात लाते हैं। वर्षा तब होती है जब नवंबर में बोया गया गेहूँ बढ़ रहा होता है, और किसानों की एक-दो सिंचाई बचा सकती है; हिम उन नदियों को पोषित करता है जो अगले वसंत और ग्रीष्म में बहती हैं। फिर भी यही प्रणालियाँ हानि भी कर सकती हैं। देर से, मार्च या अप्रैल में, जब गेहूँ पक रहा होता है, आने वाला विक्षोभ ओले और तेज़ हवाएँ ला सकता है जो फ़सल को बिछा देती हैं। कोई पश्चिमी विक्षोभ वरदान सिद्ध होगा या हानि, यह उसकी तीव्रता से कम और उसके समय से अधिक तय होता है।

परिच्छेद के अनुसार, पश्चिमी विक्षोभों द्वारा पश्चिमी हिमालय में लाया गया शीतकालीन हिम कैसे सहायता करता है?','{"craft": "precision", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p07", "csat_order": 59}'::jsonb,'[{"id": "a", "body": "It saves farmers on the plains an irrigation or two for the wheat sown in November.", "body_hi": "यह मैदानों के किसानों की नवंबर में बोए गए गेहूँ के लिए एक-दो सिंचाई बचाता है।", "isCorrect": false}, {"id": "b", "body": "It stops hail from falling on the plains when the wheat is ripening in March and April.", "body_hi": "यह मार्च और अप्रैल में गेहूँ पकने के समय मैदानों में ओले गिरने से रोकता है।", "isCorrect": false}, {"id": "c", "body": "It feeds the rivers that flow through the following spring and summer.", "body_hi": "यह उन नदियों को पोषित करता है जो अगले वसंत और ग्रीष्म में बहती हैं।", "isCorrect": true}, {"id": "d", "body": "It cools the westerly winds of the upper air that carry the disturbances eastward.", "body_hi": "यह ऊपरी वायुमंडल की उन पछुआ हवाओं को ठंडा करता है जो विक्षोभों को पूर्व की ओर ले जाती हैं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says that the snow ''feeds the rivers that flow through the following spring and summer''. Saving an irrigation is what the rain on the plains does for the wheat; the passage does not say that snow prevents hail or cools the westerly winds.','परिच्छेद कहता है कि हिम ''उन नदियों को पोषित करता है जो अगले वसंत और ग्रीष्म में बहती हैं''। सिंचाई बचाना वह काम है जो मैदानों की वर्षा गेहूँ के लिए करती है; परिच्छेद यह नहीं कहता कि हिम ओलों को रोकता है या पछुआ हवाओं को ठंडा करता है।','csat-l4-s04-rc-p07-what-the-winter-snow-does','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Most of India''s rain falls in the summer monsoon, but the north-west also receives a little rain in winter, and it matters out of all proportion to its amount. It is brought by western disturbances -- low-pressure systems that form over the Mediterranean region and are carried eastward across Iran and Afghanistan by the westerly winds of the upper air. When they reach India they bring light rain to the plains of Punjab, Haryana and western Uttar Pradesh, and snow to the western Himalaya. The rain falls while the wheat sown in November is growing, and can save farmers an irrigation or two; the snow feeds the rivers that flow through the following spring and summer. Yet the same systems can do harm. A disturbance that arrives late, in March or April, when the wheat is ripening, may bring hail and strong winds that flatten the crop. Whether a western disturbance proves a blessing or a loss depends less on its strength than on its timing.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
भारत की अधिकांश वर्षा ग्रीष्मकालीन मानसून में होती है, पर उत्तर-पश्चिम में सर्दियों में भी थोड़ी वर्षा होती है, और उसका महत्त्व उसकी मात्रा से कहीं अधिक है। यह पश्चिमी विक्षोभों से आती है -- निम्न दाब की प्रणालियाँ जो भूमध्यसागरीय क्षेत्र के ऊपर बनती हैं और ऊपरी वायुमंडल की पछुआ हवाओं द्वारा ईरान और अफ़ग़ानिस्तान के पार पूर्व की ओर ले जाई जाती हैं। भारत पहुँचने पर वे पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश के मैदानों में हल्की वर्षा, और पश्चिमी हिमालय में हिमपात लाते हैं। वर्षा तब होती है जब नवंबर में बोया गया गेहूँ बढ़ रहा होता है, और किसानों की एक-दो सिंचाई बचा सकती है; हिम उन नदियों को पोषित करता है जो अगले वसंत और ग्रीष्म में बहती हैं। फिर भी यही प्रणालियाँ हानि भी कर सकती हैं। देर से, मार्च या अप्रैल में, जब गेहूँ पक रहा होता है, आने वाला विक्षोभ ओले और तेज़ हवाएँ ला सकता है जो फ़सल को बिछा देती हैं। कोई पश्चिमी विक्षोभ वरदान सिद्ध होगा या हानि, यह उसकी तीव्रता से कम और उसके समय से अधिक तय होता है।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Two western disturbances of the same strength could have opposite effects on the wheat harvest.", "A western disturbance in December or January is more likely to help the wheat crop than one in April."], "statements_hi": ["समान तीव्रता के दो पश्चिमी विक्षोभों का गेहूँ की फ़सल पर विपरीत प्रभाव हो सकता है।", "दिसंबर या जनवरी के पश्चिमी विक्षोभ के गेहूँ की फ़सल के लिए अप्रैल वाले विक्षोभ से अधिक सहायक होने की संभावना है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p07", "csat_order": 60}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are valid. The passage ends by saying that a disturbance''s effect depends less on its strength than on its timing, so two of equal strength, one arriving while the wheat grows and one while it ripens, could help in one case and harm in the other (1). And since a disturbance in the growing season brings useful rain while one in March or April may bring hail, one in December or January is the more likely to help (2).','दोनों वैध हैं। परिच्छेद यह कहकर समाप्त होता है कि किसी विक्षोभ का प्रभाव उसकी तीव्रता से कम और उसके समय पर अधिक निर्भर है, इसलिए समान तीव्रता के दो विक्षोभ, एक गेहूँ के बढ़ते समय और एक पकते समय आने वाला, एक स्थिति में सहायता और दूसरी में हानि कर सकते हैं (1)। और चूँकि बढ़वार के मौसम का विक्षोभ उपयोगी वर्षा लाता है जबकि मार्च या अप्रैल का विक्षोभ ओले ला सकता है, दिसंबर या जनवरी के विक्षोभ के सहायक होने की संभावना अधिक है (2)।','csat-l4-s04-rc-p07-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','easy','What is the sum 1 + 2 + 4 + 8 + ... + 512, in which each term is double the one before?','योग 1 + 2 + 4 + 8 + ... + 512 क्या है, जिसमें हर पद पिछले पद का दोगुना है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 61}'::jsonb,'[{"id": "a", "body": "256", "body_hi": "256", "isCorrect": false}, {"id": "b", "body": "511", "body_hi": "511", "isCorrect": false}, {"id": "c", "body": "512", "body_hi": "512", "isCorrect": false}, {"id": "d", "body": "1,023", "body_hi": "1,023", "isCorrect": true}]'::jsonb,2.5,0.83,'Each partial sum is one less than the next power of 2 (1 = 2 - 1, 1 + 2 = 4 - 1, 1 + 2 + 4 = 8 - 1, ...), so the sum up to 512 is 1,024 - 1 = 1,023. 512 is the last term alone; 511 is the sum up to 256; 256 has no basis.','हर आंशिक योग 2 की अगली घात से एक कम है (1 = 2 - 1, 1 + 2 = 4 - 1, 1 + 2 + 4 = 8 - 1, ...), इसलिए 512 तक का योग 1,024 - 1 = 1,023 है। 512 केवल अंतिम पद है; 511, 256 तक का योग है; 256 का कोई आधार नहीं।','csat-l4-s04-qa-ss-a-doubling-sum','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Coding-Decoding','mcq','medium','In a code, each letter from A to M is replaced by the letter two places after it in the alphabet, and each letter from N to Z by the letter two places before it. How is SMILE written in this code?','एक कूट में A से M तक का हर अक्षर वर्णमाला में अपने से दो स्थान आगे वाले अक्षर से, और N से Z तक का हर अक्षर अपने से दो स्थान पीछे वाले अक्षर से बदला जाता है। इस कूट में SMILE कैसे लिखा जाता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 62}'::jsonb,'[{"id": "a", "body": "UOKNG", "body_hi": "UOKNG", "isCorrect": false}, {"id": "b", "body": "QKGJC", "body_hi": "QKGJC", "isCorrect": false}, {"id": "c", "body": "QOKNG", "body_hi": "QOKNG", "isCorrect": true}, {"id": "d", "body": "UKGJC", "body_hi": "UKGJC", "isCorrect": false}]'::jsonb,2.5,0.83,'S is in the second half, so it moves back two places to Q. M, I, L and E are all in the first half (M is its last letter), so each moves forward two: M to O, I to K, L to N, E to G. SMILE becomes QOKNG. UOKNG moves every letter forward; QKGJC moves every letter back; UKGJC applies the rule the wrong way round.','S दूसरे आधे में है, इसलिए वह दो स्थान पीछे Q पर जाता है। M, I, L और E सभी पहले आधे में हैं (M उसका अंतिम अक्षर है), इसलिए हर एक दो स्थान आगे जाता है: M से O, I से K, L से N, E से G। SMILE बन जाता है QOKNG। UOKNG हर अक्षर को आगे ले जाता है; QKGJC हर अक्षर को पीछे; UKGJC नियम को उलटा लागू करता है।','csat-l4-s04-lr-cd-the-two-halves-of-the-alphabet-shifted-opposite-ways','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','medium','A fair die is rolled twice. What is the probability of getting exactly one six?','एक निष्पक्ष पासे को दो बार फेंका जाता है। ठीक एक छह आने की प्रायिकता क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 63}'::jsonb,'[{"id": "a", "body": "1/6", "body_hi": "1/6", "isCorrect": false}, {"id": "b", "body": "5/18", "body_hi": "5/18", "isCorrect": true}, {"id": "c", "body": "11/36", "body_hi": "11/36", "isCorrect": false}, {"id": "d", "body": "1/3", "body_hi": "1/3", "isCorrect": false}]'::jsonb,2.5,0.83,'The six can come on the first roll and not the second (1/6 × 5/6 = 5/36) or on the second and not the first (another 5/36): 10/36 = 5/18. 11/36 is the chance of at least one six, which includes two sixes; 1/3 adds 1/6 twice; 1/6 is the chance on one roll.','छह पहली बार में आए और दूसरी में नहीं (1/6 × 5/6 = 5/36) या दूसरी में आए और पहली में नहीं (और 5/36): 10/36 = 5/18। 11/36 कम से कम एक छह की संभावना है, जिसमें दो छह भी शामिल हैं; 1/3, 1/6 को दो बार जोड़ता है; 1/6 एक बार फेंकने की संभावना है।','csat-l4-s04-qa-pc-exactly-one-six-in-two-rolls','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','hard','Five meetings are held in one morning: 9:00-10:00, 9:30-11:00, 10:00-11:30, 10:45-12:00 and 11:30-12:30. A room can hold only one meeting at a time, and a meeting that ends at a given time leaves its room free for one starting then. What is the least number of rooms needed?','एक सुबह पाँच बैठकें होती हैं: 9:00-10:00, 9:30-11:00, 10:00-11:30, 10:45-12:00 और 11:30-12:30। एक कमरे में एक समय में एक ही बैठक हो सकती है, और किसी समय समाप्त होने वाली बैठक उसी समय शुरू होने वाली बैठक के लिए अपना कमरा ख़ाली कर देती है। कम से कम कितने कमरे चाहिए?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 64}'::jsonb,'[{"id": "a", "body": "2", "body_hi": "2", "isCorrect": false}, {"id": "b", "body": "3", "body_hi": "3", "isCorrect": true}, {"id": "c", "body": "4", "body_hi": "4", "isCorrect": false}, {"id": "d", "body": "5", "body_hi": "5", "isCorrect": false}]'::jsonb,2.5,0.83,'The rooms needed equal the largest number of meetings in progress at one moment. From 10:45 to 11:00 three meetings run together (9:30-11:00, 10:00-11:30 and 10:45-12:00), and at no time are there four. So three rooms are enough -- for example, room 1 for 9:00-10:00, 10:00-11:30 and 11:30-12:30; room 2 for 9:30-11:00; room 3 for 10:45-12:00. 2 rooms cannot hold the three overlapping meetings; 4 and 5 are more than needed.','आवश्यक कमरों की संख्या किसी एक क्षण पर चल रही बैठकों की सबसे बड़ी संख्या के बराबर है। 10:45 से 11:00 तक तीन बैठकें साथ चलती हैं (9:30-11:00, 10:00-11:30 और 10:45-12:00), और किसी समय चार नहीं होतीं। अतः तीन कमरे पर्याप्त हैं -- उदाहरण के लिए, कमरा 1 में 9:00-10:00, 10:00-11:30 और 11:30-12:30; कमरा 2 में 9:30-11:00; कमरा 3 में 10:45-12:00। 2 कमरे तीन साथ-साथ चलने वाली बैठकों को नहीं सँभाल सकते; 4 और 5 आवश्यकता से अधिक हैं।','csat-l4-s04-qa-ph-meetings-that-need-rooms','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Best Summary','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
When railways were first built in India in the nineteenth century, the main lines were laid to a broad gauge -- the distance between the rails -- of 1,676 mm. From the 1870s, to save money, many new lines were built to a metre gauge, and some hill and branch lines to narrower gauges still. Each choice made sense at the time, but together they left a network in which goods moving between lines of different gauges had to be unloaded and reloaded by hand, a slow and costly business. Once thousands of kilometres of track, and the engines and wagons to run on it, had been built to a gauge, changing it was hugely expensive, so the mixed network lasted for more than a century. Only in 1992 did Indian Railways begin Project Unigauge, a long programme of converting metre and narrow gauge lines to broad gauge. Economists call such cases path dependence: a choice that suits its moment can, by attracting investments built around it, lock in a pattern that later generations would never have chosen.

Which one of the following best summarises the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
जब उन्नीसवीं शताब्दी में भारत में पहली बार रेलें बनीं, तो मुख्य लाइनें 1,676 मिमी की बड़ी लाइन (ब्रॉड गेज) -- पटरियों के बीच की दूरी -- पर बिछाई गईं। 1870 के दशक से पैसा बचाने के लिए कई नई लाइनें मीटर गेज पर बनाई गईं, और कुछ पहाड़ी और शाखा लाइनें उससे भी संकरी गेजों पर। हर चुनाव अपने समय में उचित था, पर मिलकर उन्होंने ऐसा जाल छोड़ा जिसमें अलग-अलग गेज की लाइनों के बीच जाने वाले माल को हाथ से उतारना और फिर लादना पड़ता था, जो धीमा और महँगा काम था। एक बार किसी गेज पर हज़ारों किलोमीटर पटरी, और उस पर चलने वाले इंजन और डिब्बे बन जाने पर उसे बदलना बेहद महँगा था, इसलिए मिश्रित जाल एक शताब्दी से भी अधिक समय तक बना रहा। केवल 1992 में भारतीय रेल ने प्रोजेक्ट यूनीगेज शुरू किया, मीटर और नैरो गेज लाइनों को बड़ी लाइन में बदलने का एक लंबा कार्यक्रम। अर्थशास्त्री ऐसे मामलों को पथ-निर्भरता कहते हैं: अपने समय के अनुकूल कोई चुनाव, अपने इर्द-गिर्द बने निवेशों को आकर्षित करके, एक ऐसा ढर्रा जमा सकता है जिसे बाद की पीढ़ियाँ कभी न चुनतीं।

निम्नलिखित में से कौन-सा परिच्छेद का सबसे अच्छा सारांश है?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p08", "csat_order": 65}'::jsonb,'[{"id": "a", "body": "India''s early railway builders chose the metre gauge without giving any thought to what it would cost.", "body_hi": "भारत के आरंभिक रेल निर्माताओं ने मीटर गेज को उसकी लागत का कोई विचार किए बिना चुना।", "isCorrect": false}, {"id": "b", "body": "A single gauge for a whole railway network is always cheaper than a mix of gauges, right from the start.", "body_hi": "पूरे रेल जाल के लिए एक ही गेज शुरू से ही गेजों के मिश्रण से हमेशा सस्ती होती है।", "isCorrect": false}, {"id": "c", "body": "Project Unigauge has now converted every railway line in India from metre or narrow gauge to broad gauge.", "body_hi": "प्रोजेक्ट यूनीगेज ने अब भारत की हर रेल लाइन को मीटर या नैरो गेज से बड़ी लाइन में बदल दिया है।", "isCorrect": false}, {"id": "d", "body": "Choices made for good reasons in their time can become costly to undo once investment grows around them.", "body_hi": "अपने समय में उचित चुनाव, उनके इर्द-गिर्द निवेश बढ़ने के बाद, बदलने में महँगे हो सकते हैं।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage tells how sensible choices of gauge, each made to suit its time, became costly to undo once track and rolling stock had been built around them, and names this path dependence. It says the metre gauge was chosen to save money, the opposite of choosing without thought for cost; it never claims that a single gauge was cheaper from the very start; and it calls Project Unigauge a long programme begun in 1992, without saying that every line has been converted.','परिच्छेद बताता है कि गेज के समझदारी भरे चुनाव, जो हर एक अपने समय के अनुकूल किया गया था, पटरियों और डिब्बों के उनके इर्द-गिर्द बन जाने के बाद बदलने में महँगे हो गए, और इसे पथ-निर्भरता कहता है। वह कहता है कि मीटर गेज पैसा बचाने के लिए चुनी गई, जो लागत का विचार किए बिना चुनने का उलटा है; वह कभी दावा नहीं करता कि एक ही गेज शुरू से सस्ती थी; और वह प्रोजेक्ट यूनीगेज को 1992 में शुरू हुआ एक लंबा कार्यक्रम कहता है, यह कहे बिना कि हर लाइन बदल दी गई है।','csat-l4-s04-rc-p08-summary','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
When railways were first built in India in the nineteenth century, the main lines were laid to a broad gauge -- the distance between the rails -- of 1,676 mm. From the 1870s, to save money, many new lines were built to a metre gauge, and some hill and branch lines to narrower gauges still. Each choice made sense at the time, but together they left a network in which goods moving between lines of different gauges had to be unloaded and reloaded by hand, a slow and costly business. Once thousands of kilometres of track, and the engines and wagons to run on it, had been built to a gauge, changing it was hugely expensive, so the mixed network lasted for more than a century. Only in 1992 did Indian Railways begin Project Unigauge, a long programme of converting metre and narrow gauge lines to broad gauge. Economists call such cases path dependence: a choice that suits its moment can, by attracting investments built around it, lock in a pattern that later generations would never have chosen.

Which one of the following is also an example of path dependence as the passage describes it?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
जब उन्नीसवीं शताब्दी में भारत में पहली बार रेलें बनीं, तो मुख्य लाइनें 1,676 मिमी की बड़ी लाइन (ब्रॉड गेज) -- पटरियों के बीच की दूरी -- पर बिछाई गईं। 1870 के दशक से पैसा बचाने के लिए कई नई लाइनें मीटर गेज पर बनाई गईं, और कुछ पहाड़ी और शाखा लाइनें उससे भी संकरी गेजों पर। हर चुनाव अपने समय में उचित था, पर मिलकर उन्होंने ऐसा जाल छोड़ा जिसमें अलग-अलग गेज की लाइनों के बीच जाने वाले माल को हाथ से उतारना और फिर लादना पड़ता था, जो धीमा और महँगा काम था। एक बार किसी गेज पर हज़ारों किलोमीटर पटरी, और उस पर चलने वाले इंजन और डिब्बे बन जाने पर उसे बदलना बेहद महँगा था, इसलिए मिश्रित जाल एक शताब्दी से भी अधिक समय तक बना रहा। केवल 1992 में भारतीय रेल ने प्रोजेक्ट यूनीगेज शुरू किया, मीटर और नैरो गेज लाइनों को बड़ी लाइन में बदलने का एक लंबा कार्यक्रम। अर्थशास्त्री ऐसे मामलों को पथ-निर्भरता कहते हैं: अपने समय के अनुकूल कोई चुनाव, अपने इर्द-गिर्द बने निवेशों को आकर्षित करके, एक ऐसा ढर्रा जमा सकता है जिसे बाद की पीढ़ियाँ कभी न चुनतीं।

निम्नलिखित में से कौन-सा भी परिच्छेद में वर्णित पथ-निर्भरता का एक उदाहरण है?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p08", "csat_order": 66}'::jsonb,'[{"id": "a", "body": "A farmer who switches to a new variety of seed as soon as trials show that it gives higher yields", "body_hi": "ऐसा किसान जो परीक्षणों में किसी नए बीज के अधिक उपज देने का प्रमाण मिलते ही उसे तुरंत अपना लेता है", "isCorrect": false}, {"id": "b", "body": "A railway that rewrites its timetable every year to keep pace with changes in demand", "body_hi": "ऐसी रेल जो माँग में बदलावों के साथ चलने के लिए हर वर्ष अपनी समय-सारणी फिर से लिखती है", "isCorrect": false}, {"id": "c", "body": "A city whose lanes, laid out for carts, are too costly to widen now that buildings line them", "body_hi": "ऐसा शहर जिसकी गाड़ियों के लिए बनी गलियाँ किनारे इमारतें बन जाने से चौड़ी करने में बहुत महँगी हैं", "isCorrect": true}, {"id": "d", "body": "A shopkeeper who decides what to stock by checking which goods sold best in the month before", "body_hi": "ऐसा दुकानदार जो यह देखकर तय करता है कि क्या रखे कि पिछले महीने कौन-सा सामान सबसे अधिक बिका", "isCorrect": false}]'::jsonb,2.5,0.83,'Path dependence, in the passage, is an early choice that suited its moment and then became locked in because investments were built around it. A city''s narrow lanes, laid out for carts and now lined with buildings that make widening hugely expensive, fit that pattern. Switching to a better seed as soon as it is proven shows no lock-in; a timetable changed every year is the opposite of being locked in; and buying stock by last month''s sales is ordinary adjustment to recent information.','परिच्छेद में पथ-निर्भरता एक आरंभिक चुनाव है जो अपने समय के अनुकूल था और फिर इसलिए जम गया कि उसके इर्द-गिर्द निवेश हो गए। किसी शहर की संकरी गलियाँ, जो गाड़ियों के लिए बनी थीं और जिनके किनारे अब ऐसी इमारतें हैं कि उन्हें चौड़ा करना बेहद महँगा है, इस ढर्रे पर ठीक बैठती हैं। सिद्ध होते ही बेहतर बीज अपना लेना कोई जमाव नहीं दिखाता; हर वर्ष बदली जाने वाली समय-सारणी जमाव का उलटा है; और पिछले महीने की बिक्री के आधार पर माल ख़रीदना हाल की जानकारी के अनुसार सामान्य समायोजन है।','csat-l4-s04-rc-p08-another-example-of-path-dependence','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
When railways were first built in India in the nineteenth century, the main lines were laid to a broad gauge -- the distance between the rails -- of 1,676 mm. From the 1870s, to save money, many new lines were built to a metre gauge, and some hill and branch lines to narrower gauges still. Each choice made sense at the time, but together they left a network in which goods moving between lines of different gauges had to be unloaded and reloaded by hand, a slow and costly business. Once thousands of kilometres of track, and the engines and wagons to run on it, had been built to a gauge, changing it was hugely expensive, so the mixed network lasted for more than a century. Only in 1992 did Indian Railways begin Project Unigauge, a long programme of converting metre and narrow gauge lines to broad gauge. Economists call such cases path dependence: a choice that suits its moment can, by attracting investments built around it, lock in a pattern that later generations would never have chosen.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
जब उन्नीसवीं शताब्दी में भारत में पहली बार रेलें बनीं, तो मुख्य लाइनें 1,676 मिमी की बड़ी लाइन (ब्रॉड गेज) -- पटरियों के बीच की दूरी -- पर बिछाई गईं। 1870 के दशक से पैसा बचाने के लिए कई नई लाइनें मीटर गेज पर बनाई गईं, और कुछ पहाड़ी और शाखा लाइनें उससे भी संकरी गेजों पर। हर चुनाव अपने समय में उचित था, पर मिलकर उन्होंने ऐसा जाल छोड़ा जिसमें अलग-अलग गेज की लाइनों के बीच जाने वाले माल को हाथ से उतारना और फिर लादना पड़ता था, जो धीमा और महँगा काम था। एक बार किसी गेज पर हज़ारों किलोमीटर पटरी, और उस पर चलने वाले इंजन और डिब्बे बन जाने पर उसे बदलना बेहद महँगा था, इसलिए मिश्रित जाल एक शताब्दी से भी अधिक समय तक बना रहा। केवल 1992 में भारतीय रेल ने प्रोजेक्ट यूनीगेज शुरू किया, मीटर और नैरो गेज लाइनों को बड़ी लाइन में बदलने का एक लंबा कार्यक्रम। अर्थशास्त्री ऐसे मामलों को पथ-निर्भरता कहते हैं: अपने समय के अनुकूल कोई चुनाव, अपने इर्द-गिर्द बने निवेशों को आकर्षित करके, एक ऐसा ढर्रा जमा सकता है जिसे बाद की पीढ़ियाँ कभी न चुनतीं।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["The metre gauge lines were built because the government expected them to be replaced by broad gauge soon.", "Moving goods between lines of different gauges added both time and cost to their journey."], "statements_hi": ["मीटर गेज लाइनें इसलिए बनाई गईं कि सरकार को आशा थी कि उन्हें जल्द ही बड़ी लाइन से बदल दिया जाएगा।", "अलग-अलग गेज की लाइनों के बीच माल ले जाने से उसकी यात्रा में समय और लागत दोनों बढ़ते थे।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "precision", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p08", "csat_order": 67}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is valid. The passage says goods moving between gauges had to be unloaded and reloaded by hand, ''a slow and costly business''. 1 is not supported: the passage says the metre gauge was adopted to save money, and nothing suggests that the government expected the lines to be replaced soon -- the mixed network in fact lasted more than a century.','केवल 2 वैध है। परिच्छेद कहता है कि अलग-अलग गेज के बीच जाने वाले माल को हाथ से उतारना और फिर लादना पड़ता था, ''जो धीमा और महँगा काम था''। 1 समर्थित नहीं है: परिच्छेद कहता है कि मीटर गेज पैसा बचाने के लिए अपनाई गई, और कुछ भी यह नहीं बताता कि सरकार को लाइनों के जल्द बदले जाने की आशा थी -- वास्तव में मिश्रित जाल एक शताब्दी से अधिक चला।','csat-l4-s04-rc-p08-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','easy','A train covers 1 km in 45 seconds. What is its speed?','एक रेलगाड़ी 1 किमी, 45 सेकंड में तय करती है। उसकी चाल क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 68}'::jsonb,'[{"id": "a", "body": "80 km/h", "body_hi": "80 किमी/घंटा", "isCorrect": true}, {"id": "b", "body": "90 km/h", "body_hi": "90 किमी/घंटा", "isCorrect": false}, {"id": "c", "body": "120 km/h", "body_hi": "120 किमी/घंटा", "isCorrect": false}, {"id": "d", "body": "135 km/h", "body_hi": "135 किमी/घंटा", "isCorrect": false}]'::jsonb,2.5,0.83,'An hour has 3,600 seconds, so the train covers 3,600 ÷ 45 = 80 km in an hour: 80 km/h. 135 km/h multiplies 45 by 3; 90 and 120 km/h would need 40 and 30 seconds a kilometre.','एक घंटे में 3,600 सेकंड होते हैं, इसलिए रेलगाड़ी एक घंटे में 3,600 ÷ 45 = 80 किमी चलती है: 80 किमी/घंटा। 135 किमी/घंटा, 45 को 3 से गुणा करता है; 90 और 120 किमी/घंटा के लिए प्रति किलोमीटर 40 और 30 सेकंड चाहिए।','csat-l4-s04-qa-sdt-a-kilometre-in-45-seconds','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','hard','Six people -- P, Q, R, S, T and U -- sit at a round table with seven chairs, all facing the centre, so that one chair is empty. The empty chair is to P''s immediate left. Q sits second to P''s right. T sits next to the empty chair. R does not sit next to Q, and S does not sit next to P. Which one of the following pairs sit next to each other?','छह लोग -- P, Q, R, S, T और U -- सात कुर्सियों वाली एक गोल मेज़ पर, सभी केंद्र की ओर मुख करके, ऐसे बैठे हैं कि एक कुर्सी ख़ाली है। ख़ाली कुर्सी P के ठीक बाईं ओर है। Q, P के दाईं ओर दूसरे स्थान पर बैठा है। T ख़ाली कुर्सी के बगल में बैठा है। R, Q के बगल में नहीं बैठा, और S, P के बगल में नहीं बैठा। निम्नलिखित में से कौन-सा जोड़ा एक-दूसरे के बगल में बैठा है?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 69}'::jsonb,'[{"id": "a", "body": "P and T", "body_hi": "P और T", "isCorrect": false}, {"id": "b", "body": "S and U", "body_hi": "S और U", "isCorrect": false}, {"id": "c", "body": "R and T", "body_hi": "R और T", "isCorrect": true}, {"id": "d", "body": "Q and R", "body_hi": "Q और R", "isCorrect": false}]'::jsonb,2.5,0.83,'Go round the table from P towards P''s left: first the empty chair, then the chair beyond it. T must sit next to the empty chair, whose other neighbour is P, so T takes the chair beyond it. Going the other way from P, the chair at P''s right is followed by Q''s. That leaves the chair between Q and P and the two chairs between T and Q for R, S and U. R must not be next to Q, so R takes the chair next to T. S must not be next to P, so S takes the chair between R and Q, and U the chair between Q and P. So R and T are neighbours. P and T are not, as the empty chair lies between them; S and U are separated by Q; and R is kept away from Q by the clue itself.','P से P के बाईं ओर मेज़ पर घूमिए: पहले ख़ाली कुर्सी, फिर उसके आगे की कुर्सी। T को ख़ाली कुर्सी के बगल में बैठना है, जिसका दूसरा पड़ोसी P है, इसलिए T उसके आगे वाली कुर्सी लेता है। P से दूसरी ओर जाने पर, P के दाईं ओर वाली कुर्सी के बाद Q की कुर्सी है। इससे Q और P के बीच की कुर्सी और T और Q के बीच की दो कुर्सियाँ R, S और U के लिए बचती हैं। R को Q के बगल में नहीं होना है, इसलिए R, T के बगल वाली कुर्सी लेता है। S को P के बगल में नहीं होना है, इसलिए S, R और Q के बीच की कुर्सी लेता है, और U, Q और P के बीच की। अतः R और T पड़ोसी हैं। P और T नहीं, क्योंकि उनके बीच ख़ाली कुर्सी है; S और U को Q अलग करता है; और R को Q से स्वयं संकेत ही दूर रखता है।','csat-l4-s04-lr-sa-a-round-table-of-seven-chairs-one-left-empty','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','What is the largest four-digit number that leaves a remainder of 2 when divided by 13?','चार अंकों की वह सबसे बड़ी संख्या कौन-सी है जो 13 से भाग देने पर शेषफल 2 छोड़ती है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 70}'::jsonb,'[{"id": "a", "body": "9984", "body_hi": "9984", "isCorrect": false}, {"id": "b", "body": "9986", "body_hi": "9986", "isCorrect": false}, {"id": "c", "body": "9997", "body_hi": "9997", "isCorrect": false}, {"id": "d", "body": "9999", "body_hi": "9999", "isCorrect": true}]'::jsonb,2.5,0.83,'Start from the largest four-digit number: 9999 = 13 × 769 + 2, so 9999 itself leaves remainder 2. 9997 is the largest four-digit multiple of 13; 9984 is the multiple before it; 9986 adds the 2 to that smaller multiple, stepping back a whole 13 too far.','चार अंकों की सबसे बड़ी संख्या से शुरू कीजिए: 9999 = 13 × 769 + 2, इसलिए स्वयं 9999 शेष 2 छोड़ती है। 9997, चार अंकों का सबसे बड़ा 13 का गुणज है; 9984 उससे पहले का गुणज है; 9986 उस छोटे गुणज में 2 जोड़ता है, एक पूरा 13 ज़्यादा पीछे जाकर।','csat-l4-s04-qa-nt-the-largest-four-digit-number-leaving-2-by-13','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','medium','A person owns 60 per cent of a company, and that company owns 40 per cent of a second company. What share of the second company does the person own indirectly?','एक व्यक्ति किसी कंपनी का 60 प्रतिशत स्वामी है, और वह कंपनी एक दूसरी कंपनी की 40 प्रतिशत स्वामी है। दूसरी कंपनी में उस व्यक्ति का अप्रत्यक्ष हिस्सा कितना है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 71}'::jsonb,'[{"id": "a", "body": "20 per cent", "body_hi": "20 प्रतिशत", "isCorrect": false}, {"id": "b", "body": "24 per cent", "body_hi": "24 प्रतिशत", "isCorrect": true}, {"id": "c", "body": "40 per cent", "body_hi": "40 प्रतिशत", "isCorrect": false}, {"id": "d", "body": "100 per cent", "body_hi": "100 प्रतिशत", "isCorrect": false}]'::jsonb,2.5,0.83,'The person owns 60 per cent of the company''s 40 per cent stake: 0.6 × 0.4 = 0.24, that is 24 per cent. 40 per cent treats the person as owning the whole of the company''s stake; 100 per cent assumes control means full ownership; 20 per cent subtracts 40 from 60.','व्यक्ति कंपनी के 40 प्रतिशत हिस्से का 60 प्रतिशत स्वामी है: 0.6 × 0.4 = 0.24, यानी 24 प्रतिशत। 40 प्रतिशत व्यक्ति को कंपनी के पूरे हिस्से का स्वामी मानता है; 100 प्रतिशत मान लेता है कि नियंत्रण का अर्थ पूर्ण स्वामित्व है; 20 प्रतिशत, 60 में से 40 घटाता है।','csat-l4-s04-qa-pp-a-stake-held-through-a-company','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','hard','A shop gives one chocolate in exchange for every 3 empty wrappers. A child buys 15 chocolates, eats them all, and keeps exchanging the wrappers -- including those of the chocolates got in exchange -- for as long as she can. How many chocolates does she eat in all?','एक दुकान हर 3 ख़ाली रैपरों के बदले एक चॉकलेट देती है। एक बच्ची 15 चॉकलेट ख़रीदती है, सब खा लेती है, और जब तक हो सके रैपर बदलती रहती है -- बदले में मिली चॉकलेटों के रैपर भी। वह कुल कितनी चॉकलेट खाती है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 72}'::jsonb,'[{"id": "a", "body": "20", "body_hi": "20", "isCorrect": false}, {"id": "b", "body": "21", "body_hi": "21", "isCorrect": false}, {"id": "c", "body": "22", "body_hi": "22", "isCorrect": true}, {"id": "d", "body": "23", "body_hi": "23", "isCorrect": false}]'::jsonb,2.5,0.83,'15 wrappers buy 5 chocolates, leaving 5 wrappers; those buy 1 more, leaving 2 + 1 = 3 wrappers; those buy 1 more, leaving 1. In all 15 + 5 + 1 + 1 = 22. 20 stops after the first exchange; 21 after the second; 23 assumes the last single wrapper can still be used.','15 रैपरों से 5 चॉकलेट मिलती हैं, 5 रैपर बचते हैं; उनसे 1 और, 2 + 1 = 3 रैपर बचते हैं; उनसे 1 और, 1 बचता है। कुल 15 + 5 + 1 + 1 = 22। 20 पहले बदलाव के बाद रुक जाता है; 21 दूसरे के बाद; 23 मान लेता है कि अंतिम अकेला रैपर भी काम आ सकता है।','csat-l4-s04-qa-ph-chocolates-bought-with-wrappers','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Moving the draft Constitution in the Constituent Assembly in November 1948, B. R. Ambedkar borrowed a phrase from the historian George Grote: constitutional morality. By it he meant a deep respect for the forms of the constitution -- a habit of working through its procedures and accepting their limits, even when one is strong enough to brush them aside. Such a habit, he warned, is not a natural sentiment; it has to be cultivated, and he doubted that it was yet widespread in India. That doubt explains a feature of the document that is often criticised: its length. Ambedkar defended including details of administration, which other constitutions leave to ordinary law, on the ground that where constitutional morality is weak it is possible to pervert a constitution without changing its form, simply by changing the way it is administered. Writing more into the text narrows the room for such perversion. But no text can close it entirely. A constitution can lay down procedures; whether they are honoured depends on those who work them.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
नवंबर 1948 में संविधान सभा में संविधान का प्रारूप प्रस्तुत करते हुए बी. आर. आंबेडकर ने इतिहासकार जॉर्ज ग्रोट से एक पद उधार लिया: संवैधानिक नैतिकता। इससे उनका आशय संविधान के रूपों के प्रति गहरे सम्मान से था -- उसकी प्रक्रियाओं के माध्यम से काम करने और उनकी सीमाओं को स्वीकार करने की आदत, तब भी जब कोई उन्हें किनारे कर देने लायक़ शक्तिशाली हो। उन्होंने चेताया कि ऐसी आदत कोई स्वाभाविक भावना नहीं है; उसे विकसित करना पड़ता है, और उन्हें संदेह था कि वह भारत में अभी व्यापक है। यही संदेह इस दस्तावेज़ की एक ऐसी विशेषता को समझाता है जिसकी प्रायः आलोचना होती है: उसकी लंबाई। आंबेडकर ने प्रशासन के उन विवरणों को शामिल करने का बचाव किया जिन्हें अन्य संविधान साधारण क़ानून पर छोड़ देते हैं, इस आधार पर कि जहाँ संवैधानिक नैतिकता कमज़ोर हो वहाँ संविधान का रूप बदले बिना, केवल उसके प्रशासन का ढंग बदलकर, उसे विकृत करना संभव है। पाठ में अधिक लिखना ऐसी विकृति की गुंजाइश को कम करता है। पर कोई भी पाठ उसे पूरी तरह बंद नहीं कर सकता। संविधान प्रक्रियाएँ निर्धारित कर सकता है; उनका सम्मान होगा या नहीं, यह उन पर निर्भर है जो उन्हें चलाते हैं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p09", "csat_order": 73}'::jsonb,'[{"id": "a", "body": "A long and detailed constitution makes the habit of constitutional morality unnecessary.", "body_hi": "एक लंबा और विस्तृत संविधान संवैधानिक नैतिकता की आदत को अनावश्यक बना देता है।", "isCorrect": false}, {"id": "b", "body": "Ambedkar wrote administrative detail into the Constitution because respect for its forms was not yet secure.", "body_hi": "आंबेडकर ने संविधान में प्रशासनिक विवरण इसलिए लिखे कि उसके रूपों के प्रति सम्मान अभी सुरक्षित नहीं था।", "isCorrect": true}, {"id": "c", "body": "Constitutional morality comes naturally to any people that adopts a democratic constitution.", "body_hi": "संवैधानिक नैतिकता लोकतांत्रिक संविधान अपनाने वाले किसी भी समाज में स्वाभाविक रूप से आ जाती है।", "isCorrect": false}, {"id": "d", "body": "Ambedkar thought the draft Constitution too long and wanted its administrative details left to ordinary law.", "body_hi": "आंबेडकर प्रारूप संविधान को बहुत लंबा मानते थे और चाहते थे कि उसके प्रशासनिक विवरण साधारण क़ानून पर छोड़ दिए जाएँ।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage explains that Ambedkar wrote administrative detail into the Constitution because respect for its forms was not yet widespread, and it adds that such detail narrows, but cannot close, the room for abuse. It ends by saying that no text can close that room and that everything depends on those who work the procedures, so detail does not make constitutional morality unnecessary; Ambedkar called that morality something to be cultivated, not natural; and he defended the length rather than calling for it to be cut.','परिच्छेद बताता है कि आंबेडकर ने संविधान में प्रशासनिक विवरण इसलिए लिखे कि उसके रूपों के प्रति सम्मान अभी व्यापक नहीं था, और जोड़ता है कि ऐसे विवरण दुरुपयोग की गुंजाइश को कम करते हैं, पर बंद नहीं कर सकते। वह यह कहकर समाप्त होता है कि कोई पाठ उस गुंजाइश को बंद नहीं कर सकता और सब कुछ प्रक्रियाएँ चलाने वालों पर निर्भर है, इसलिए विवरण संवैधानिक नैतिकता को अनावश्यक नहीं बनाते; आंबेडकर ने उस नैतिकता को विकसित की जाने वाली चीज़ कहा, स्वाभाविक नहीं; और उन्होंने लंबाई का बचाव किया, उसे घटाने की माँग नहीं की।','csat-l4-s04-rc-p09-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Moving the draft Constitution in the Constituent Assembly in November 1948, B. R. Ambedkar borrowed a phrase from the historian George Grote: constitutional morality. By it he meant a deep respect for the forms of the constitution -- a habit of working through its procedures and accepting their limits, even when one is strong enough to brush them aside. Such a habit, he warned, is not a natural sentiment; it has to be cultivated, and he doubted that it was yet widespread in India. That doubt explains a feature of the document that is often criticised: its length. Ambedkar defended including details of administration, which other constitutions leave to ordinary law, on the ground that where constitutional morality is weak it is possible to pervert a constitution without changing its form, simply by changing the way it is administered. Writing more into the text narrows the room for such perversion. But no text can close it entirely. A constitution can lay down procedures; whether they are honoured depends on those who work them.

Which one of the following would be an example of perverting a constitution ''without changing its form'', in the sense the passage uses?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
नवंबर 1948 में संविधान सभा में संविधान का प्रारूप प्रस्तुत करते हुए बी. आर. आंबेडकर ने इतिहासकार जॉर्ज ग्रोट से एक पद उधार लिया: संवैधानिक नैतिकता। इससे उनका आशय संविधान के रूपों के प्रति गहरे सम्मान से था -- उसकी प्रक्रियाओं के माध्यम से काम करने और उनकी सीमाओं को स्वीकार करने की आदत, तब भी जब कोई उन्हें किनारे कर देने लायक़ शक्तिशाली हो। उन्होंने चेताया कि ऐसी आदत कोई स्वाभाविक भावना नहीं है; उसे विकसित करना पड़ता है, और उन्हें संदेह था कि वह भारत में अभी व्यापक है। यही संदेह इस दस्तावेज़ की एक ऐसी विशेषता को समझाता है जिसकी प्रायः आलोचना होती है: उसकी लंबाई। आंबेडकर ने प्रशासन के उन विवरणों को शामिल करने का बचाव किया जिन्हें अन्य संविधान साधारण क़ानून पर छोड़ देते हैं, इस आधार पर कि जहाँ संवैधानिक नैतिकता कमज़ोर हो वहाँ संविधान का रूप बदले बिना, केवल उसके प्रशासन का ढंग बदलकर, उसे विकृत करना संभव है। पाठ में अधिक लिखना ऐसी विकृति की गुंजाइश को कम करता है। पर कोई भी पाठ उसे पूरी तरह बंद नहीं कर सकता। संविधान प्रक्रियाएँ निर्धारित कर सकता है; उनका सम्मान होगा या नहीं, यह उन पर निर्भर है जो उन्हें चलाते हैं।

निम्नलिखित में से कौन-सा, परिच्छेद में प्रयुक्त अर्थ में, संविधान को ''उसका रूप बदले बिना'' विकृत करने का उदाहरण होगा?','{"craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p09", "csat_order": 74}'::jsonb,'[{"id": "a", "body": "A government that keeps all procedures on paper but fills the bodies that check it with loyalists", "body_hi": "ऐसी सरकार जो काग़ज़ पर सब प्रक्रियाएँ रखती है पर अंकुश वाले निकायों में निष्ठावान भर देती है", "isCorrect": true}, {"id": "b", "body": "Amending the constitution by the very procedure that it lays down, after an open debate in the legislature", "body_hi": "विधायिका में खुली बहस के बाद संविधान को उसी की निर्धारित की गई प्रक्रिया के अनुसार संशोधित करना", "isCorrect": false}, {"id": "c", "body": "A court striking down a law because it conflicts with a provision of the constitution", "body_hi": "किसी न्यायालय द्वारा किसी क़ानून को इसलिए रद्द करना कि वह संविधान के किसी प्रावधान के विरुद्ध है", "isCorrect": false}, {"id": "d", "body": "Abolishing the legislature by decree and governing without it until further notice", "body_hi": "एक आदेश द्वारा विधायिका को समाप्त कर देना और अगली सूचना तक उसके बिना ही शासन चलाना", "isCorrect": false}]'::jsonb,2.5,0.83,'Perverting a constitution without changing its form means leaving every procedure in place on paper while administering it against its spirit. A government that keeps the forms but fills the bodies meant to check it with its own loyalists does exactly that. Amending the constitution by its own procedure after open debate is working through its forms, not perverting them; a court striking down an unconstitutional law is a check doing its job; and abolishing the legislature by decree changes the form itself.','संविधान को उसका रूप बदले बिना विकृत करने का अर्थ है काग़ज़ पर हर प्रक्रिया को बनाए रखते हुए उसे उसकी भावना के विरुद्ध चलाना। ऐसी सरकार जो रूपों को बनाए रखती है पर उस पर अंकुश रखने वाले निकायों को अपने निष्ठावानों से भर देती है, ठीक यही करती है। खुली बहस के बाद संविधान को उसकी अपनी प्रक्रिया से संशोधित करना उसके रूपों के माध्यम से काम करना है, उन्हें विकृत करना नहीं; असंवैधानिक क़ानून को रद्द करने वाला न्यायालय एक अंकुश है जो अपना काम कर रहा है; और आदेश द्वारा विधायिका को समाप्त करना स्वयं रूप को बदलता है।','csat-l4-s04-rc-p09-perverting-without-changing-the-form','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Assumption','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Moving the draft Constitution in the Constituent Assembly in November 1948, B. R. Ambedkar borrowed a phrase from the historian George Grote: constitutional morality. By it he meant a deep respect for the forms of the constitution -- a habit of working through its procedures and accepting their limits, even when one is strong enough to brush them aside. Such a habit, he warned, is not a natural sentiment; it has to be cultivated, and he doubted that it was yet widespread in India. That doubt explains a feature of the document that is often criticised: its length. Ambedkar defended including details of administration, which other constitutions leave to ordinary law, on the ground that where constitutional morality is weak it is possible to pervert a constitution without changing its form, simply by changing the way it is administered. Writing more into the text narrows the room for such perversion. But no text can close it entirely. A constitution can lay down procedures; whether they are honoured depends on those who work them.

Which of the following assumptions has/have been made in the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
नवंबर 1948 में संविधान सभा में संविधान का प्रारूप प्रस्तुत करते हुए बी. आर. आंबेडकर ने इतिहासकार जॉर्ज ग्रोट से एक पद उधार लिया: संवैधानिक नैतिकता। इससे उनका आशय संविधान के रूपों के प्रति गहरे सम्मान से था -- उसकी प्रक्रियाओं के माध्यम से काम करने और उनकी सीमाओं को स्वीकार करने की आदत, तब भी जब कोई उन्हें किनारे कर देने लायक़ शक्तिशाली हो। उन्होंने चेताया कि ऐसी आदत कोई स्वाभाविक भावना नहीं है; उसे विकसित करना पड़ता है, और उन्हें संदेह था कि वह भारत में अभी व्यापक है। यही संदेह इस दस्तावेज़ की एक ऐसी विशेषता को समझाता है जिसकी प्रायः आलोचना होती है: उसकी लंबाई। आंबेडकर ने प्रशासन के उन विवरणों को शामिल करने का बचाव किया जिन्हें अन्य संविधान साधारण क़ानून पर छोड़ देते हैं, इस आधार पर कि जहाँ संवैधानिक नैतिकता कमज़ोर हो वहाँ संविधान का रूप बदले बिना, केवल उसके प्रशासन का ढंग बदलकर, उसे विकृत करना संभव है। पाठ में अधिक लिखना ऐसी विकृति की गुंजाइश को कम करता है। पर कोई भी पाठ उसे पूरी तरह बंद नहीं कर सकता। संविधान प्रक्रियाएँ निर्धारित कर सकता है; उनका सम्मान होगा या नहीं, यह उन पर निर्भर है जो उन्हें चलाते हैं।

परिच्छेद में निम्नलिखित में से कौन-सी पूर्वधारणा/एँ बनाई गई है/हैं?','{"statements": ["Rules written into a constitution are harder to change or ignore than rules left to ordinary law.", "A constitution that includes enough administrative detail will be honoured by whoever comes to work it."], "statements_hi": ["संविधान में लिखे गए नियमों को साधारण क़ानून पर छोड़े गए नियमों की तुलना में बदलना या अनदेखा करना कठिन है।", "पर्याप्त प्रशासनिक विवरण वाले संविधान का सम्मान वह हर व्यक्ति करेगा जो उसे चलाने आए।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s04", "passage_group": "csat-l4-s04-p09", "csat_order": 75}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 1 is assumed. The claim that writing more into the text ''narrows the room'' for perversion takes for granted that rules placed in the constitution are harder to change or ignore than rules left to ordinary law. 2 is not assumed; the passage denies it, saying no text can close the room entirely and that whether procedures are honoured depends on those who work them.','केवल 1 पूर्वधारणा है। यह दावा कि पाठ में अधिक लिखना विकृति की ''गुंजाइश को कम करता है'', यह मानकर चलता है कि संविधान में रखे गए नियमों को साधारण क़ानून पर छोड़े गए नियमों की तुलना में बदलना या अनदेखा करना कठिन है। 2 पूर्वधारणा नहीं है; परिच्छेद उसका खंडन करता है, यह कहते हुए कि कोई पाठ गुंजाइश को पूरी तरह बंद नहीं कर सकता और प्रक्रियाओं का सम्मान उन्हें चलाने वालों पर निर्भर है।','csat-l4-s04-rc-p09-assumptions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','medium','''A fair coin has come up heads in each of its last five tosses, so the next toss is more likely to come up tails.'' Which one of the following best describes the flaw in this reasoning?','''एक निष्पक्ष सिक्का अपनी पिछली पाँचों उछालों में चित आया है, इसलिए अगली उछाल में पट आने की संभावना अधिक है।'' निम्नलिखित में से कौन-सा इस तर्क की त्रुटि का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s04", "csat_order": 76}'::jsonb,'[{"id": "a", "body": "It takes the coin to be fair without first testing it over a large number of tosses.", "body_hi": "यह बहुत-सी उछालों में जाँचे बिना ही सिक्के को निष्पक्ष मान लेता है।", "isCorrect": false}, {"id": "b", "body": "It draws a conclusion about every coin from what happened with a single coin.", "body_hi": "यह एक ही सिक्के के साथ हुई घटना से हर सिक्के के बारे में निष्कर्ष निकाल लेता है।", "isCorrect": false}, {"id": "c", "body": "It treats the coin''s past tosses as if they could change the chance of the next one.", "body_hi": "यह सिक्के की पिछली उछालों को ऐसे लेता है मानो वे अगली उछाल की संभावना बदल सकती हों।", "isCorrect": true}, {"id": "d", "body": "It assumes that what is true of each toss must be true of the five tosses together.", "body_hi": "यह मान लेता है कि जो हर उछाल के लिए सत्य है वह पाँचों उछालों के लिए मिलाकर भी सत्य होगा।", "isCorrect": false}]'::jsonb,2.5,0.83,'Each toss of a fair coin is independent: the coin has no memory, so heads and tails stay equally likely on the sixth toss whatever came before. Five heads in a row was unlikely before it happened (1 in 32), but once it has happened it says nothing about the next toss. The argument states that the coin is fair, so it does not take that on trust as a flaw; it generalises to no other coin; and it does not reason from the parts to the whole.','निष्पक्ष सिक्के की हर उछाल स्वतंत्र है: सिक्के की कोई स्मृति नहीं होती, इसलिए पहले चाहे जो हुआ हो, छठी उछाल में चित और पट समान रूप से संभावित रहते हैं। लगातार पाँच चित होना घटित होने से पहले असंभावित था (32 में 1), पर घटित हो जाने के बाद वह अगली उछाल के बारे में कुछ नहीं कहता। तर्क स्वयं कहता है कि सिक्का निष्पक्ष है, इसलिए उसे बिना जाँचे मानना त्रुटि नहीं; वह किसी अन्य सिक्के पर सामान्यीकरण नहीं करता; और वह अंशों से पूर्ण की ओर तर्क नहीं करता।','csat-l4-s04-lr-sc-a-coin-thought-to-be-due-for-tails','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','What is the value of (-1)¹ + (-1)² + (-1)³ + ... + (-1)⁹⁹?','(-1)¹ + (-1)² + (-1)³ + ... + (-1)⁹⁹ का मान क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 77}'::jsonb,'[{"id": "a", "body": "-1", "body_hi": "-1", "isCorrect": true}, {"id": "b", "body": "0", "body_hi": "0", "isCorrect": false}, {"id": "c", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "d", "body": "99", "body_hi": "99", "isCorrect": false}]'::jsonb,2.5,0.83,'The terms are -1, +1, -1, +1, ...: each pair of a -1 and the +1 after it adds to 0. The first 98 terms make 49 such pairs, adding to 0, and the 99th term, an odd power, is -1. So the sum is -1. 0 forgets that 99 terms cannot all be paired; 1 and 99 have no basis.','पद -1, +1, -1, +1, ... हैं: हर -1 और उसके बाद का +1 मिलकर 0 बनाते हैं। पहले 98 पद ऐसे 49 जोड़े बनाते हैं, जिनका योग 0 है, और 99वाँ पद, एक विषम घात, -1 है। अतः योग -1 है। 0 यह भूल जाता है कि 99 पदों के सब जोड़े नहीं बन सकते; 1 और 99 का कोई आधार नहीं।','csat-l4-s04-qa-nt-a-sum-of-minus-one-powers','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','medium','₹5,000 earns compound interest at 10 per cent a year for 2 years. At what rate of simple interest would the same sum earn the same interest in the same 2 years?','₹5,000 पर 2 वर्षों के लिए 10 प्रतिशत वार्षिक चक्रवृद्धि ब्याज मिलता है। साधारण ब्याज की किस दर पर वही राशि उन्हीं 2 वर्षों में उतना ही ब्याज कमाएगी?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 78}'::jsonb,'[{"id": "a", "body": "10.5 per cent", "body_hi": "10.5 प्रतिशत", "isCorrect": true}, {"id": "b", "body": "11 per cent", "body_hi": "11 प्रतिशत", "isCorrect": false}, {"id": "c", "body": "12 per cent", "body_hi": "12 प्रतिशत", "isCorrect": false}, {"id": "d", "body": "21 per cent", "body_hi": "21 प्रतिशत", "isCorrect": false}]'::jsonb,2.5,0.83,'Compound interest for 2 years at 10 per cent is 5,000 × (1.1² - 1) = 5,000 × 0.21 = ₹1,050. Simple interest of ₹1,050 on ₹5,000 over 2 years means ₹525 a year, that is 10.5 per cent. 21 per cent is the total over the two years, not a yearly rate; 11 and 12 per cent have no basis.','10 प्रतिशत पर 2 वर्षों का चक्रवृद्धि ब्याज 5,000 × (1.1² - 1) = 5,000 × 0.21 = ₹1,050 है। ₹5,000 पर 2 वर्षों में ₹1,050 साधारण ब्याज का अर्थ है प्रति वर्ष ₹525, यानी 10.5 प्रतिशत। 21 प्रतिशत दोनों वर्षों का कुल है, वार्षिक दर नहीं; 11 और 12 प्रतिशत का कोई आधार नहीं।','csat-l4-s04-qa-pp-simple-interest-matched-to-compound','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','In a village market, 3 apples can be exchanged for 2 oranges, and 4 oranges for 5 bananas. How many apples can be exchanged for 10 bananas?','एक गाँव के बाज़ार में 3 सेब के बदले 2 संतरे, और 4 संतरों के बदले 5 केले मिलते हैं। 10 केलों के बदले कितने सेब मिल सकते हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 79}'::jsonb,'[{"id": "a", "body": "12", "body_hi": "12", "isCorrect": true}, {"id": "b", "body": "15", "body_hi": "15", "isCorrect": false}, {"id": "c", "body": "18", "body_hi": "18", "isCorrect": false}, {"id": "d", "body": "20", "body_hi": "20", "isCorrect": false}]'::jsonb,2.5,0.83,'10 bananas are worth 10 × 4/5 = 8 oranges, and each orange is worth 3/2 of an apple, so 8 oranges are worth 12 apples. 15 multiplies 10 by 3/2 and skips the oranges; 18 and 20 turn one of the ratios upside down.','10 केले 10 × 4/5 = 8 संतरों के बराबर हैं, और हर संतरा 3/2 सेब के बराबर है, इसलिए 8 संतरे 12 सेब के बराबर हैं। 15, 10 को 3/2 से गुणा करता है और संतरों का चरण छोड़ देता है; 18 और 20 किसी एक अनुपात को उलट देते हैं।','csat-l4-s04-qa-rm-a-barter-chain','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Cube Painting','mcq','medium','Each of the eight corners of a solid cube is sliced off with a small flat cut, so that every corner is replaced by a small triangular face and no two cuts meet. How many edges does the new solid have?','एक ठोस घन के आठों कोनों में से हर एक को एक छोटे समतल कट से काट दिया जाता है, जिससे हर कोने की जगह एक छोटा त्रिभुजाकार फलक बन जाता है और कोई दो कट आपस में नहीं मिलते। नए ठोस के कितने किनारे (कोर) हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s04", "csat_order": 80}'::jsonb,'[{"id": "a", "body": "20", "body_hi": "20", "isCorrect": false}, {"id": "b", "body": "24", "body_hi": "24", "isCorrect": false}, {"id": "c", "body": "30", "body_hi": "30", "isCorrect": false}, {"id": "d", "body": "36", "body_hi": "36", "isCorrect": true}]'::jsonb,2.5,0.83,'The cube''s 12 edges all remain, only shorter. Each cut adds a triangle, and a triangle has 3 edges of its own, so the 8 cuts add 8 × 3 = 24 edges. In all 12 + 24 = 36. As a check, the new solid has 24 corners (3 for each triangle) and 6 + 8 = 14 faces, and 24 - 36 + 14 = 2, as Euler''s formula requires. 24 counts only the new edges; 20 adds the 8 cuts to the 12 old edges; 30 has no basis.','घन के सभी 12 किनारे बने रहते हैं, केवल छोटे हो जाते हैं। हर कट एक त्रिभुज जोड़ता है, और त्रिभुज के अपने 3 किनारे होते हैं, इसलिए 8 कट 8 × 3 = 24 किनारे जोड़ते हैं। कुल 12 + 24 = 36। जाँच के लिए, नए ठोस के 24 शीर्ष (हर त्रिभुज के 3) और 6 + 8 = 14 फलक हैं, और 24 - 36 + 14 = 2, जैसा ऑयलर का सूत्र माँगता है। 24 केवल नए किनारे गिनता है; 20, 12 पुराने किनारों में 8 कट जोड़ता है; 30 का कोई आधार नहीं।','csat-l4-s04-lr-cp-a-cube-with-its-corners-sliced-off','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft')
returning concept_group_id;
